-- ============================================================================
-- Las 48 recetas, de los JSON del repo a `charcu.recetario` (2026-10-07)
--
-- GENERADA, no escrita a mano: el contenido de cada receta es el JSON que
-- vivía en `src/entities/recipe/recipes/` (se borran en este mismo cambio; la
-- historia queda en git). El orden es el que tenía `recipes.ts`.
--
-- Lo que NO venía en los JSON y se decidió aquí:
--   · `category`: los cinco ids de `courses.category`, alineados con el curso
--     cuando la receta lo tiene (longaniza → embutidos-frescos, como su curso).
--   · `capsule_slug`: la cápsula con la que termina la receta. Embutidos →
--     "Formas de embutir un chorizo"; piezas que se bridan → "Cómo bridar un
--     jamón"; el resto de curados → "Qué saber de la sal de cura"; quesos, ninguna.
--   · `course_slug`: NO se escribe a mano. Al final se enlaza con el curso del
--     mismo slug, si existe (es la relación que ya usaban las páginas).
-- ============================================================================

on conflict (slug) do update set
  name = excluded.name, category = excluded.category, tags = excluded.tags,
  image = excluded.image, origin = excluded.origin, capsule_slug = excluded.capsule_slug,
  content = excluded.content, position = excluded.position, updated_at = now();

-- La receta → su curso: el que comparte slug (publicado o en lista de espera).
update charcu.recetario r
   set course_slug = c.slug
  from charcu.courses c
 where c.slug = r.slug
   and c.kind = 'curso';
