insert into charcu.recetario
  (slug, name, category, tags, image, origin, capsule_slug, content, position)
values
  ('longaniza-colombiana', 'Longaniza Colombiana Artesanal', 'embutidos-frescos', '{"Colombia","Fresco","Parrillero"}', '/recipes/longaniza-colombiana.jpg', 'Colombia · 1 kg', 'embutir-un-chorizo', $receta${"slug":"longaniza-colombiana","name":"Longaniza Colombiana Artesanal","description":"Embutido fresco tradicional — carne y grasa en equilibrio, comino, paprika y orégano medidos.","image":"/recipes/longaniza-colombiana.jpg","tags":["Colombia","Fresco","Parrillero"],"eyebrow":"Receta · El camino del charcutero","subtitle":"Receta base para elaboración artesanal.","intro":"La longaniza colombiana es uno de los embutidos frescos más tradicionales del país. Su equilibrio entre carne, grasa y especias da como resultado un producto jugoso, con excelente textura y un sabor intenso que la convierte en una de las recetas esenciales de la charcutería artesanal. Cada lote cuenta la misma historia: técnica, paciencia y respeto por la materia prima.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Embutido fresco"},{"label":"Nivel","value":"Intermedio"},{"label":"Tiempo de preparación","value":"45 min"},{"label":"Tiempo de reposo","value":"12–24 h"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 32–35 mm"}],"details":[{"title":"Origen","description":"Pierna o paleta de cerdo, molida gruesa para conservar mordida."},{"title":"Textura","description":"200 g de grasa firme por cada kilo aportan jugosidad sin perder firmeza al corte."},{"title":"Sabor","description":"Comino, paprika y orégano, en dosis medidas, sin dominar la carne."}],"quote":"El Charcu no improvisa. Cada receta es una fórmula probada, pensada para repetirse con el mismo resultado — lote tras lote.","ingredientsNote":"Toda buena longaniza empieza en la báscula, no en la sartén: pesar cada ingrediente con precisión es lo que separa un embutido consistente de uno improvisado.","ingredients":[{"name":"Carne de cerdo (pierna o paleta)","amount":"800 g","pct":"80%"},{"name":"Grasa de cerdo (papada o tocino)","amount":"200 g","pct":"20%"},{"name":"Sal","amount":"18 g","pct":"1.8%"},{"name":"Ajo fresco triturado","amount":"4 g","pct":"0.4%"},{"name":"Pimienta negra","amount":"2.4 g","pct":"0.24%"},{"name":"Comino","amount":"3 g","pct":"0.3%"},{"name":"Paprika dulce o achiote","amount":"3 g","pct":"0.3%"},{"name":"Orégano seco","amount":"1 g","pct":"0.1%"},{"name":"Azúcar","amount":"1 g","pct":"0.1%"},{"name":"Agua helada","amount":"20 ml","pct":"2%"}],"proportionNote":"80% carne y 20% grasa (800 g y 200 g por cada kilo) es el punto de partida clásico de la longaniza. Puedes mover ese balance uno o dos puntos porcentuales según la jugosidad que busques, sin salirte del rango artesanal.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. Es la misma proporción sin importar si haces 1 kilo o 20: domínala y podrás escalar esta longaniza a cualquier cantidad sin perder el equilibrio.","steps":[{"n":"01","text":"Cortar la carne y la grasa en cubos y mantenerlas frías entre 0 y 4 °C."},{"n":"02","text":"Moler la carne y la grasa con un disco de 8 mm."},{"n":"03","text":"Agregar todos los condimentos y mezclar hasta obtener una masa homogénea y pegajosa."},{"n":"04","text":"Incorporar el agua helada poco a poco mientras se continúa mezclando."},{"n":"05","text":"Embutir la mezcla en tripa natural de cerdo, calibre 32–35 mm."},{"n":"06","text":"Formar las longanizas del tamaño deseado."},{"n":"07","text":"Refrigerar entre 12 y 24 horas antes de cocinar, para mejorar la textura y desarrollar el sabor."}],"tips":[{"title":"Consejo técnico","description":"El frío es tu mejor aliado. Si la mezcla se calienta durante el embutido, la grasa se derrite prematuramente y la textura final pierde firmeza. Trabaja rápido y con la carne casi congelada."},{"title":"Temperatura de mezcla","description":"Trabaja siempre entre 0 y 4 °C. Por encima de 7 °C la grasa empieza a untar la carne y la textura final se pierde."},{"title":"Ritmo de embutido","description":"Alimenta la máquina despacio y sin forzar, dejando que la tripa se llene de forma pareja para evitar bolsas de aire."}],"cookMethods":[{"title":"Parrilla","description":"20–25 minutos a fuego medio, girando constantemente para lograr una cocción uniforme."},{"title":"Sartén","description":"Cocinar a fuego medio-bajo hasta obtener un dorado uniforme por todos los lados."}],"recommendations":["Mantener siempre la carne fría durante todo el proceso.","Evitar sobremezclar para conservar una buena textura.","Utilizar carne fresca y grasa firme.","No pinchar las longanizas durante la cocción, para evitar la pérdida de jugos."],"resultNote":"El resultado: un corte parejo, con la grasa bien distribuida y sin bolsas de aire, es la señal de un buen mezclado y un embutido sin prisas. Así se ve una longaniza hecha con respeto por el oficio.","finalQuote":"Una buena longaniza no depende de agregar más especias, sino de respetar el equilibrio entre carne, grasa, temperatura y técnica. La calidad de la materia prima y un buen mezclado marcarán la diferencia en el resultado final.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 10),
  ('chorizo-de-ajo', 'Chorizo de Ajo Parrillero', 'chorizos', '{"Colombia","Fresco","Parrillero"}', '/recipes/chorizo-de-ajo.jpg', 'Colombia · 2 kg', 'embutir-un-chorizo', $receta${"slug":"chorizo-de-ajo","name":"Chorizo de Ajo Parrillero","description":"El chorizo parrillero por excelencia — ajo protagonista, vino tinto y un “nutri” que integra todos los secos.","image":"/recipes/chorizo-de-ajo.jpg","tags":["Colombia","Fresco","Parrillero"],"eyebrow":"Receta · El camino del charcutero","subtitle":"El más popular de la parrilla, con ajo y vino.","intro":"El chorizo de ajo es el rey de la parrilla: jugoso, aromático y con el ajo como protagonista. El secreto está en el “nutri” — la mezcla previa de todos los ingredientes secos — que integra los sabores de forma uniforme antes de moler, y en un chorro de vino tinto que aporta profundidad. Una receta fresca, sin curado largo, pensada para asar el mismo día o al día siguiente.","stats":[{"label":"Rendimiento base","value":"2 kg"},{"label":"Tipo","value":"Embutido fresco"},{"label":"Nivel","value":"Fácil–Intermedio"},{"label":"Tiempo de preparación","value":"45 min"},{"label":"Tiempo de reposo","value":"12–24 h"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 32–35 mm"}],"details":[{"title":"Origen","description":"Carne magra de cerdo (pierna o paleta), molida media para una buena mordida."},{"title":"Textura","description":"500 g de grasa por cada 2 kg dan jugosidad sin que el chorizo se reseque en la parrilla."},{"title":"Sabor","description":"Ajo al frente, redondeado con vino tinto, pimentón y un toque de comino."}],"quote":"El “nutri” no es un truco: es la forma de que cada bocado sepa igual, del primer chorizo al último de la tanda.","ingredientsNote":"Prepara primero el “nutri”: pesa y mezcla todos los ingredientes secos antes de tocar la carne. Así los sabores se reparten parejos y no quedan bolsas de sal o de ajo.","ingredients":[{"name":"Carne magra de cerdo (pierna o paleta)","amount":"1500 g","pct":"75%"},{"name":"Grasa de cerdo (papada o tocino)","amount":"500 g","pct":"25%"},{"name":"Ajo fresco triturado","amount":"30 g","pct":"1.5%"},{"name":"Sal","amount":"40 g","pct":"2%"},{"name":"Pimentón dulce","amount":"20 g","pct":"1%"},{"name":"Pimienta negra","amount":"5 g","pct":"0.25%"},{"name":"Comino","amount":"4 g","pct":"0.2%"},{"name":"Orégano seco","amount":"2 g","pct":"0.1%"},{"name":"Azúcar","amount":"6 g","pct":"0.3%"},{"name":"Vino tinto seco","amount":"200 ml","pct":"10%"}],"proportionNote":"75% carne y 25% grasa (1,5 kg y 500 g) es el balance parrillero: suficiente grasa para que quede jugoso sobre las brasas sin volverse graso. El vino se calcula al 10% del total de carne y grasa.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. Domínalo y podrás hacer 2 kg o 20 con el mismo sabor: solo multiplica.","steps":[{"n":"01","text":"Prepara el “nutri”: pesa y mezcla todos los secos (sal, ajo, pimentón, pimienta, comino, orégano y azúcar) hasta integrarlos."},{"n":"02","text":"Corta la carne y la grasa en cubos y mantenlas muy frías, entre 0 y 4 °C."},{"n":"03","text":"Mezcla los cubos con el “nutri” y deja reposar en frío de 30 a 60 minutos."},{"n":"04","text":"Muele la carne y la grasa con un disco de 8 mm."},{"n":"05","text":"Incorpora el vino tinto frío poco a poco, amasando hasta una masa homogénea y pegajosa."},{"n":"06","text":"Embute en tripa natural de cerdo, calibre 32–35 mm, y forma los chorizos."},{"n":"07","text":"Refrigera entre 12 y 24 horas antes de asar, para asentar el sabor y la textura."}],"tips":[{"title":"El nutri primero","description":"Mezclar los secos antes de moler reparte la sal y el ajo de forma pareja; evita puntos salados o zonas sin sabor."},{"title":"Todo en frío","description":"Trabaja siempre entre 0 y 4 °C. Si la grasa se calienta, se unta y el chorizo pierde jugosidad en la parrilla."},{"title":"Vino al final","description":"Añade el vino poco a poco después de moler: liga la masa y aporta aroma sin ablandarla de más."}],"cookMethods":[{"title":"Parrilla","description":"20–25 minutos a fuego medio, girando con frecuencia para un dorado parejo sin reventar la tripa."},{"title":"Sartén","description":"Fuego medio-bajo hasta dorar por todos los lados; deja reposar un par de minutos antes de cortar."}],"recommendations":["Mantén la carne fría durante todo el proceso.","No sobremezcles: para en cuanto la masa quede pegajosa.","Usa carne fresca y grasa firme, no grasa blanda.","No pinches los chorizos al asar, para no perder los jugos."],"resultNote":"El resultado: un chorizo jugoso, con aroma de ajo y vino, que dora sin resecarse. Al corte, la grasa bien repartida y sin bolsas de aire delata el buen mezclado.","finalQuote":"Un buen chorizo de ajo no se mide por cuánto ajo lleva, sino por qué tan bien se integra con la carne, la grasa y el vino. El equilibrio manda.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 20),
  ('chorizo-criollo-argentino', 'Chorizo Criollo Argentino', 'chorizos', '{"Argentina","Fresco","Parrillero"}', '/recipes/chorizo-criollo-argentino.jpg', 'Argentina · 1 kg', 'embutir-un-chorizo', $receta${"slug":"chorizo-criollo-argentino","name":"Chorizo Criollo Argentino","description":"El alma del asado y el choripán — mezcla de cerdo y res, molido grueso, poco condimento y mucho fuego.","image":"/recipes/chorizo-criollo-argentino.jpg","tags":["Argentina","Fresco","Parrillero"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"El chorizo del asado y el choripán.","intro":"El chorizo criollo es el protagonista silencioso de todo asado argentino. A diferencia del español, no busca el pimentón ni el curado: es fresco, de molido grueso, con un condimento discreto que deja hablar a la carne. Mezcla clásica de cerdo y vacuno, un toque de vino y a la parrilla. Simple, honesto, imbatible en un buen choripán.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Embutido fresco"},{"label":"Nivel","value":"Fácil"},{"label":"Tiempo de preparación","value":"40 min"},{"label":"Tiempo de reposo","value":"12 h"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 32–34 mm"}],"details":[{"title":"Origen","description":"Cerdo y vacuno en mezcla, molido grueso para conservar mordida y jugo."},{"title":"Textura","description":"20% de grasa mantiene el chorizo jugoso sobre las brasas sin gotear de más."},{"title":"Sabor","description":"Condimento sobrio: ajo, pimienta y un poco de vino. Nada tapa la carne."}],"quote":"El criollo no compite con la carne del asado: la acompaña. Por eso el condimento es discreto y la mano, corta.","ingredientsNote":"Pesa los secos y mézclalos antes de moler. Un criollo no lleva muchas especias: lo que importa es que las pocas que lleva estén parejas.","ingredients":[{"name":"Carne de cerdo (paleta)","amount":"600 g","pct":"60%"},{"name":"Carne de res (roast/aguja)","amount":"200 g","pct":"20%"},{"name":"Grasa de cerdo","amount":"200 g","pct":"20%"},{"name":"Sal","amount":"20 g","pct":"2%"},{"name":"Ajo fresco triturado","amount":"10 g","pct":"1%"},{"name":"Pimentón dulce","amount":"6 g","pct":"0.6%"},{"name":"Pimienta negra","amount":"3 g","pct":"0.3%"},{"name":"Ají molido (opcional)","amount":"3 g","pct":"0.3%"},{"name":"Nuez moscada","amount":"1 g","pct":"0.1%"},{"name":"Vino blanco seco","amount":"50 ml","pct":"5%"}],"proportionNote":"60% cerdo, 20% res y 20% grasa es la base del criollo tradicional. Puedes subir el cerdo si buscas un chorizo más suave, o el vacuno para más carácter.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. Es la misma proporción para 1 kg o para 10.","steps":[{"n":"01","text":"Mezcla todos los secos (sal, ajo, pimentón, pimienta, ají y nuez moscada)."},{"n":"02","text":"Corta las carnes y la grasa en cubos y mantenlas entre 0 y 4 °C."},{"n":"03","text":"Muele con disco grueso de 8–10 mm para conservar la mordida."},{"n":"04","text":"Integra los secos y luego el vino frío, amasando lo justo."},{"n":"05","text":"Embute en tripa natural de cerdo, calibre 32–34 mm."},{"n":"06","text":"Forma los chorizos y ata en el largo deseado."},{"n":"07","text":"Refrigera al menos 12 horas antes de llevar a la parrilla."}],"tips":[{"title":"Molido grueso","description":"El criollo se distingue por su textura: disco grueso y no sobremezclar. Debe verse la carne, no una pasta."},{"title":"Poco condimento","description":"Menos es más. El pimentón aquí es color y fondo, no protagonista como en el español."},{"title":"A fuego medio","description":"Ásalo lento y entero; si lo abres “mariposa”, hazlo recién sobre las brasas para que no se seque."}],"cookMethods":[{"title":"Parrilla","description":"25–30 minutos a fuego medio, girando; la clave es cocción pareja sin apurar el fuego."},{"title":"Choripán","description":"Abierto a la mitad los últimos minutos, en pan crujiente y con chimichurri."}],"recommendations":["Mantén las carnes frías durante todo el proceso.","Usa disco grueso y amasa lo mínimo.","No pinches el chorizo en la parrilla.","Deja reposar 12 h para que el sabor se asiente."],"resultNote":"El resultado: un chorizo jugoso y de mordida firme, que dora parejo y no se deshace. Al corte se ve el grano grueso de la carne — la firma del criollo.","finalQuote":"Un buen criollo se reconoce en la parrilla: jugoso, entero y con la carne al frente. El secreto no está en el condimento, sino en la mano corta.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 30),
  ('chorizo-parrillero', 'Chorizo Parrillero Clásico', 'chorizos', '{"Colombia","Fresco","Parrillero"}', '/recipes/chorizo-parrillero.jpg', 'Colombia · 1 kg', 'embutir-un-chorizo', $receta${"slug":"chorizo-parrillero","name":"Chorizo Parrillero Clásico","description":"El comodín de la parrilla — cerdo jugoso, ajo, comino y cebolla, equilibrado para agradar a todos.","image":"/recipes/chorizo-parrillero.jpg","tags":["Colombia","Fresco","Parrillero"],"eyebrow":"Receta · El camino del charcutero","subtitle":"El chorizo de todos los días, bien hecho.","intro":"El parrillero clásico es la receta base que todo charcutero debería dominar: un chorizo fresco, jugoso y equilibrado, sin un sabor que domine sobre los demás. Ajo, comino y un toque de cebolla lo hacen redondo y familiar. Es el punto de partida para entender cómo la grasa, la sal y la temperatura definen un buen embutido.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Embutido fresco"},{"label":"Nivel","value":"Fácil"},{"label":"Tiempo de preparación","value":"40 min"},{"label":"Tiempo de reposo","value":"12–24 h"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 32–35 mm"}],"details":[{"title":"Origen","description":"Pierna o paleta de cerdo, molida media para una mordida jugosa."},{"title":"Textura","description":"20% de grasa asegura jugosidad sobre las brasas sin volverse graso."},{"title":"Sabor","description":"Equilibrio de ajo, comino y cebolla; ninguno domina sobre la carne."}],"quote":"El parrillero clásico enseña lo esencial: si dominas el balance de sal, grasa y frío, dominas cualquier chorizo.","ingredientsNote":"Mezcla los secos antes de moler para repartir sal y especias de forma pareja. La cebolla en polvo evita el exceso de humedad de la fresca.","ingredients":[{"name":"Carne de cerdo (pierna o paleta)","amount":"800 g","pct":"80%"},{"name":"Grasa de cerdo (papada o tocino)","amount":"200 g","pct":"20%"},{"name":"Sal","amount":"20 g","pct":"2%"},{"name":"Ajo fresco triturado","amount":"10 g","pct":"1%"},{"name":"Pimentón dulce","amount":"10 g","pct":"1%"},{"name":"Comino","amount":"3 g","pct":"0.3%"},{"name":"Cebolla en polvo","amount":"5 g","pct":"0.5%"},{"name":"Pimienta negra","amount":"3 g","pct":"0.3%"},{"name":"Azúcar","amount":"3 g","pct":"0.3%"},{"name":"Agua helada","amount":"30 ml","pct":"3%"}],"proportionNote":"80% carne y 20% grasa es el balance parrillero universal. Sube la grasa un par de puntos si buscas más jugosidad, sin pasar del rango artesanal.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. Domínalo y escalas la receta a cualquier cantidad.","steps":[{"n":"01","text":"Mezcla todos los secos hasta integrarlos (el “nutri”)."},{"n":"02","text":"Corta la carne y la grasa en cubos y mantenlas entre 0 y 4 °C."},{"n":"03","text":"Muele con disco de 8 mm."},{"n":"04","text":"Agrega los secos y mezcla hasta una masa homogénea y pegajosa."},{"n":"05","text":"Incorpora el agua helada poco a poco mientras amasas."},{"n":"06","text":"Embute en tripa natural de cerdo, calibre 32–35 mm, y forma los chorizos."},{"n":"07","text":"Refrigera entre 12 y 24 horas antes de asar."}],"tips":[{"title":"El frío manda","description":"Trabaja entre 0 y 4 °C. Si la grasa se calienta, se unta y el chorizo pierde textura."},{"title":"No sobremezclar","description":"Para en cuanto la masa quede pegajosa; amasar de más endurece el resultado."},{"title":"Reposo con sentido","description":"Las 12–24 h en frío asientan la sal y desarrollan el sabor antes de cocinar."}],"cookMethods":[{"title":"Parrilla","description":"20–25 minutos a fuego medio, girando con frecuencia para un dorado parejo."},{"title":"Sartén","description":"Fuego medio-bajo hasta dorar por todos los lados; reposar antes de cortar."}],"recommendations":["Mantén la carne fría durante todo el proceso.","Evita sobremezclar para conservar buena textura.","Usa carne fresca y grasa firme.","No pinches los chorizos durante la cocción."],"resultNote":"El resultado: un chorizo jugoso, parejo y de sabor redondo, sin picos de sal ni de especia. La base sobre la que se construyen todas las variantes.","finalQuote":"El mejor chorizo parrillero no es el más condimentado, sino el mejor balanceado. Domina el equilibrio y todo lo demás es variación.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 40),
  ('chorizo-iberico', 'Chorizo Ibérico Curado', 'chorizos', '{"España","Curado"}', '/recipes/chorizo-iberico.jpg', 'España · 1 kg', 'embutir-un-chorizo', $receta${"slug":"chorizo-iberico","name":"Chorizo Ibérico Curado","description":"El clásico español curado en seco — cerdo ibérico y pimentón de la Vera, ahumado y con carácter.","image":"/recipes/chorizo-iberico.jpg","tags":["España","Curado"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Cerdo ibérico y pimentón de la Vera.","intro":"El chorizo ibérico es el emblema de la charcutería española: carne de cerdo ibérico, pimentón de la Vera — dulce y ahumado — y un curado paciente que concentra el sabor. No se cocina: se cura al aire durante semanas hasta lograr su textura firme y su aroma inconfundible. Una receta que exige respeto por la temperatura, la humedad y la sal de cura.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Curado en seco"},{"label":"Nivel","value":"Avanzado"},{"label":"Tiempo de preparación","value":"50 min"},{"label":"Curado","value":"4–8 semanas"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 38–40 mm"}],"details":[{"title":"Origen","description":"Cerdo ibérico, cuya grasa infiltrada da untuosidad y aroma al curado."},{"title":"Textura","description":"Curado lento hasta perder ~30% del peso: firme al corte, no seco."},{"title":"Sabor","description":"Pimentón de la Vera al frente — dulce, ahumado — con fondo de ajo."}],"quote":"El pimentón de la Vera es el alma del chorizo ibérico: ahumado sobre leña de encina, no admite sustitutos.","ingredientsNote":"En un curado, la sal de cura no es opcional: inhibe las bacterias peligrosas durante las semanas al aire. Pésala con precisión — ni más, ni menos.","ingredients":[{"name":"Carne de cerdo ibérico (magro)","amount":"800 g","pct":"80%"},{"name":"Tocino ibérico","amount":"200 g","pct":"20%"},{"name":"Pimentón de la Vera dulce","amount":"30 g","pct":"3%"},{"name":"Pimentón de la Vera picante","amount":"10 g","pct":"1%"},{"name":"Sal","amount":"26 g","pct":"2.6%"},{"name":"Ajo fresco triturado","amount":"10 g","pct":"1%"},{"name":"Sal de cura (nitrificante, #2)","amount":"2.5 g","pct":"0.25%"},{"name":"Orégano seco","amount":"1 g","pct":"0.1%"},{"name":"Vino blanco seco","amount":"30 ml","pct":"3%"}],"proportionNote":"80% magro y 20% tocino es el equilibrio ibérico: suficiente grasa infiltrada para untuosidad sin que el curado quede blando. El pimentón ronda el 4% del total.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. La sal de cura al 0.25% (2.5 g/kg) es el estándar seguro; respétalo siempre.","steps":[{"n":"01","text":"Mezcla los secos: pimentones, sal, sal de cura, ajo y orégano."},{"n":"02","text":"Corta magro y tocino en cubos, muy fríos (0–2 °C)."},{"n":"03","text":"Muele con disco de 8 mm."},{"n":"04","text":"Integra los secos y el vino; amasa hasta una masa homogénea y roja."},{"n":"05","text":"Deja macerar en frío 12–24 h para que el pimentón tome."},{"n":"06","text":"Embute firme en tripa de 38–40 mm, evitando bolsas de aire, y pincha."},{"n":"07","text":"Cura a 12–15 °C y 75–80% de humedad, 4–8 semanas, hasta perder ~30% del peso."}],"tips":[{"title":"Pimentón de la Vera","description":"Su ahumado sobre encina es irremplazable. Un pimentón sin ahumar dará color, pero no el aroma del ibérico."},{"title":"Curado controlado","description":"12–15 °C y 75–80% de humedad. Sin esas condiciones, el curado en casa es un riesgo real."},{"title":"Sal de cura","description":"Nunca la omitas en un curado largo: es lo que impide el crecimiento de bacterias peligrosas."}],"cookMethods":[{"title":"En lonchas","description":"Curado y servido a temperatura ambiente, en lonchas finas sobre pan con aceite."},{"title":"Para guisar","description":"En tacos, aporta color y sabor a guisos, arroces y potajes."}],"recommendations":["Nunca omitas la sal de cura en un curado largo.","Controla temperatura (12–15 °C) y humedad (75–80%).","Embute firme y pincha para evitar bolsas de aire.","Pesa cada ingrediente: el margen de error es pequeño."],"resultNote":"El resultado: un chorizo firme, de color rojo profundo y aroma ahumado, que al corte muestra la grasa infiltrada del ibérico. Paciencia y control, no atajos.","finalQuote":"El chorizo ibérico no se hace en un día. Es tiempo, pimentón de la Vera y control — la definición misma de curar con respeto por el oficio.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 50),
  ('chorizo-riojano', 'Chorizo Riojano', 'chorizos', '{"España","Curado","Picante"}', '/recipes/chorizo-riojano.jpg', 'España · 1 kg', 'embutir-un-chorizo', $receta${"slug":"chorizo-riojano","name":"Chorizo Riojano","description":"Curado firme y especiado — solo cerdo, tocino, pimentón extra, ajo y sal. Pureza con carácter.","image":"/recipes/chorizo-riojano.jpg","tags":["España","Curado","Picante"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Pimentón extra, forma de herradura, sabor intenso.","intro":"El chorizo riojano se distingue por su pureza: carne y tocino de calidad, pimentón extra, ajo y sal — nada más. Sin aditivos que enmascaren. Su consistencia es firme y compacta, con el pimentón dominando el aroma y un punto picante que lo hace inconfundible. Se cura en forma de herradura durante semanas hasta lograr su textura característica.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Curado en seco"},{"label":"Nivel","value":"Avanzado"},{"label":"Tiempo de preparación","value":"50 min"},{"label":"Curado","value":"4–8 semanas"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 34–40 mm"}],"details":[{"title":"Origen","description":"Carne y tocino de cerdo de buena calidad, molido medio-grueso."},{"title":"Textura","description":"Firme y compacta: se distingue bien la carne de la grasa al corte."},{"title":"Sabor","description":"Pimentón extra al frente, ajo de fondo y un punto picante persistente."}],"quote":"El riojano no esconde nada: cuatro ingredientes y tiempo. Cuando la receta es corta, cada gramo cuenta.","ingredientsNote":"La receta es mínima, así que la precisión lo es todo. La sal de cura es obligatoria para un curado seguro.","ingredients":[{"name":"Carne de cerdo (magro)","amount":"750 g","pct":"75%"},{"name":"Tocino de cerdo","amount":"250 g","pct":"25%"},{"name":"Pimentón extra dulce","amount":"30 g","pct":"3%"},{"name":"Pimentón picante","amount":"10 g","pct":"1%"},{"name":"Sal","amount":"26 g","pct":"2.6%"},{"name":"Ajo fresco triturado","amount":"15 g","pct":"1.5%"},{"name":"Sal de cura (nitrificante, #2)","amount":"2.5 g","pct":"0.25%"},{"name":"Agua helada","amount":"20 ml","pct":"2%"}],"proportionNote":"75% carne y 25% tocino da la firmeza compacta del riojano. El pimentón al 4% es lo que define su color y aroma; ajústalo entre dulce y picante a tu gusto.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y tocino. La sal de cura al 0.25% es el estándar seguro para curados.","steps":[{"n":"01","text":"Mezcla los secos: pimentones, sal, sal de cura y ajo."},{"n":"02","text":"Corta carne y tocino en cubos, muy fríos (0–2 °C)."},{"n":"03","text":"Muele con disco de 8–10 mm."},{"n":"04","text":"Integra los secos con el agua helada; amasa hasta masa homogénea."},{"n":"05","text":"Macera en frío 12–24 h para asentar el pimentón."},{"n":"06","text":"Embute firme, forma la herradura y pincha para sacar el aire."},{"n":"07","text":"Cura a 12–15 °C y 75–80% de humedad, 4–8 semanas."}],"tips":[{"title":"Pimentón de calidad","description":"Al ser casi el único condimento, un buen pimentón extra define el resultado. No escatimes aquí."},{"title":"Curado controlado","description":"Mantén 12–15 °C y 75–80% de humedad. Un curado sin control es un riesgo sanitario."},{"title":"Embutido firme","description":"Compacta bien la masa y pincha la tripa: las bolsas de aire arruinan el curado."}],"cookMethods":[{"title":"En lonchas","description":"Curado, en lonchas sobre pan; su punto picante brilla a temperatura ambiente."},{"title":"Para guisar","description":"En rodajas, da color y fuerza a lentejas, patatas y arroces."}],"recommendations":["Usa un pimentón extra de buena calidad.","Nunca omitas la sal de cura.","Controla temperatura y humedad durante el curado.","Pincha la tripa para evitar bolsas de aire."],"resultNote":"El resultado: un chorizo firme, rojo intenso y de aroma dominado por el pimentón, con un picante que persiste. La prueba de que menos ingredientes exigen más técnica.","finalQuote":"En el riojano no hay dónde esconderse: cuatro ingredientes y el tiempo. Por eso separa a los charcuteros de verdad.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 60),
  ('chorizo-cantimpalo', 'Chorizo de Cantimpalos', 'chorizos', '{"España","Curado"}', '/recipes/chorizo-cantimpalo.jpg', 'España · 1 kg', 'embutir-un-chorizo', $receta${"slug":"chorizo-cantimpalo","name":"Chorizo de Cantimpalos","description":"El segoviano suave y ligeramente dulce — magro, pimentón de la Vera y curado, sin tocino añadido.","image":"/recipes/chorizo-cantimpalo.jpg","tags":["España","Curado"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Suave, magro y con Denominación de Origen.","intro":"El chorizo de Cantimpalos, del pueblo segoviano del mismo nombre, es famoso por su sabor suave y ligeramente dulce. Su seña de identidad es que no lleva tocino añadido: se elabora con carne magra de cerdo — de animales alimentados con cereal — pimentón de la Vera y sal, sin conservantes que enmascaren. Un curado sobrio que deja hablar a la buena materia prima.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Curado en seco"},{"label":"Nivel","value":"Avanzado"},{"label":"Tiempo de preparación","value":"50 min"},{"label":"Curado","value":"5–8 semanas"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 38–40 mm"}],"details":[{"title":"Origen","description":"Carne magra de cerdo, sin tocino añadido — solo la grasa propia de la pieza."},{"title":"Textura","description":"Firme pero jugosa, gracias a la grasa infiltrada del magro."},{"title":"Sabor","description":"Suave y ligeramente dulce; el pimentón de la Vera aporta al menos la mitad del carácter."}],"quote":"Cantimpalos enseña una lección: sin tocino que lo esconda, un chorizo solo es tan bueno como su carne.","ingredientsNote":"Al usar magro casi puro, elige carne con buena grasa infiltrada. La sal de cura es obligatoria para el curado.","ingredients":[{"name":"Carne magra de cerdo","amount":"900 g","pct":"90%"},{"name":"Grasa de cerdo (propia de la pieza)","amount":"100 g","pct":"10%"},{"name":"Pimentón de la Vera dulce","amount":"25 g","pct":"2.5%"},{"name":"Sal","amount":"26 g","pct":"2.6%"},{"name":"Ajo fresco triturado","amount":"8 g","pct":"0.8%"},{"name":"Sal de cura (nitrificante, #2)","amount":"2.5 g","pct":"0.25%"},{"name":"Orégano seco","amount":"1 g","pct":"0.1%"},{"name":"Agua helada","amount":"20 ml","pct":"2%"}],"proportionNote":"90% magro y 10% grasa es lo que hace único al Cantimpalos: sin tocino añadido. Por eso la calidad de la carne — y su grasa infiltrada — lo es todo.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. La sal de cura al 0.25% mantiene el curado seguro.","steps":[{"n":"01","text":"Mezcla los secos: pimentón, sal, sal de cura, ajo y orégano."},{"n":"02","text":"Corta la carne en cubos, muy fría (0–2 °C)."},{"n":"03","text":"Muele con disco de 8 mm."},{"n":"04","text":"Integra los secos con el agua helada; amasa hasta ligar."},{"n":"05","text":"Macera en frío 24 h para que el pimentón desarrolle su dulzor."},{"n":"06","text":"Embute firme en tripa de 38–40 mm y pincha."},{"n":"07","text":"Cura a 12–15 °C y 75–80% de humedad, 5–8 semanas."}],"tips":[{"title":"La carne manda","description":"Sin tocino que aporte jugosidad, necesitas magro con buena grasa infiltrada. Ahí está el secreto."},{"title":"Pimentón dulce","description":"El Cantimpalos es suave: usa pimentón de la Vera dulce y evita el picante para respetar su perfil."},{"title":"Curado controlado","description":"12–15 °C y 75–80% de humedad; sin control, el curado en casa es arriesgado."}],"cookMethods":[{"title":"En lonchas","description":"Curado, en lonchas finas a temperatura ambiente para apreciar su dulzor."},{"title":"Para guisar","description":"Su suavidad lo hace ideal en cocidos y sopas castellanas."}],"recommendations":["Elige magro con buena grasa infiltrada.","Usa pimentón de la Vera dulce, sin picante.","No omitas la sal de cura.","Controla temperatura y humedad durante el curado."],"resultNote":"El resultado: un chorizo firme y magro, de color rojo suave y sabor ligeramente dulce. La prueba de que sin tocino no hay dónde esconder una carne mediocre.","finalQuote":"El Cantimpalos es honestidad pura: sin tocino, sin conservantes. Solo carne buena, pimentón y tiempo bien llevado.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 70),
  ('chorizo-verde-mexicano', 'Chorizo Verde de Toluca', 'chorizos', '{"México","Fresco","Picante"}', '/recipes/chorizo-verde-mexicano.jpg', 'México · 1 kg', 'embutir-un-chorizo', $receta${"slug":"chorizo-verde-mexicano","name":"Chorizo Verde de Toluca","description":"El fresco verde de Toluca — tomatillo, chiles verdes, cilantro y perejil molidos con la carne.","image":"/recipes/chorizo-verde-mexicano.jpg","tags":["México","Fresco","Picante"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"El chorizo verde que conquistó a Toluca.","intro":"El chorizo verde es la joya de Toluca: un embutido fresco de color intenso, hecho con una pasta de tomatillo, chiles verdes, cilantro y perejil. Cada familia guarda su receta, pero todas coinciden en el chile serrano, el cilantro y el tomatillo como base. La espinaca o acelga refuerzan el verde, y las especias — comino, clavo, orégano — le dan profundidad. Se cocina fresco, nunca se cura.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Embutido fresco"},{"label":"Nivel","value":"Intermedio"},{"label":"Tiempo de preparación","value":"50 min"},{"label":"Tiempo de reposo","value":"12–24 h"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 28–32 mm"}],"details":[{"title":"Origen","description":"Carne de cerdo con la pasta verde molida en conjunto para teñir la masa."},{"title":"Textura","description":"Fresca y húmeda; la pasta verde aporta jugosidad y color."},{"title":"Sabor","description":"Ácido y herbal — tomatillo y cilantro — con el picor del chile serrano."}],"quote":"El verde de Toluca no es un chorizo teñido: la carne y la pasta verde se muelen juntas, y ahí nace su color y su acidez.","ingredientsNote":"Licúa primero la pasta verde y escúrrela un poco: demasiada humedad dificulta el embutido. Ajusta el picante con la cantidad de serrano.","ingredients":[{"name":"Carne de cerdo (pierna o paleta)","amount":"800 g","pct":"80%"},{"name":"Grasa de cerdo","amount":"200 g","pct":"20%"},{"name":"Pasta verde (tomatillo, chile serrano, cilantro, perejil, espinaca)","amount":"150 g","pct":"15%"},{"name":"Ajo fresco triturado","amount":"15 g","pct":"1.5%"},{"name":"Sal","amount":"20 g","pct":"2%"},{"name":"Vinagre blanco","amount":"30 ml","pct":"3%"},{"name":"Comino","amount":"3 g","pct":"0.3%"},{"name":"Orégano seco","amount":"2 g","pct":"0.2%"},{"name":"Pimienta negra","amount":"2 g","pct":"0.2%"},{"name":"Clavo molido","amount":"1 g","pct":"0.1%"}],"proportionNote":"80% carne y 20% grasa, con la pasta verde al 15% del total. Más pasta intensifica el color y la acidez, pero también la humedad: escúrrela para poder embutir.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. Al ser fresco, no lleva sal de cura, pero sí se consume cocinado y pronto.","steps":[{"n":"01","text":"Licúa la pasta verde (tomatillo, chiles, cilantro, perejil, espinaca) y escúrrela."},{"n":"02","text":"Mezcla los secos: sal, comino, orégano, pimienta y clavo."},{"n":"03","text":"Corta la carne y la grasa en cubos, muy fríos (0–4 °C)."},{"n":"04","text":"Muele la carne y la grasa con disco de 8 mm."},{"n":"05","text":"Integra la pasta verde, el ajo, los secos y el vinagre; amasa hasta teñir la masa."},{"n":"06","text":"Embute en tripa fina de cerdo (28–32 mm) y forma los chorizos."},{"n":"07","text":"Refrigera 12–24 h; consúmelo fresco en pocos días."}],"tips":[{"title":"Escurre la pasta","description":"La humedad es el enemigo del embutido. Escurre bien la pasta verde para que la masa ligue."},{"title":"Frío constante","description":"Trabaja entre 0 y 4 °C; la pasta fría ayuda a mantener la grasa firme."},{"title":"Fresco, no curado","description":"El verde es un chorizo fresco: refrigéralo y cocínalo en pocos días, o congélalo."}],"cookMethods":[{"title":"Sartén","description":"Desmenuzado a fuego medio hasta secar la humedad; ideal para tacos y huevos."},{"title":"Comal","description":"En trozos sobre comal caliente, girando hasta dorar por fuera."}],"recommendations":["Escurre bien la pasta verde antes de mezclar.","Mantén la carne y la grasa frías.","Consúmelo fresco en pocos días o congélalo.","Ajusta el picante con la cantidad de chile serrano."],"resultNote":"El resultado: un chorizo de verde vivo, fresco y ácido, con el picor justo. Al cocinarlo suelta su humedad y concentra el sabor herbal de Toluca.","finalQuote":"El chorizo verde no busca curarse ni durar: busca frescura. Su secreto está en la pasta de hierbas y chiles, molida con la carne.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 80),
  ('chorizos-picantes-jalapeno-queso-cheddar', 'Chorizos Picantes de Jalapeño y Queso Cheddar', 'chorizos', '{"México","Picante","Queso"}', '/recipes/chorizos-picantes-jalapeno-queso-cheddar.jpg', 'México · 1 kg', 'embutir-un-chorizo', $receta${"slug":"chorizos-picantes-jalapeno-queso-cheddar","name":"Chorizos Picantes de Jalapeño y Queso Cheddar","description":"Chorizos frescos de cerdo con jalapeño picado y cubos de cheddar, inspirados en el chorizo jalapeño-cheddar y el chorizo mexicano con queso.","image":"/recipes/chorizos-picantes-jalapeno-queso-cheddar.jpg","tags":["México","Picante","Queso"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Cerdo, jalapeño y cheddar en una mezcla fresca y contundente.","intro":"Esta receta toma la idea clásica del chorizo jalapeño con queso y la aterriza en una versión de cerdo bien sazonada: carne de cerdo, grasa, jalapeño fresco y cheddar en cubos. El resultado es un chorizo fresco, pensado para embutir y cocinar, con mordida jugosa, picante limpio y pequeños bolsillos de queso derretido al dorarse.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Embutido fresco"},{"label":"Nivel","value":"Intermedio"},{"label":"Tiempo de preparación","value":"45 min"},{"label":"Tiempo de reposo","value":"8–12 h"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 32–36 mm"}],"details":[{"title":"Origen","description":"Basado en recetas de chorizo fresco de cerdo con jalapeño y en versiones con queso cheddar y queso latino."},{"title":"Textura","description":"Molienda gruesa y jugosa, con jalapeño picado y cubos de cheddar que se ablandan sin desaparecer."},{"title":"Sabor","description":"Picante medio, lácteo y salado, con ajo, pimienta y el toque herbal del jalapeño."}],"quote":"El truco está en mantener el queso frío y los cubos pequeños: así el cheddar perfuma la mordida sin desaparecer por completo.","ingredientsNote":"Usa cheddar bien frío, cortado en cubos pequeños, y jalapeños sin exceso de humedad. Eso ayuda a embutir sin que la mezcla se rompa.","ingredients":[{"name":"Carne de cerdo (paleta o pierna)","amount":"800 g","pct":"80%"},{"name":"Grasa de cerdo","amount":"200 g","pct":"20%"},{"name":"Jalapeño fresco, sin semillas y picado fino","amount":"60 g","pct":"6%"},{"name":"Queso cheddar curado, en cubos fríos","amount":"120 g","pct":"12%"},{"name":"Sal","amount":"18 g","pct":"1.8%"},{"name":"Pimienta negra","amount":"2 g","pct":"0.2%"},{"name":"Ajo fresco triturado","amount":"5 g","pct":"0.5%"},{"name":"Cebolla en polvo","amount":"3 g","pct":"0.3%"},{"name":"Comino molido","amount":"2 g","pct":"0.2%"},{"name":"Orégano seco","amount":"2 g","pct":"0.2%"},{"name":"Vinagre blanco","amount":"25 ml","pct":"2.5%"}],"proportionNote":"La base es 80/20 de carne y grasa, con jalapeño al 6% y cheddar al 12%. El queso suma riqueza y volumen, pero conviene mantenerlo en cubos fríos para que el embutido no se compacte de más.","charcuteroNote":"Es un chorizo fresco: no lleva sal de cura. Se mezcla, se embute y se cocina pronto o se congela para uso posterior.","steps":[{"n":"01","text":"Enfría el queso cheddar y córtalo en cubos pequeños."},{"n":"02","text":"Retira semillas y venas del jalapeño, pícalo fino y escurre el exceso de líquido."},{"n":"03","text":"Mezcla sal, pimienta, ajo, cebolla en polvo, comino y orégano."},{"n":"04","text":"Muele la carne de cerdo y la grasa con disco de 8 mm."},{"n":"05","text":"Incorpora especias, jalapeño y vinagre; amasa hasta que la mezcla quede pegajosa."},{"n":"06","text":"Añade el cheddar al final, mezcla lo justo y embute en tripa natural de cerdo."},{"n":"07","text":"Reposa 8–12 horas en refrigeración y cocina antes de servir."}],"tips":[{"title":"Queso frío","description":"Si el cheddar se calienta demasiado, se aplasta y se pierde en la masa."},{"title":"Jalapeño escurrido","description":"Menos agua significa una textura más limpia y mejor embutido."},{"title":"Cocción suave","description":"Cocínalo a fuego medio para que el queso funda sin reventar la tripa."}],"cookMethods":[{"title":"Sartén","description":"Dorado lento en rodajas o enteros, hasta que el cheddar empiece a asomar."},{"title":"Parrilla","description":"A fuego medio, girando con frecuencia para que el queso no escape."}],"recommendations":["Mantén todo muy frío antes de embutir.","No picates demasiado fino el jalapeño para que conserve presencia.","Usa cheddar curado para mejor sabor y estructura.","Cocina a fuego medio para evitar que se rompa la tripa."],"resultNote":"El resultado es un chorizo fresco de cerdo con picor nítido, aroma de ajo y el contraste cremoso del cheddar. Funciona muy bien en tortas, tacos o a la parrilla.","finalQuote":"Cuando el jalapeño y el cheddar entran al chorizo de cerdo, el picante deja de ser solo fuego y se vuelve mordida.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 90),
  ('chorizo-venezolano', 'Chorizo Venezolano', 'chorizos', '{"Venezuela","Fresco","Parrillero"}', '/recipes/chorizo-venezolano.jpg', 'Venezuela · 1 kg', 'embutir-un-chorizo', $receta${"slug":"chorizo-venezolano","name":"Chorizo Venezolano","description":"Fresco y aromático — ajo, ají dulce, cilantro y un toque de comino. El chorizo de la parrilla llanera.","image":"/recipes/chorizo-venezolano.jpg","tags":["Venezuela","Fresco","Parrillero"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Ají dulce, cilantro y parrilla.","intro":"El chorizo venezolano es fresco, jugoso y muy aromático. Su firma es el ají dulce — sin picante — junto al cilantro y el ajo, que le dan un perfil herbal inconfundible. Es un chorizo de parrilla y de sartén, presente en toda parrilla llanera y en el desayuno criollo. Un toque de comino y pimentón redondean el sabor.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Embutido fresco"},{"label":"Nivel","value":"Fácil–Intermedio"},{"label":"Tiempo de preparación","value":"45 min"},{"label":"Tiempo de reposo","value":"12–24 h"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 32–35 mm"}],"details":[{"title":"Origen","description":"Carne de cerdo, molida media, con verduras aromáticas picadas fino."},{"title":"Textura","description":"Jugosa; el ají dulce y el cilantro aportan frescura sin exceso de humedad."},{"title":"Sabor","description":"Ajo y ají dulce al frente, cilantro herbal y un fondo de comino."}],"quote":"El ají dulce es el corazón del sabor venezolano: aroma sin picor, imposible de sustituir por pimentón.","ingredientsNote":"Pica el ají dulce y el cilantro muy fino, o licúalos con poca agua. Escurre para no aguar la masa.","ingredients":[{"name":"Carne de cerdo (pierna o paleta)","amount":"750 g","pct":"75%"},{"name":"Grasa de cerdo","amount":"250 g","pct":"25%"},{"name":"Ají dulce","amount":"60 g","pct":"6%"},{"name":"Ajo fresco triturado","amount":"12 g","pct":"1.2%"},{"name":"Cilantro fresco picado","amount":"20 g","pct":"2%"},{"name":"Sal","amount":"20 g","pct":"2%"},{"name":"Pimentón dulce","amount":"10 g","pct":"1%"},{"name":"Comino","amount":"3 g","pct":"0.3%"},{"name":"Pimienta negra","amount":"3 g","pct":"0.3%"},{"name":"Vinagre o vino","amount":"30 ml","pct":"3%"}],"proportionNote":"75% carne y 25% grasa da la jugosidad parrillera. El ají dulce y el cilantro suman aroma; ajústalos según cuánto verde busques.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. Al ser fresco, no lleva sal de cura: se cocina y se consume pronto.","steps":[{"n":"01","text":"Pica fino el ají dulce y el cilantro; escúrrelos."},{"n":"02","text":"Mezcla los secos: sal, pimentón, comino y pimienta."},{"n":"03","text":"Corta la carne y la grasa en cubos, muy fríos (0–4 °C)."},{"n":"04","text":"Muele con disco de 8 mm."},{"n":"05","text":"Integra ají, cilantro, ajo, secos y vinagre; amasa hasta ligar."},{"n":"06","text":"Embute en tripa natural de cerdo (32–35 mm) y forma los chorizos."},{"n":"07","text":"Refrigera 12–24 h antes de asar."}],"tips":[{"title":"Ají dulce, no picante","description":"El perfil venezolano es aromático, no picante. El ají dulce da olor y sabor sin calor."},{"title":"Verduras escurridas","description":"Escurre bien el ají y el cilantro; el exceso de agua impide que la masa ligue."},{"title":"Todo frío","description":"Mantén 0–4 °C durante el proceso para conservar la textura de la grasa."}],"cookMethods":[{"title":"Parrilla","description":"20–25 minutos a fuego medio, girando; jugoso y aromático para la parrilla."},{"title":"Sartén","description":"Fuego medio hasta dorar; clásico del desayuno con arepa y huevos."}],"recommendations":["Usa ají dulce, no picante, para el perfil correcto.","Escurre las verduras antes de mezclar.","Mantén la carne fría durante todo el proceso.","Consúmelo fresco o congélalo pronto."],"resultNote":"El resultado: un chorizo jugoso y muy aromático, con el verde del cilantro y el ají a la vista. Fresco, para la parrilla o el sartén del desayuno.","finalQuote":"El chorizo venezolano se reconoce por el aroma antes que por el sabor: ají dulce y cilantro, la frescura del llano en cada bocado.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 100),
  ('chorizo-santarrosano', 'Chorizo Santarrosano', 'chorizos', '{"Colombia","Fresco","Parrillero"}', '/recipes/chorizo-santarrosano.jpg', 'Colombia · 1 kg', 'embutir-un-chorizo', $receta${"slug":"chorizo-santarrosano","name":"Chorizo Santarrosano","description":"Uno de los chorizos más tradicionales de Colombia — carne magra de cerdo y tocino en equilibrio, jugoso y perfecto para la parrilla.","image":"/recipes/chorizo-santarrosano.jpg","tags":["Colombia","Fresco","Parrillero"],"eyebrow":"Receta · El camino del charcutero","subtitle":"El chorizo tradicional de Santa Rosa, jugoso y directo a la parrilla.","intro":"🔥 Así se prepara uno de los chorizos más tradicionales de Colombia: el chorizo santarrosano. 🌭\n\nCon una mezcla sencilla pero llena de sabor: 700 g de carne magra de cerdo y 300 g de tocino, logramos un chorizo jugoso, con excelente textura y perfecto para la parrilla.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Embutido fresco"},{"label":"Nivel","value":"Fácil"},{"label":"Tiempo de preparación","value":"30 min"},{"label":"Tiempo de reposo","value":"24–36 h"},{"label":"Tipo de tripa","value":"Natural"}],"details":[{"title":"Origen","description":"Carne magra de cerdo y tocino, en proporción 70/30 — la base clásica del santarrosano."},{"title":"Textura","description":"300 g de tocino por kilo aportan jugosidad sin perder firmeza al morder."},{"title":"Sabor","description":"Ajo fresco, cebolla larga, comino y paprika dulce dan el sabor tradicional que nunca pasa de moda."}],"quote":"El santarrosano es la prueba de que la tradición no necesita complicarse: carne, tocino y las especias justas.","ingredientsNote":"Condimentos para 1 kg de carne (700 g de carne magra de cerdo y 300 g de tocino).","ingredients":[{"name":"Carne magra de cerdo","amount":"700 g","pct":"70%"},{"name":"Tocino","amount":"300 g","pct":"30%"},{"name":"Sal","amount":"18 g","pct":"1.8%"},{"name":"Sal de cura (Prague Powder #1)","amount":"2.5 g","pct":"0.25%"},{"name":"Ajo fresco","amount":"18 g","pct":"1.8%"},{"name":"Cebolla larga finamente picada","amount":"25 g","pct":"2.5%"},{"name":"Pimienta negra molida","amount":"2 g","pct":"0.2%"},{"name":"Comino molido","amount":"2 g","pct":"0.2%"},{"name":"Paprika dulce","amount":"2 g","pct":"0.2%"}],"proportionNote":"70% carne magra y 30% tocino es el balance santarrosano tradicional: suficiente grasa para lograr jugosidad sin perder firmeza en la parrilla.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. Domínalo y escalas la receta a cualquier cantidad.","steps":[{"n":"01","text":"Mezclar la carne magra, el tocino, la sal, la sal de cura, el ajo, la cebolla larga y las especias hasta integrar bien."},{"n":"02","text":"Embutir la mezcla en tripa natural."},{"n":"03","text":"Dejar secar una noche a temperatura ambiente, en un lugar fresco y protegido."},{"n":"04","text":"Reposar 24 horas más en refrigeración."},{"n":"05","text":"Al día siguiente, asar, freír o cocinar."}],"tips":[{"title":"Precisión con la sal de cura","description":"Pesa la sal de cura (Prague Powder #1) con exactitud: es clave para la seguridad y el color del embutido."},{"title":"Cebolla fresca, picada fina","description":"Pícala lo más fino posible para que se integre sin dejar bolsas de humedad en la mezcla."},{"title":"Respeta el doble reposo","description":"El secado a temperatura ambiente y las 24 h en frío que siguen son las que asientan el sabor tradicional."}],"cookMethods":[{"title":"Parrilla","description":"A fuego medio, girando con frecuencia hasta dorar parejo por todos los lados."},{"title":"Sartén o freír","description":"Fuego medio-bajo hasta dorar y cocinar por completo; también se puede cocinar antes de dorar."}],"recommendations":["Mantén la carne y el tocino fríos durante todo el proceso.","Pesa la sal de cura con precisión.","Respeta el secado a temperatura ambiente antes de refrigerar.","No pinches los chorizos durante la cocción."],"resultNote":"Al día siguiente tendrás unos chorizos listos para asar, freír o cocinar, con un sabor tradicional que nunca pasa de moda.","finalQuote":"El chorizo santarrosano no necesita trucos: carne magra, tocino y el tiempo de reposo justo hacen todo el trabajo.","finalQuoteCaption":"Consejo de El Charcu","socialPost":{"caption":"🔥 Así se prepara uno de los chorizos más tradicionales de Colombia: el chorizo santarrosano. 🌭\n\nCon una mezcla sencilla pero llena de sabor: 700 g de carne magra de cerdo y 300 g de tocino, logramos un chorizo jugoso, con excelente textura y perfecto para la parrilla.","instructions":"Después de mezclar todos los ingredientes, embutimos en tripa natural, dejamos secar una noche a temperatura ambiente en un lugar fresco y protegido, y luego reposamos 24 horas más en refrigeración. Al día siguiente tendrás unos chorizos listos para asar, freír o cocinar, con un sabor tradicional que nunca pasa de moda. 🔥","callToAction":"💬 Comenta “CHORIZO SANTAROSANO” y te envío la receta completa con el paso a paso.","hashtags":["#ChorizoSantarrosano","#ChorizoArtesanal","#ChorizoColombiano","#Charcuteria","#Embutidos","#Parrilla","#BBQ","#Recetas","#HechoEnCasa","#FoodTok","#Cocina","#Carnes","#MeatLovers","#ReelsColombia","#FYP"]}}$receta$::jsonb, 110),
  ('chistorra', 'Chistorra', 'chorizos', '{"España","Semicurado","Parrillero"}', '/recipes/chistorra.jpg', 'España · 1 kg', 'embutir-un-chorizo', $receta${"slug":"chistorra","name":"Chistorra","description":"Navarra en formato fino — muy jugosa, pimentón y ajo, oreada pocos días y hecha a la sartén o brasa.","image":"/recipes/chistorra.jpg","tags":["España","Semicurado","Parrillero"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Fina, roja y jugosa; lista en pocos días.","intro":"La chistorra es el chorizo fresco-oreado de Navarra y el País Vasco: fina, muy jugosa y roja por el pimentón. No es un curado largo — se orea apenas unos días y se cocina. Su calibre delgado la hace ideal para la sartén, la brasa o el pincho. Rica en grasa, con ajo y pimentón al frente, es pura contundencia en poco diámetro.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Fresco-oreado"},{"label":"Nivel","value":"Intermedio"},{"label":"Tiempo de preparación","value":"45 min"},{"label":"Oreo","value":"1–3 días"},{"label":"Tipo de tripa","value":"Natural de cordero, cal. 20–22 mm"}],"details":[{"title":"Origen","description":"Cerdo con alta proporción de tocino, molido fino para un calibre delgado."},{"title":"Textura","description":"Muy jugosa; el 30% de grasa se funde al cocinar y la hace melosa."},{"title":"Sabor","description":"Pimentón y ajo dominan; perfil directo y contundente."}],"quote":"La chistorra no busca curar: busca jugosidad. Por eso lleva más grasa y menos tiempo que un chorizo de bodega.","ingredientsNote":"Aquí va sal de cura #1, no #2. La #1 lleva nitrito, que actúa desde el primer día y es lo que hace falta en un oreo de 1–3 días. La #2 lleva además nitrato, que necesita semanas para convertirse en nitrito: en tres días no te protege de nada. Muele fino: la chistorra es de textura homogénea, no de grano grueso.","ingredients":[{"name":"Carne de cerdo (magro)","amount":"700 g","pct":"70%"},{"name":"Tocino de cerdo","amount":"300 g","pct":"30%"},{"name":"Pimentón dulce","amount":"25 g","pct":"2.5%"},{"name":"Ajo fresco triturado","amount":"15 g","pct":"1.5%"},{"name":"Sal","amount":"22 g","pct":"2.2%"},{"name":"Sal de cura #1 (nitrificante)","amount":"2.5 g","pct":"0.25%"},{"name":"Pimienta negra","amount":"3 g","pct":"0.3%"},{"name":"Agua helada","amount":"20 ml","pct":"2%"}],"proportionNote":"70% magro y 30% tocino: la chistorra es deliberadamente grasa, y eso es lo que la hace jugosa al cocinarla. No bajes mucho la grasa o pierde su carácter.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y tocino. La sal de cura #1 protege durante el oreo corto: 2,5 g por kilo es el estándar y también el techo, nunca más. La regla general del oficio: #1 para lo corto y para todo lo que se cocina —que es el caso de la chistorra—, #2 solo para curados largos en seco, de semanas o meses.","steps":[{"n":"01","text":"Mezcla los secos aparte: pimentón, sal, sal de cura #1, ajo y pimienta. Hacerlo en un bol antes de tocar la carne es lo único que garantiza que la sal de cura quede repartida pareja."},{"n":"02","text":"Corta magro y tocino en cubos, muy fríos (0–2 °C)."},{"n":"03","text":"Muele fino con disco de 6 mm."},{"n":"04","text":"Integra los secos con el agua helada; amasa hasta ligar bien."},{"n":"05","text":"Embute en tripa fina de cordero (20–22 mm) sin bolsas de aire."},{"n":"06","text":"Forma rollos o tiras largas."},{"n":"07","text":"Orea 1–3 días a 12–15 °C antes de cocinar."}],"tips":[{"title":"Muele fino","description":"La chistorra es de textura homogénea; el disco de 6 mm da su mordida característica."},{"title":"Calibre delgado","description":"La tripa de cordero (20–22 mm) es clave: define su formato fino y su cocción rápida."},{"title":"Oreo corto, y por eso sal de cura #1","description":"Unos días a 12–15 °C bastan; no es un curado largo. Y como es corto y además se cocina, la sal que corresponde es la #1: el nitrito actúa de inmediato. La #2 ahí no hace nada."}],"cookMethods":[{"title":"Sartén","description":"Fuego medio 5–7 minutos; suelta su grasa y queda dorada y melosa."},{"title":"Brasa o pincho","description":"En pincho sobre brasa, rápido; ideal en pan como bocado."}],"recommendations":["Usa buena proporción de tocino: la jugosidad es su firma.","Muele fino con disco de 6 mm.","Orea solo unos días; siempre se consume cocinada.","Emplea tripa fina de cordero para el calibre correcto."],"resultNote":"El resultado: una chistorra fina, roja y jugosa, que al calor suelta su grasa y se vuelve melosa. Poco diámetro, mucho sabor.","finalQuote":"La chistorra demuestra que el formato importa: la misma masa en tripa fina y con poco oreo es otro producto entero. Técnica, no solo receta.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 120),
  ('salchichon', 'Salchichón', 'chorizos', '{"España","Curado"}', '/recipes/salchichon.jpg', 'España · 1 kg', 'embutir-un-chorizo', $receta${"slug":"salchichon","name":"Salchichón","description":"El curado de pimienta, no de pimentón — cerdo, granos de pimienta y vino, madurado al aire.","image":"/recipes/salchichon.jpg","tags":["España","Curado"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Pimienta en grano, sin pimentón.","intro":"El salchichón es el hermano del chorizo que renuncia al pimentón: aquí el protagonista es la pimienta negra, en grano y molida, sobre una base de cerdo y tocino curada al aire. Su sabor es más sobrio y elegante, con el punto aromático del vino blanco y un toque de nuez moscada. Un curado clásico que se sirve en lonchas finas.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Curado en seco"},{"label":"Nivel","value":"Avanzado"},{"label":"Tiempo de preparación","value":"50 min"},{"label":"Curado","value":"5–8 semanas"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 40–45 mm"}],"details":[{"title":"Origen","description":"Cerdo y tocino de calidad, molido medio, con granos de pimienta enteros."},{"title":"Textura","description":"Firme y compacta tras el curado; los granos de pimienta se ven al corte."},{"title":"Sabor","description":"Sobrio y aromático: pimienta al frente, ajo y vino de fondo, sin pimentón."}],"quote":"Quita el pimentón y todo cambia: el salchichón demuestra que un buen curado no necesita color para tener carácter.","ingredientsNote":"La pimienta en grano es la seña del salchichón. La sal de cura es obligatoria para un curado seguro.","ingredients":[{"name":"Carne de cerdo (magro)","amount":"800 g","pct":"80%"},{"name":"Tocino de cerdo","amount":"200 g","pct":"20%"},{"name":"Sal","amount":"26 g","pct":"2.6%"},{"name":"Pimienta negra en grano","amount":"5 g","pct":"0.5%"},{"name":"Pimienta negra molida","amount":"3 g","pct":"0.3%"},{"name":"Ajo fresco triturado","amount":"8 g","pct":"0.8%"},{"name":"Sal de cura (nitrificante, #2)","amount":"2.5 g","pct":"0.25%"},{"name":"Nuez moscada","amount":"1 g","pct":"0.1%"},{"name":"Vino blanco seco","amount":"30 ml","pct":"3%"}],"proportionNote":"80% magro y 20% tocino da un curado firme y elegante. La pimienta, entre grano y molida, define su perfil; ajústala al gusto.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y tocino. La sal de cura al 0.25% es el estándar seguro.","steps":[{"n":"01","text":"Mezcla los secos: sal, sal de cura, pimienta molida, ajo y nuez moscada."},{"n":"02","text":"Corta magro y tocino en cubos, muy fríos (0–2 °C)."},{"n":"03","text":"Muele con disco de 8 mm."},{"n":"04","text":"Integra los secos, los granos de pimienta enteros y el vino; amasa hasta ligar."},{"n":"05","text":"Macera en frío 24 h."},{"n":"06","text":"Embute firme en tripa de 40–45 mm y pincha para sacar el aire."},{"n":"07","text":"Cura a 12–15 °C y 75–80% de humedad, 5–8 semanas."}],"tips":[{"title":"Pimienta protagonista","description":"Combina grano y molida: el grano da textura y sorpresa, la molida da fondo aromático."},{"title":"Sin pimentón","description":"El salchichón se define por su ausencia de pimentón. Resiste la tentación de añadirlo."},{"title":"Curado controlado","description":"12–15 °C y 75–80% de humedad; sin control, el curado en casa es un riesgo."}],"cookMethods":[{"title":"En lonchas","description":"Curado, en lonchas finas a temperatura ambiente sobre pan."},{"title":"En tabla","description":"Junto a queso y frutos secos; su sobriedad marida con vinos tintos jóvenes."}],"recommendations":["Combina pimienta en grano y molida.","No añadas pimentón: rompe el perfil del salchichón.","No omitas la sal de cura.","Controla temperatura y humedad durante el curado."],"resultNote":"El resultado: un embutido firme, pálido y elegante, con los granos de pimienta a la vista y un aroma sobrio. La prueba de que el color no hace al curado.","finalQuote":"El salchichón es la elegancia de la charcutería: sin color que distraiga, todo depende de la carne, la pimienta y el tiempo.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 130),
  ('salchichon-cervecero-colombiano', 'Salchichón Cervecero Colombiano', 'chorizos', '{"Colombia","Ahumado","Cocido","Pollo"}', '/recipes/salchichon-cervecero-colombiano.jpg', 'Colombia', 'embutir-un-chorizo', $receta${"slug":"salchichon-cervecero-colombiano","name":"Salchichón Cervecero Colombiano","description":"El cervecero de toda la vida, hecho en casa — pollo, bondiola y panceta, especiado con ajo y comino y cocido hasta 75 °C para tajarlo frío.","image":"/recipes/salchichon-cervecero-colombiano.jpg","tags":["Colombia","Ahumado","Cocido","Pollo"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Pollo, bondiola y panceta; especiado, cocido y tajado en frío.","intro":"El salchichón cervecero es el embutido de la nevera colombiana: el de las arepas, el sándwich y la picada. Esta versión lo hace artesanal y le da un giro europeo — pechuga de pollo para la base magra, bondiola de cerdo para el sabor y panceta para la grasa que lo mantiene jugoso. Ajo, comino, pimienta y paprika le dan el perfil especiado que reconoces en cada tajada. Se embute en tripa de colágeno, se cocina u ahúma hasta los 75 °C internos y se enfría bien antes de cortar. Nada de humo frío: aquí se termina cocido.","stats":[{"label":"Rendimiento base","value":"1 kg de carne"},{"label":"Tipo","value":"Cocido (u ahumado cocido)"},{"label":"Nivel","value":"Intermedio"},{"label":"Tiempo de preparación","value":"1 h"},{"label":"Cocción","value":"80–150 °C hasta 75 °C internos"},{"label":"Tipo de tripa","value":"Colágeno, cal. 45–60 mm"}],"details":[{"title":"Origen","description":"Mezcla de pechuga de pollo (40%), bondiola de cerdo (30%) y panceta sin piel (30%)."},{"title":"Textura","description":"Emulsión fina y compacta; la panceta y el agua helada la vuelven jugosa y fácil de tajar."},{"title":"Sabor","description":"Especiado y aromático — ajo y comino al frente, paprika y pimienta de fondo."}],"quote":"El cervecero no se cura: se cocina. Por eso la clave está en la temperatura interna, no en el calendario.","ingredientsNote":"Si usas sal de cura, la cantidad depende de la concentración de nitrito del producto: no uses la misma dosis para sales de cura distintas. Con la Prague Powder #1 estándar (6,25% de nitrito), 2,5 g por kilo es el estándar y también el techo — y baja entonces la sal común a 14 g para no pasarte de sal. Es la #1, no la #2: esto se cocina y se come en días, no se cura durante semanas.","ingredients":[{"name":"Pechuga de pollo","amount":"400 g","pct":"40%"},{"name":"Bondiola de cerdo","amount":"300 g","pct":"30%"},{"name":"Panceta de cerdo sin piel","amount":"300 g","pct":"30%"},{"name":"Sal","amount":"16 g","pct":"1.6%"},{"name":"Sal de cura #1 (opcional, recomendada si ahúmas)","amount":"2.5 g","pct":"0.25%"},{"name":"Azúcar","amount":"2 g","pct":"0.2%"},{"name":"Ajo","amount":"4 g","pct":"0.4%"},{"name":"Comino","amount":"1 g","pct":"0.1%"},{"name":"Pimienta","amount":"2 g","pct":"0.2%"},{"name":"Paprika","amount":"2 g","pct":"0.2%"},{"name":"Agua helada","amount":"70 ml","pct":"7%"}],"proportionNote":"40% pollo, 30% bondiola y 30% panceta: el pollo aporta el magro, la bondiola el sabor y la panceta la grasa. Si bajas la panceta, el salchichón queda seco y se desmorona al tajarlo.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el kilo de carne. Por kilo: sal 16 g, azúcar 2 g, ajo 4 g, comino 1 g, pimienta 2 g, paprika 2 g y 70 ml de agua helada. El agua no es relleno: es lo que permite formar la emulsión y lo que se pierde en parte durante la cocción.","steps":[{"n":"01","text":"Mezcla los secos aparte: sal, sal de cura si la usas, azúcar, ajo, comino, pimienta y paprika. Repartirlos bien es lo único que garantiza una salazón pareja."},{"n":"02","text":"Corta el pollo, la bondiola y la panceta en cubos y déjalos muy fríos (0–2 °C)."},{"n":"03","text":"Muele con disco de 4–6 mm, manteniendo la carne casi congelada."},{"n":"04","text":"Agrega los secos y el agua helada; amasa hasta que la masa quede pegajosa y ligada — esa es la emulsión."},{"n":"05","text":"Vigila la temperatura de la masa: no debe pasar de 8–10 °C. Si se calienta, al frío otra vez."},{"n":"06","text":"Embute en tripa de colágeno (45–60 mm) bien apretado, sin bolsas de aire, y ata los extremos."},{"n":"07","text":"Cocina u ahúma entre 80 y 150 °C hasta que el centro marque 75 °C."},{"n":"08","text":"Enfría rápido y refrigera varias horas antes de cortar: frío, taja firme y bonito."}],"tips":[{"title":"Todo muy frío","description":"Pollo y panceta pierden la emulsión con el calor. Trabaja casi congelado y no alargues el amasado."},{"title":"El termómetro manda","description":"No lo saques por tiempo: sácalo a 75 °C internos. Menos es inseguro; más lo reseca."},{"title":"Sal de cura solo si ahúmas","description":"Si lo vas a ahumar a baja temperatura, la #1 es lo correcto. Si lo horneas y lo comes en pocos días, puedes ir sin ella — pero nunca con la #2."},{"title":"Frío antes del cuchillo","description":"Tajarlo tibio lo desarma. Refrigéralo entero y córtalo al día siguiente."}],"cookMethods":[{"title":"Ahumador","description":"Entre 80 y 150 °C, humo suave, hasta los 75 °C en el centro. Aquí sí lleva sal de cura #1."},{"title":"Horno","description":"Entre 80 y 150 °C hasta los 75 °C internos; una bandeja con agua ayuda a que no se reseque."},{"title":"A la sartén, ya frío","description":"Tajadas gruesas doradas un minuto por lado, para arepa o sándwich."}],"recommendations":["Mantén la masa por debajo de 8–10 °C durante todo el proceso.","Embute apretado: las bolsas de aire dejan huecos al tajar.","Cocina hasta 75 °C internos, medidos con termómetro.","Enfría y refrigera antes de cortar."],"resultNote":"El resultado: un salchichón cervecero casero, jugoso y aromático, de corte compacto y parejo. Perfecto para la arepa, el sándwich, la picada o unas tajadas directas de la nevera.","finalQuote":"El cervecero de la tienda es un producto industrial; este es el mismo sabor, pero sabiendo exactamente qué lleva. Ahí está la diferencia del oficio.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 140),
  ('salchichon-iberico', 'Salchichón Ibérico', 'chorizos', '{"España","Curado"}', '/recipes/salchichon-iberico.jpg', 'España · 1 kg', 'embutir-un-chorizo', $receta${"slug":"salchichon-iberico","name":"Salchichón Ibérico","description":"Salchichón de cerdo ibérico — más veteado y untuoso, con pimienta en grano y curado largo.","image":"/recipes/salchichon-iberico.jpg","tags":["España","Curado"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"La versión ibérica: más grasa infiltrada, más sabor.","intro":"El salchichón ibérico eleva el clásico con carne de cerdo ibérico: su grasa infiltrada aporta untuosidad y un aroma más profundo. Como todo salchichón, prescinde del pimentón y confía en la pimienta negra. El curado es más largo para que la grasa desarrolle sus matices. Un producto de tabla, para lonchear fino y disfrutar sin prisa.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Curado en seco"},{"label":"Nivel","value":"Avanzado"},{"label":"Tiempo de preparación","value":"50 min"},{"label":"Curado","value":"8–12 semanas"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 45–50 mm"}],"details":[{"title":"Origen","description":"Cerdo ibérico, con grasa infiltrada que da untuosidad al curado."},{"title":"Textura","description":"Untuosa y firme; la grasa veteada se funde en boca."},{"title":"Sabor","description":"Pimienta al frente sobre un fondo profundo de cerdo ibérico curado."}],"quote":"La grasa del ibérico no es un defecto que ocultar: es el ingrediente que define el sabor. Por eso el salchichón ibérico se curó más tiempo.","ingredientsNote":"El curado más largo exige aún más rigor con la sal de cura y las condiciones. Pésalo todo con precisión.","ingredients":[{"name":"Carne de cerdo ibérico (magro)","amount":"800 g","pct":"80%"},{"name":"Tocino ibérico","amount":"200 g","pct":"20%"},{"name":"Sal","amount":"26 g","pct":"2.6%"},{"name":"Pimienta negra en grano","amount":"6 g","pct":"0.6%"},{"name":"Pimienta negra molida","amount":"3 g","pct":"0.3%"},{"name":"Ajo fresco triturado","amount":"8 g","pct":"0.8%"},{"name":"Sal de cura (nitrificante, #2)","amount":"2.5 g","pct":"0.25%"},{"name":"Vino blanco seco","amount":"30 ml","pct":"3%"}],"proportionNote":"80% magro ibérico y 20% tocino; la grasa infiltrada del propio magro añade untuosidad extra. El curado largo concentra ese sabor.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y tocino. La sal de cura al 0.25% es innegociable en curados largos.","steps":[{"n":"01","text":"Mezcla los secos: sal, sal de cura, pimienta molida y ajo."},{"n":"02","text":"Corta magro y tocino ibérico en cubos, muy fríos (0–2 °C)."},{"n":"03","text":"Muele con disco de 8 mm."},{"n":"04","text":"Integra los secos, los granos de pimienta y el vino; amasa hasta ligar."},{"n":"05","text":"Macera en frío 24 h."},{"n":"06","text":"Embute firme en tripa de 45–50 mm y pincha."},{"n":"07","text":"Cura a 12–15 °C y 75–80% de humedad, 8–12 semanas."}],"tips":[{"title":"Grasa infiltrada","description":"El ibérico da untuosidad natural. No compenses con más tocino: deja que la carne hable."},{"title":"Curado paciente","description":"El calibre mayor y la grasa piden más semanas. Apúrate y quedará ácido o blando."},{"title":"Sal de cura","description":"En curados largos es imprescindible para un producto seguro."}],"cookMethods":[{"title":"En lonchas","description":"Curado, en lonchas muy finas a temperatura ambiente para apreciar la untuosidad."},{"title":"En tabla","description":"Protagonista de tabla ibérica, con pan y un tinto con cuerpo."}],"recommendations":["Usa cerdo ibérico de buena grasa infiltrada.","Cura más tiempo por el calibre mayor.","No omitas la sal de cura.","Controla temperatura y humedad durante el curado."],"resultNote":"El resultado: un salchichón untuoso y aromático, con veteado de grasa que se funde en boca. La versión más golosa del clásico de pimienta.","finalQuote":"El salchichón ibérico premia la paciencia: más semanas, más grasa infiltrada, más sabor. El tiempo, como siempre, hace el trabajo.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 150),
  ('chourico-portugues', 'Chouriço Português', 'chorizos', '{"Portugal","Ahumado","Cocido"}', '/recipes/chourico-portugues.jpg', 'Portugal · 1 kg', 'embutir-un-chorizo', $receta${"slug":"chourico-portugues","name":"Chouriço Português","description":"El ahumado luso — carne macerada en vino y ajo, pimentón, humo de encina y cocción a 75 °C.","image":"/recipes/chourico-portugues.jpg","tags":["Portugal","Ahumado","Cocido"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Vinho, alho, colorau e fumo.","intro":"El chouriço portugués nace de una maceración: la carne descansa en vino tinto, ajo y pimentón (colorau) antes de embutirse, y luego se ahúma lentamente sobre leña. Ese doble proceso — vino y humo — le da su color oscuro y su aroma profundo. Es más rústico y ahumado que el chorizo español, y base de platos como la feijoada y el cozido.\n\n⚠️ ESTA ES LA VERSIÓN COCIDA, adaptada al clima colombiano. La tradicional se ahúma en frío varios días y se cuelga a orear, y eso pide un ambiente estable de 12–15 °C que aquí casi nadie tiene: a 25 °C o más, cuatro días de humo frío sobre carne picada cruda no es ahumado, es incubación. Al terminarla a 75 °C internos queda algo más firme y menos seco que la original, y se puede hacer con seguridad en cualquier cocina.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Ahumado y cocido"},{"label":"Nivel","value":"Avanzado"},{"label":"Tiempo de preparación","value":"50 min"},{"label":"Piel + ahumado","value":"12–24 h en nevera + humo a 80–150 °C"},{"label":"Temperatura interna","value":"75 °C"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 38–40 mm"}],"details":[{"title":"Origen","description":"Cerdo troceado (no siempre molido fino), macerado en vino y ajo."},{"title":"Textura","description":"Rústica, de trozos visibles; el ahumado la seca y compacta."},{"title":"Sabor","description":"Vino, ajo y pimentón, con el humo de encina como firma inconfundible."}],"quote":"El chouriço no se entiende sin humo: la maceración en vino pone la base, pero es la leña la que lo define.","ingredientsNote":"Macera la carne en vino y ajo antes de embutir. Aquí la sal de cura #1 NO es opcional. Aunque la pieza termine cocida a 75 °C, antes pasa horas formando piel y tomando humo por debajo de esa temperatura: ese es el rato de riesgo, y es justo el rango donde el Clostridium botulinum trabaja mejor. Va la #1 porque su nitrito actúa desde el primer minuto; el nitrato de la #2 necesita semanas y una bacteria que lo convierta, y aquí no hay ni lo uno ni lo otro.","ingredients":[{"name":"Carne de cerdo (paleta)","amount":"800 g","pct":"80%"},{"name":"Tocino de cerdo","amount":"200 g","pct":"20%"},{"name":"Vino tinto","amount":"50 ml","pct":"5%"},{"name":"Pimentón dulce (colorau)","amount":"20 g","pct":"2%"},{"name":"Ajo fresco triturado","amount":"20 g","pct":"2%"},{"name":"Sal","amount":"24 g","pct":"2.4%"},{"name":"Sal de cura #1 (nitrificante)","amount":"2.5 g","pct":"0.25%"},{"name":"Pimentón picante (piri-piri)","amount":"5 g","pct":"0.5%"},{"name":"Hoja de laurel molida","amount":"1 g","pct":"0.1%"}],"proportionNote":"80% carne y 20% tocino, con el vino al 5%. La maceración previa hace que el vino y el ajo penetren la carne antes de moler o picar.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y tocino. La sal de cura #1 al 0,25% protege las horas de piel y humo que hay antes de la cocción. 2,5 g por kilo es el estándar y también el techo, nunca más.","steps":[{"n":"01","text":"Trocea o pica grueso la carne y el tocino, muy fríos."},{"n":"02","text":"Macera 24 h en frío con vino, ajo, pimentones, sal, sal de cura #1 y laurel."},{"n":"03","text":"Escurre ligeramente conservando el adobo pegado a la carne."},{"n":"04","text":"Embute firme en tripa de 38–40 mm y ata en herradura."},{"n":"05","text":"Orea en la NEVERA, destapada sobre rejilla, 12–24 h, hasta que la tripa quede seca al tacto. Esa piel es lo que hace que el humo se agarre. En nevera y no al ambiente: aquí hace demasiado calor."},{"n":"06","text":"Ahúma EN CALIENTE, entre 80 y 150 °C. Empieza por abajo —80–100 °C la primera media hora— y sube después. Si arrancas fuerte, la grasa se funde antes de que el centro se caliente y la tripa revienta."},{"n":"07","text":"Cocina hasta que el CENTRO marque 75 °C. Mide con termómetro en la pieza más gruesa, nunca por tiempo: el calibre y la carga del ahumador cambian cuánto tarda."},{"n":"08","text":"Enfría de golpe en agua con hielo hasta que esté fría al tacto. Seca, y a la nevera. Aguanta una semana refrigerada, o congelada varios meses."}],"tips":[{"title":"La maceración","description":"Las 24 h en vino y ajo son el corazón del chouriço; no las saltes."},{"title":"Empieza flojo y sube","description":"80–100 °C la primera media hora, y de ahí para arriba. Si la metes de golpe a 150 °C, la grasa sale antes de que el centro suba y te quedas con la tripa rota y el embutido seco."},{"title":"El termómetro manda sobre el reloj","description":"75 °C en el CENTRO, medidos en la pieza más gruesa. La temperatura del ahumador dice a qué ritmo va; la del centro dice cuándo está."},{"title":"Sal de cura #1, no #2","description":"Las horas de piel y de humo, antes de llegar a los 75 °C, son el rato en que la carne picada cruda está expuesta. Va la #1 porque su nitrito actúa desde el primer minuto; el nitrato de la #2 necesita semanas y una bacteria que lo convierta, y aquí no hay ni lo uno ni lo otro. No la omitas por llevar cocción al final."},{"title":"El enfriado de golpe no es acabado, es seguridad","description":"En cuanto llega a 75 °C, al agua con hielo hasta que esté fría al tacto. Corta la cocción residual y saca la pieza del rango de temperatura donde crecen las bacterias, en vez de dejarla enfriando despacio dentro de él."}],"cookMethods":[{"title":"Para guisar","description":"En rodajas, base de feijoada, cozido y caldo verde. Ya viene cocido."},{"title":"Assado / à bombeiro","description":"Flameado con aguardiente en el clásico chouriço à bombeiro."}],"recommendations":["Respeta las 24 h de maceración en vino y ajo.","No omitas la sal de cura #1: antes de los 75 °C hay horas de riesgo.","Usa leña de encina o roble para el aroma correcto.","Ahúma entre 80 y 150 °C, empezando por abajo para no reventar la tripa.","Da la pieza por lista a 75 °C internos, y enfríala de golpe."],"resultNote":"El resultado: un chouriço oscuro, rústico y profundamente ahumado, con el vino y el ajo integrados — y ya cocido, listo para la feijoada o el cozido.","finalQuote":"El chouriço enseña que el humo es un ingrediente más — y de los que más mandan. Sin buena leña, no hay buen chouriço.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 160),
  ('linguica-portuguesa', 'Linguiça Portuguesa', 'chorizos', '{"Portugal","Ahumado","Parrillero","Cocido"}', '/recipes/linguica-portuguesa.jpg', 'Portugal · 1 kg', 'embutir-un-chorizo', $receta${"slug":"linguica-portuguesa","name":"Linguiça Portuguesa","description":"Más fina que el chouriço — ajo, pimentón y vino, ahumada y cocida a 75 °C. Fundamental en la parrilla lusa.","image":"/recipes/linguica-portuguesa.jpg","tags":["Portugal","Ahumado","Parrillero","Cocido"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"La hermana fina del chouriço, ya cocida.","intro":"La linguiça es la versión más fina y menos grasa del embutido portugués: se macera en vino y ajo, se sazona con pimentón (colorau) y se ahúma lento, pero en un calibre delgado que la hace ideal para la parrilla y el pan. Menos rústica que el chouriço, comparte su alma ahumada. Un toque de piri-piri le da el punto justo de calor.\n\n⚠️ ESTA ES LA VERSIÓN COCIDA, adaptada al clima colombiano. La tradicional se ahúma en frío varios días y se cuelga a orear, y eso pide un ambiente estable de 12–15 °C que aquí casi nadie tiene: a 25 °C o más, cuatro días de humo frío sobre carne picada cruda no es ahumado, es incubación. Al terminarla a 75 °C internos queda algo más firme y menos seco que la original, y se puede hacer con seguridad en cualquier cocina.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Ahumado y cocido"},{"label":"Nivel","value":"Intermedio–Avanzado"},{"label":"Tiempo de preparación","value":"50 min"},{"label":"Piel + ahumado","value":"12–24 h en nevera + humo a 80–150 °C"},{"label":"Temperatura interna","value":"75 °C"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 30–32 mm"}],"details":[{"title":"Origen","description":"Cerdo magro con algo de tocino, macerado en vino y ajo."},{"title":"Textura","description":"Más firme y magra que el chouriço; el ahumado la seca ligeramente."},{"title":"Sabor","description":"Ajo y pimentón sobre fondo ahumado, con un punto de piri-piri."}],"quote":"La linguiça demuestra que el mismo adobo, en tripa fina y con menos grasa, cuenta otra historia.","ingredientsNote":"Macera la carne en vino y ajo antes de embutir. Aquí la sal de cura #1 NO es opcional. Aunque la pieza termine cocida a 75 °C, antes pasa horas formando piel y tomando humo por debajo de esa temperatura: ese es el rato de riesgo, y es justo el rango donde el Clostridium botulinum trabaja mejor. Va la #1 porque su nitrito actúa desde el primer minuto; el nitrato de la #2 necesita semanas y una bacteria que lo convierta, y aquí no hay ni lo uno ni lo otro.","ingredients":[{"name":"Carne de cerdo (paleta)","amount":"850 g","pct":"85%"},{"name":"Tocino de cerdo","amount":"150 g","pct":"15%"},{"name":"Vino blanco","amount":"40 ml","pct":"4%"},{"name":"Pimentón dulce (colorau)","amount":"15 g","pct":"1.5%"},{"name":"Ajo fresco triturado","amount":"15 g","pct":"1.5%"},{"name":"Sal","amount":"22 g","pct":"2.2%"},{"name":"Sal de cura #1 (nitrificante)","amount":"2.5 g","pct":"0.25%"},{"name":"Piri-piri (guindilla)","amount":"4 g","pct":"0.4%"},{"name":"Hoja de laurel molida","amount":"1 g","pct":"0.1%"}],"proportionNote":"85% carne y 15% tocino: más magra que el chouriço. Esa es la diferencia de textura entre ambos, con el mismo perfil de adobo.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y tocino. La sal de cura #1 al 0,25% protege las horas de piel y humo que hay antes de la cocción. 2,5 g por kilo es el estándar y también el techo, nunca más.","steps":[{"n":"01","text":"Pica grueso la carne y el tocino, muy fríos."},{"n":"02","text":"Macera 24 h en frío con vino, ajo, pimentón, sal, sal de cura #1, piri-piri y laurel."},{"n":"03","text":"Embute firme en tripa fina de cerdo (30–32 mm)."},{"n":"04","text":"Ata en tramos y forma aros o tiras."},{"n":"05","text":"Orea en la NEVERA, destapada sobre rejilla, 12–24 h, hasta que la tripa quede seca al tacto. Esa piel es lo que hace que el humo se agarre. En nevera y no al ambiente: aquí hace demasiado calor."},{"n":"06","text":"Ahúma EN CALIENTE, entre 80 y 150 °C. Empieza por abajo —80–100 °C la primera media hora— y sube después. Si arrancas fuerte, la grasa se funde antes de que el centro se caliente y la tripa revienta."},{"n":"07","text":"Cocina hasta que el CENTRO marque 75 °C. Mide con termómetro en la pieza más gruesa, nunca por tiempo: el calibre y la carga del ahumador cambian cuánto tarda."},{"n":"08","text":"Enfría de golpe en agua con hielo hasta que esté fría al tacto. Seca, y a la nevera. Aguanta una semana refrigerada, o congelada varios meses."}],"tips":[{"title":"Calibre fino","description":"El diámetro delgado (30–32 mm) es lo que la separa del chouriço; respeta la tripa fina."},{"title":"Empieza flojo y sube","description":"80–100 °C la primera media hora, y de ahí para arriba. Si la metes de golpe a 150 °C, la grasa sale antes de que el centro suba y te quedas con la tripa rota y el embutido seco."},{"title":"El termómetro manda sobre el reloj","description":"75 °C en el CENTRO, medidos en la pieza más gruesa. La temperatura del ahumador dice a qué ritmo va; la del centro dice cuándo está."},{"title":"Piri-piri al gusto","description":"Ajusta la guindilla según cuánto calor busques; la linguiça admite desde suave a picante."},{"title":"El enfriado de golpe no es acabado, es seguridad","description":"En cuanto llega a 75 °C, al agua con hielo hasta que esté fría al tacto. Corta la cocción residual y saca la pieza del rango de temperatura donde crecen las bacterias, en vez de dejarla enfriando despacio dentro de él."}],"cookMethods":[{"title":"Parrilla","description":"A la brasa hasta dorar. Ya viene cocida: es dorar y templar, no cocinar."},{"title":"Para guisar","description":"En rodajas, aporta ahumado a arroces, feijoadas y caldos."}],"recommendations":["Respeta la maceración de 24 h.","Usa tripa fina para el calibre correcto.","No omitas la sal de cura #1: antes de los 75 °C hay horas de riesgo.","Ahúma entre 80 y 150 °C, empezando por abajo para no reventar la tripa.","Da la pieza por lista a 75 °C internos, y enfríala de golpe."],"resultNote":"El resultado: una linguiça firme y ahumada, más esbelta que el chouriço y ya cocida. El ajo y el humo, en formato fino y listos para la brasa.","finalQuote":"La linguiça y el chouriço comparten adobo pero no destino: el calibre y la grasa definen a cuál llega tu parrilla.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 170),
  ('linguica-calabresa', 'Linguiça Calabresa', 'chorizos', '{"Brasil","Ahumado","Picante","Cocido"}', '/recipes/linguica-calabresa.jpg', 'Brasil · 1 kg', 'embutir-un-chorizo', $receta${"slug":"linguica-calabresa","name":"Linguiça Calabresa","description":"El ahumado picante de Brasil — pimienta calabresa y páprica, ahumada y cocida a 75 °C. Reina de la pizza y la feijoada.","image":"/recipes/linguica-calabresa.jpg","tags":["Brasil","Ahumado","Picante","Cocido"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Ahumada, picante y lista para usar.","intro":"La calabresa es el embutido más popular de Brasil: de cerdo, ahumada y con el picor característico de la pimienta calabresa (guindilla en hojuelas). Aunque su nombre remite a Calabria, es una creación brasileña, presente en la pizza, la feijoada y el churrasco. Firme, roja y con fuego, se cura y ahúma lento hasta concentrar su sabor.\n\n⚠️ ESTA ES LA VERSIÓN COCIDA, adaptada al clima colombiano. La tradicional se ahúma en frío varios días y se cuelga a orear, y eso pide un ambiente estable de 12–15 °C que aquí casi nadie tiene: a 25 °C o más, cuatro días de humo frío sobre carne picada cruda no es ahumado, es incubación. Al terminarla a 75 °C internos queda algo más firme y menos seco que la original, y se puede hacer con seguridad en cualquier cocina.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Ahumado y cocido"},{"label":"Nivel","value":"Intermedio–Avanzado"},{"label":"Tiempo de preparación","value":"50 min"},{"label":"Piel + ahumado","value":"12–24 h en nevera + humo a 80–150 °C"},{"label":"Temperatura interna","value":"75 °C"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 34–38 mm"}],"details":[{"title":"Origen","description":"Cerdo con tocino, molido medio; se ahúma para su sabor característico."},{"title":"Textura","description":"Firme tras el ahumado; se corta en rodajas sin desarmarse."},{"title":"Sabor","description":"Picante de pimienta calabresa y páprica, con fondo ahumado."}],"quote":"La calabresa no es italiana pese a su nombre: es puro Brasil, y el humo con el picante son su firma.","ingredientsNote":"El picante viene de la pimienta calabresa (guindilla en hojuelas). Aquí la sal de cura #1 no es opcional aunque haya cocción: antes del humo caliente hay entre 12 y 24 horas formando piel, y es carne picada cruda. Va la #1 porque su nitrito actúa desde el primer minuto; el nitrato de la #2 necesita semanas y una bacteria que lo convierta, y aquí no hay ni lo uno ni lo otro. Además es la que da el color rojo del ahumado en vez del pardo de la carne cocida.","ingredients":[{"name":"Carne de cerdo (paleta)","amount":"800 g","pct":"80%"},{"name":"Grasa de cerdo","amount":"200 g","pct":"20%"},{"name":"Pimienta calabresa (hojuelas)","amount":"15 g","pct":"1.5%"},{"name":"Páprica picante","amount":"10 g","pct":"1%"},{"name":"Ajo fresco triturado","amount":"15 g","pct":"1.5%"},{"name":"Sal","amount":"22 g","pct":"2.2%"},{"name":"Sal de cura #1 (nitrificante)","amount":"2.5 g","pct":"0.25%"},{"name":"Pimienta negra","amount":"3 g","pct":"0.3%"},{"name":"Agua helada","amount":"20 ml","pct":"2%"}],"proportionNote":"80% carne y 20% grasa da firmeza para rodajas y jugosidad al fundirse en la pizza. Ajusta el picante con la cantidad de pimienta calabresa.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. La sal de cura #1 al 0,25% protege las horas de piel que hay antes del humo, y es la que sostiene el color. 2,5 g por kilo es el estándar y también el techo, nunca más.","steps":[{"n":"01","text":"Mezcla los secos: pimienta calabresa, páprica, sal, sal de cura #1 y pimienta negra."},{"n":"02","text":"Corta la carne y la grasa en cubos, muy fríos (0–2 °C)."},{"n":"03","text":"Muele con disco de 8 mm."},{"n":"04","text":"Integra los secos, el ajo y el agua helada; amasa hasta ligar."},{"n":"05","text":"Embute firme en tripa de 34–38 mm y forma aros."},{"n":"06","text":"Orea en la NEVERA, destapada sobre rejilla, 12–24 h, hasta que la tripa quede seca al tacto. Esa piel es lo que hace que el humo se agarre: sobre tripa húmeda el humo resbala y el color queda desigual."},{"n":"07","text":"Ahúma EN CALIENTE, entre 80 y 150 °C. Empieza por abajo —80–100 °C la primera media hora— y sube después. Si arrancas fuerte, la grasa se funde antes de que el centro se caliente y la tripa revienta: sale seca por dentro y rota por fuera."},{"n":"08","text":"Cocina hasta que el CENTRO marque 75 °C. Mide con termómetro en la pieza más gruesa, nunca por tiempo: a 150 °C un aro de 34 mm llega en poco más de media hora, y pasarse de ahí solo le saca grasa."},{"n":"09","text":"Enfría de golpe en agua con hielo hasta que esté fría al tacto. Seca, y a la nevera. Aguanta una semana refrigerada, o congelada varios meses."}],"tips":[{"title":"Pimienta calabresa","description":"Las hojuelas de guindilla dan el picor y el aspecto moteado típico. Son insustituibles."},{"title":"Empieza flojo y sube","description":"80–100 °C la primera media hora, y de ahí para arriba. El calibre de la calabresa es fino: si la metes de golpe a 150 °C, la grasa sale antes de que el centro suba y te quedas con una tripa rota y un embutido seco."},{"title":"El termómetro manda sobre el reloj","description":"75 °C en el CENTRO, medidos en la pieza más gruesa. La temperatura del ahumador dice a qué ritmo va; la del centro dice cuándo está."},{"title":"El enfriado de golpe no es acabado, es seguridad","description":"En cuanto llega a 75 °C, al agua con hielo hasta que esté fría al tacto. Corta la cocción residual y saca la pieza del rango de temperatura donde crecen las bacterias, en vez de dejarla enfriando despacio dentro de él."}],"cookMethods":[{"title":"En rodajas","description":"Ya viene cocida: sobre la pizza o en la feijoada solo se calienta y suelta su humo."},{"title":"Parrilla","description":"A la brasa, solo para dorar y templar. No hay que cocinarla, ya lo está."}],"recommendations":["Usa pimienta calabresa en hojuelas para el picor correcto.","No omitas la sal de cura #1: antes del humo hay 12–24 h de carne picada cruda.","Ahúma entre 80 y 150 °C, empezando por abajo para no reventar la tripa.","Da la pieza por lista a 75 °C internos, medidos con termómetro.","Enfría en agua con hielo en cuanto llegue: es parte de la seguridad."],"resultNote":"El resultado: una calabresa firme, roja y ahumada, con el picor moteado a la vista — y ya cocida, lista para la pizza, la feijoada o la brasa.","finalQuote":"La calabresa enseña que el humo y el picante, bien medidos, hacen un embutido que trasciende fronteras — de Calabria de nombre, brasileño de alma.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 180),
  ('sobrasada', 'Sobrasada de Mallorca', 'chorizos', '{"España","Curado","Untable"}', '/recipes/sobrasada.jpg', 'España · 1 kg', 'embutir-un-chorizo', $receta${"slug":"sobrasada","name":"Sobrasada de Mallorca","description":"El curado untable — carne y grasa molidas muy fino, mucho pimentón, madurado hasta poder untarse.","image":"/recipes/sobrasada.jpg","tags":["España","Curado","Untable"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"El único chorizo que se unta.","intro":"La sobrasada rompe las reglas: en lugar de cortarse, se unta. Carne y grasa de cerdo se muelen muy fino, se sazonan con abundante pimentón y se embuten para curarse lento hasta lograr una pasta blanda y anaranjada. Originaria de Mallorca, es única entre los embutidos curados por su textura cremosa. El pimentón — dulce, con un punto picante — es su alma.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Curado untable"},{"label":"Nivel","value":"Avanzado"},{"label":"Tiempo de preparación","value":"50 min"},{"label":"Curado","value":"4–8 semanas"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 40–45 mm"}],"details":[{"title":"Origen","description":"Cerdo y bastante grasa, molidos muy fino para una textura de pasta."},{"title":"Textura","description":"Blanda y untable; la alta grasa y el molido fino la hacen cremosa."},{"title":"Sabor","description":"Pimentón dominante — dulce y algo picante — con fondo de cerdo curado."}],"quote":"La sobrasada demuestra que el curado no siempre busca firmeza: aquí el objetivo es una pasta cremosa que se unta.","ingredientsNote":"Muele muy fino y usa bastante grasa: sin ella, la sobrasada no queda untable. La sal de cura es obligatoria.","ingredients":[{"name":"Carne de cerdo (magro)","amount":"700 g","pct":"70%"},{"name":"Tocino de cerdo","amount":"300 g","pct":"30%"},{"name":"Pimentón dulce","amount":"40 g","pct":"4%"},{"name":"Pimentón picante","amount":"10 g","pct":"1%"},{"name":"Sal","amount":"24 g","pct":"2.4%"},{"name":"Sal de cura (nitrificante, #2)","amount":"2.5 g","pct":"0.25%"},{"name":"Pimienta negra","amount":"3 g","pct":"0.3%"}],"proportionNote":"70% magro y 30% tocino: la alta proporción de grasa es lo que hace posible la textura untable. Bajarla mucho arruina el resultado.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y tocino. La sal de cura al 0.25% mantiene seguro el curado lento.","steps":[{"n":"01","text":"Mezcla los secos: pimentones, sal, sal de cura y pimienta."},{"n":"02","text":"Corta magro y tocino en cubos, muy fríos (0–2 °C)."},{"n":"03","text":"Muele fino con disco de 4–6 mm; repite si es necesario."},{"n":"04","text":"Integra los secos y amasa hasta una pasta homogénea y roja."},{"n":"05","text":"Embute en tripa de 40–45 mm sin bolsas de aire."},{"n":"06","text":"Cura a 12–15 °C y 75–80% de humedad, sin secar en exceso."},{"n":"07","text":"Retira cuando esté firme por fuera y untable por dentro, 4–8 semanas."}],"tips":[{"title":"Molido muy fino","description":"El disco de 4–6 mm (o doble molido) da la textura cremosa característica."},{"title":"No secar de más","description":"A diferencia de un chorizo, la sobrasada no debe endurecer: cuida la humedad."},{"title":"Pimentón protagonista","description":"Es el ingrediente estrella, en cantidad generosa. Usa uno de calidad."}],"cookMethods":[{"title":"Para untar","description":"En pan tostado, sola o con miel; también sobre pizza o en salsas."},{"title":"En cocina","description":"Se deshace en guisos y sofritos, aportando color y grasa aromática."}],"recommendations":["Usa suficiente grasa: es la clave de lo untable.","Muele muy fino, incluso dos veces.","No dejes que seque en exceso durante el curado.","No omitas la sal de cura."],"resultNote":"El resultado: una pasta anaranjada, cremosa y aromática que se unta con el cuchillo. Curado, sí, pero con un objetivo opuesto a la firmeza.","finalQuote":"La sobrasada le enseña al charcutero que las reglas se doblan con criterio: aquí la grasa no se controla, se celebra.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 190),
  ('fuet', 'Fuet Catalán', 'chorizos', '{"España","Curado"}', '/recipes/fuet.jpg', 'España · 1 kg', 'embutir-un-chorizo', $receta${"slug":"fuet","name":"Fuet Catalán","description":"Curado fino con flor blanca — cerdo, pimienta y ajo suave, madurado hasta su moho noble exterior.","image":"/recipes/fuet.jpg","tags":["España","Curado"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Delgado, con flor blanca y sabor delicado.","intro":"El fuet es el embutido curado catalán por excelencia: delgado, sin pimentón, con un sabor delicado de cerdo, pimienta y ajo suave. Su seña visual es la flor blanca — el moho noble (penicillium) que lo recubre y protege durante el curado, aportando aroma. Se cura relativamente rápido por su calibre fino, y se come en rodajas finas como aperitivo.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Curado en seco"},{"label":"Nivel","value":"Avanzado"},{"label":"Tiempo de preparación","value":"50 min"},{"label":"Curado","value":"3–5 semanas"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 34–38 mm"}],"details":[{"title":"Origen","description":"Cerdo magro con tocino, molido medio, en tripa fina."},{"title":"Textura","description":"Firme pero tierna; el calibre fino cura sin resecar en exceso."},{"title":"Sabor","description":"Delicado: pimienta y ajo suave, sin pimentón, con el aroma del moho noble."}],"quote":"La flor blanca del fuet no es un defecto: es el moho noble que protege el curado y le da su aroma inconfundible.","ingredientsNote":"El fuet es delicado, así que el condimento es discreto. La sal de cura es obligatoria; la flor blanca se favorece con humedad y aireación.","ingredients":[{"name":"Carne de cerdo (magro)","amount":"800 g","pct":"80%"},{"name":"Tocino de cerdo","amount":"200 g","pct":"20%"},{"name":"Sal","amount":"26 g","pct":"2.6%"},{"name":"Pimienta negra molida","amount":"4 g","pct":"0.4%"},{"name":"Ajo fresco triturado","amount":"5 g","pct":"0.5%"},{"name":"Sal de cura (nitrificante, #2)","amount":"2.5 g","pct":"0.25%"},{"name":"Vino blanco seco","amount":"20 ml","pct":"2%"}],"proportionNote":"80% magro y 20% tocino da un fuet firme pero tierno. El condimento es mínimo a propósito: el fuet es sutileza, no potencia.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y tocino. La sal de cura al 0.25% es el estándar seguro.","steps":[{"n":"01","text":"Mezcla los secos: sal, sal de cura, pimienta y ajo."},{"n":"02","text":"Corta magro y tocino en cubos, muy fríos (0–2 °C)."},{"n":"03","text":"Muele con disco de 6–8 mm."},{"n":"04","text":"Integra los secos y el vino; amasa hasta ligar."},{"n":"05","text":"Embute firme en tripa de 34–38 mm sin bolsas de aire."},{"n":"06","text":"Opcional: aplica cultivo de moho noble en la superficie."},{"n":"07","text":"Cura a 12–15 °C y 80–85% de humedad, 3–5 semanas, hasta que aparezca la flor blanca."}],"tips":[{"title":"Flor blanca","description":"El penicillium noble protege y aromatiza. Favorécelo con buena humedad y algo de aireación."},{"title":"Condimento sutil","description":"El fuet no lleva pimentón; su gracia es la delicadeza. No lo sobrecondimentes."},{"title":"Curado controlado","description":"12–15 °C y humedad alta. Sin control, aparecen mohos indeseados en vez de la flor noble."}],"cookMethods":[{"title":"En rodajas finas","description":"Curado, como aperitivo o en bocadillo; su sabor delicado pide cortes finos."},{"title":"En tabla","description":"Junto a queso y pan; marida con vinos blancos y cavas."}],"recommendations":["Favorece la flor blanca con humedad y aireación.","Mantén el condimento sutil, sin pimentón.","No omitas la sal de cura.","Controla temperatura y humedad para evitar mohos indeseados."],"resultNote":"El resultado: un fuet delgado, cubierto de flor blanca, de sabor delicado y textura tierna. La elegancia discreta de la charcutería catalana.","finalQuote":"El fuet es sutileza: poco condimento, calibre fino y un moho noble que trabaja a tu favor. Curar bien también es saber restar.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 200),
  ('salami-de-res', 'Salami de Res', 'chorizos', '{"Colombia","Curado"}', '/recipes/salami-de-res.jpg', 'Colombia · 1 kg', 'embutir-un-chorizo', $receta${"slug":"salami-de-res","name":"Salami de Res","description":"Fermentado y curado en seco — 100% res, con cultivo iniciador, dextrosa y una merma del 35% que lo cambia todo.","image":"/recipes/salami-de-res.jpg","tags":["Colombia","Curado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Estilo europeo, con lo que se consigue en Colombia.","intro":"El salami de res es el curado más exigente de esta casa, y también el que más enseña. No basta con salar y colgar: aquí entra un cultivo iniciador que se come la dextrosa y acidifica la masa, bajando el pH hasta 5,3 o menos. Esa acidez es la primera barrera de seguridad; la segunda es la sal de cura #2, y la tercera es la merma. Se hace 100% res —brisket con su grasa, o magro más grasa de res— y eso cambia el resultado: la grasa de res funde más alto que la de cerdo, es más firme y de sabor más marcado. El salami sale menos untuoso y más profundo que uno italiano de cerdo.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Fermentado y curado en seco"},{"label":"Nivel","value":"Avanzado"},{"label":"Tiempo de preparación","value":"90 min"},{"label":"Fermentación","value":"18–24 °C hasta pH ≤ 5,3 — con T-SPX, 48–72 h"},{"label":"Curado","value":"4–10 semanas, hasta 35% de merma"},{"label":"Tipo de tripa","value":"Colágeno o natural de res, cal. 55–60 mm"}],"details":[{"title":"Origen","description":"Res magra con grasa de res, molida en grano medio y fermentada antes de curar."},{"title":"Textura","description":"Firme y compacta. La grasa de res funde más alto: se nota en grano, no untuosa."},{"title":"Sabor","description":"Profundo y ligeramente ácido. La fermentación aporta el punto láctico que distingue un salami de un embutido salado."}],"quote":"En un salami, la seguridad no la da un solo ingrediente: la dan tres barreras juntas — la acidez, el nitrito y la merma. Saltarse una es saltárselas todas.","ingredientsNote":"Aquí la sal de cura NO es opcional ni negociable: es carne PICADA en curado LARGO. Va la #2, que además de nitrito lleva nitrato y lo va soltando durante semanas. Y el cultivo iniciador no es un lujo de purista: hace DOS trabajos. Acidifica —sin él no baja el pH, y sin acidez falta una de las tres barreras— y además es quien convierte el nitrato de la #2 en nitrito. Sin cultivo, la #2 se queda a medias: por eso estos dos ingredientes van juntos y no se sustituyen el uno al otro.","ingredients":[{"name":"Carne de res magra (bola, chuck o pulpa)","amount":"800 g","pct":"80%"},{"name":"Grasa de res (brisket o cobertura)","amount":"200 g","pct":"20%"},{"name":"Sal","amount":"28 g","pct":"2.8%"},{"name":"Sal de cura #2 (nitrificante de curado largo)","amount":"2.5 g","pct":"0.25%"},{"name":"Dextrosa (alimento del cultivo)","amount":"5 g","pct":"0.5%"},{"name":"Cultivo iniciador de fermentación lenta (T-SPX) — guardado en congelador","amount":"0.25 g","pct":"0.025%"},{"name":"Pimienta negra molida","amount":"3 g","pct":"0.3%"},{"name":"Pimienta negra en grano","amount":"3 g","pct":"0.3%"},{"name":"Ajo en polvo","amount":"2 g","pct":"0.2%"},{"name":"Vino tinto seco","amount":"20 ml","pct":"2%"},{"name":"Agua sin cloro (para hidratar el cultivo)","amount":"20 ml","pct":"2%"}],"proportionNote":"80% magro y 20% grasa. Con menos grasa el salami queda seco y quebradizo; con más, la grasa de res —que funde alto— se siente cerosa al paladar. Si consigues brisket con su grasa, sale la proporción sola.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. La sal sube a 2.8% —más que en un curado de cerdo— porque la res lo pide y porque durante la fermentación la sal también frena lo que no queremos. La sal de cura al 0.25% es el estándar seguro y el techo: nunca más.","steps":[{"n":"01","text":"Saca el cultivo del CONGELADOR —ahí es donde vive, a −17 °C o menos— y hidrátalo en 20 ml de agua SIN cloro, 20–30 min. Dos formas de matarlo antes de empezar: el cloro del agua de la llave, y tenerlo guardado en un cajón de la cocina. Son bacterias vivas: a temperatura ambiente se van muriendo, y un cultivo muerto no avisa."},{"n":"02","text":"Corta magro y grasa en cubos y llévalos al congelador hasta que estén a −2/0 °C, casi cristalizados."},{"n":"03","text":"Muele con disco de 6–8 mm. Si la grasa se empieza a untar, para y vuelve a enfriar."},{"n":"04","text":"Mezcla los secos aparte: sal, sal de cura #2, dextrosa, pimientas y ajo. Pesa en balanza de gramos, nunca con cucharas. ⚠️ El cultivo va aparte y necesita OTRA balanza: son 0,25 g, y una balanza de gramos no los distingue de cero. Hace falta una de 0,01 g — quedarse corto de cultivo es lo que hace que el pH no baje."},{"n":"05","text":"Integra los secos, el vino y el cultivo hidratado. Amasa hasta que la masa quede pegajosa y ligada."},{"n":"06","text":"Embute firme en tripa de 55–60 mm, sin bolsas de aire. Pincha las que veas a contraluz."},{"n":"07","text":"PESA cada pieza y apunta el peso. Sin ese número no hay forma de saber cuándo está listo."},{"n":"08","text":"Fermenta a 18–24 °C y 85–90% de humedad HASTA QUE EL pH BAJE A 5,3 O MENOS. Manda el pH, no el reloj: el T-SPX es un cultivo lento y suele tardar entre 48 y 72 horas, no un día. Si a las 24 h no ha bajado, no ha fallado nada — todavía va. Lo que dice el sobre de TU cultivo manda sobre este número."},{"n":"09","text":"⚠️ NO PASES A CURADO SIN HABER LLEGADO A pH 5,3. Si a las 72 h sigue por encima, el lote se descarta: sin acidez falta una de las tres barreras, y eso no lo arreglan semanas de bodega. Colgar un salami que no acidificó es curar el problema dentro. Con el pH ya abajo, pasa a 12–14 °C y 75–80% de humedad, 4–10 semanas."},{"n":"10","text":"Está listo cuando perdió el 35% de su peso inicial. Se pesa; no se cuentan días."}],"tips":[{"title":"Sin medidor de pH, esta receta no se hace","description":"La acidez es la primera de las tres barreras, y es la única que no se ve, no se huele y no se adivina. No es un accesorio recomendable: es el instrumento que te dice si el lote es seguro. Si no tienes medidor, haz otra receta de esta casa y deja el salami para cuando lo tengas."},{"title":"La grasa de res no es la de cerdo","description":"Funde más alto, es más firme, tira a amarilla y su sabor es fuerte. Es lo que hace distinto a este salami. Si quieres algo más suave y untuoso, cambia la grasa por tocino de cerdo."},{"title":"Se pesa, no se cuenta","description":"35% de merma. En las primeras semanas solo pierde un 10–20%; el resto llega despacio. Un calendario miente, la balanza no."},{"title":"Moho blanco sí, el resto no","description":"El blanco aterciopelado y parejo es noble y se limpia. Verde, negro, gris peludo, viscoso o con mal olor: se descarta la pieza entera."}],"cookMethods":[{"title":"En lonchas finas","description":"Curado, cortado casi transparente. Es como se come: en frío, sin cocinar."},{"title":"En tabla","description":"Con queso curado y pan. La res pide un tinto con cuerpo."}],"recommendations":["No omitas la sal de cura #2: es carne picada en curado largo.","Guarda el cultivo en el congelador, no en un cajón: son bacterias vivas.","Hidrata el cultivo en agua sin cloro, o no fermenta.","Pesa el cultivo en balanza de 0,01 g: 0,25 g no se pesan en una de gramos.","Pesa la pieza al embutir y apunta el número.","Fermenta hasta pH 5,3 o menos, tarde lo que tarde. Si a las 72 h no bajó, se descarta.","Da el salami por terminado por merma (35%), nunca por calendario."],"resultNote":"El resultado: un salami firme, de corte marmoleado, ligeramente ácido y de sabor a res profundo. Menos untuoso que uno de cerdo y con más carácter.","finalQuote":"Un salami no se cura: se fermenta primero y se cura después. Ese orden es toda la diferencia entre un embutido seguro y una apuesta.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 210),
  ('longaniza-filipina', 'Longaniza Filipina (Hamonado)', 'embutidos-frescos', '{"Filipinas","Fresco","Dulce"}', '/recipes/longaniza-filipina.jpg', 'Filipinas · 1 kg', 'embutir-un-chorizo', $receta${"slug":"longaniza-filipina","name":"Longaniza Filipina (Hamonado)","description":"Dulce y ajada — la longganisa filipina estilo hamonado, con azúcar, ajo y un toque de soya.","image":"/recipes/longaniza-filipina.jpg","tags":["Filipinas","Fresco","Dulce"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Dulce, brillante y muy ajada.","intro":"La longganisa filipina, en su estilo hamonado, es dulce y pegajosa: el azúcar caramelizado al freírla es su sello. Muy ajada, con un toque de soya y vinagre de caña, se sirve al desayuno con arroz y huevo (el clásico “longsilog”). Es un embutido fresco, de color intenso, que equilibra dulce, salado y ácido en cada bocado.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Embutido fresco"},{"label":"Nivel","value":"Fácil–Intermedio"},{"label":"Tiempo de preparación","value":"45 min"},{"label":"Tiempo de reposo","value":"24–48 h"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 28–32 mm"}],"details":[{"title":"Origen","description":"Cerdo con buena grasa; el reposo deja que el dulce y el ajo penetren."},{"title":"Textura","description":"Jugosa y algo pegajosa por el azúcar, que carameliza al cocinar."},{"title":"Sabor","description":"Dulce al frente, mucho ajo, con fondo salado de soya y acidez de vinagre."}],"quote":"La longganisa hamonado juega con el contraste: dulce que caramela, ajo que abunda y un ácido que lo despierta todo.","ingredientsNote":"El azúcar es un ingrediente protagonista, no un detalle. Deja reposar 24–48 h para que el ajo y el dulce se integren.","ingredients":[{"name":"Carne de cerdo (paleta)","amount":"750 g","pct":"75%"},{"name":"Grasa de cerdo","amount":"250 g","pct":"25%"},{"name":"Azúcar morena","amount":"80 g","pct":"8%"},{"name":"Ajo fresco triturado","amount":"30 g","pct":"3%"},{"name":"Sal","amount":"18 g","pct":"1.8%"},{"name":"Salsa de soya","amount":"30 ml","pct":"3%"},{"name":"Vinagre de caña","amount":"30 ml","pct":"3%"},{"name":"Pimienta negra","amount":"3 g","pct":"0.3%"},{"name":"Pimentón dulce","amount":"5 g","pct":"0.5%"}],"proportionNote":"75% carne y 25% grasa da jugosidad; el azúcar al 8% es lo que define el estilo hamonado (dulce). Baja el azúcar si prefieres el estilo “de recado”, más ajado y salado.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. Al ser fresca, se cocina y se consume pronto, sin sal de cura.","steps":[{"n":"01","text":"Mezcla los líquidos y el azúcar hasta disolver: soya, vinagre y azúcar."},{"n":"02","text":"Corta la carne y la grasa en cubos, muy fríos (0–4 °C)."},{"n":"03","text":"Muele con disco de 8 mm."},{"n":"04","text":"Integra el ajo, la sal, las especias y la mezcla dulce; amasa hasta ligar."},{"n":"05","text":"Deja reposar en frío 24–48 h para que el sabor penetre."},{"n":"06","text":"Embute en tripa fina (28–32 mm) o forma sin tripa (skinless)."},{"n":"07","text":"Refrigera; consúmela fresca en pocos días o congélala."}],"tips":[{"title":"El azúcar carameliza","description":"Cocina a fuego medio-bajo con un poco de agua; al evaporarse, el azúcar dora la longganisa."},{"title":"Mucho ajo","description":"El ajo es protagonista, no acompañante. No lo escatimes."},{"title":"Reposo largo","description":"Las 24–48 h en frío integran el dulce y el ajo; marcan la diferencia."}],"cookMethods":[{"title":"Sartén (longsilog)","description":"A fuego medio-bajo con agua; al evaporarse, se dora en su propia grasa y azúcar."},{"title":"Con arroz y huevo","description":"El desayuno filipino clásico: longganisa, arroz al ajo y huevo frito."}],"recommendations":["Cocina a fuego medio-bajo para caramelizar sin quemar el azúcar.","No escatimes el ajo.","Reposa la masa 24–48 h antes de embutir.","Consúmela fresca o congélala."],"resultNote":"El resultado: una longganisa brillante y dorada, dulce y muy ajada, que caramela al freírse. El desayuno filipino en formato embutido.","finalQuote":"La longganisa filipina rompe el prejuicio de que el chorizo es salado: aquí el azúcar es técnica, no capricho.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 220),
  ('longaniza-dominicana', 'Longaniza Dominicana', 'embutidos-frescos', '{"R. Dominicana","Fresco","Picante"}', '/recipes/longaniza-dominicana.jpg', 'R. Dominicana · 1 kg', 'embutir-un-chorizo', $receta${"slug":"longaniza-dominicana","name":"Longaniza Dominicana","description":"Ajo, orégano y naranja agria — el embutido fresco dominicano, ácido y muy aromático.","image":"/recipes/longaniza-dominicana.jpg","tags":["R. Dominicana","Fresco","Picante"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Ácida, ajada y con mucho orégano.","intro":"La longaniza dominicana es intensa: mucho ajo, orégano abundante y el toque ácido de la naranja agria (agrio) que la define. Es un embutido fresco, jugoso, que se fríe hasta dorar y se sirve con tostones, yuca o en el desayuno. Su perfil herbal y cítrico la separa de sus primos españoles; aquí el orégano y el agrio mandan.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Embutido fresco"},{"label":"Nivel","value":"Fácil–Intermedio"},{"label":"Tiempo de preparación","value":"45 min"},{"label":"Tiempo de reposo","value":"24 h"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 30–34 mm"}],"details":[{"title":"Origen","description":"Cerdo con grasa; el agrio y el ajo maceran la carne antes de embutir."},{"title":"Textura","description":"Jugosa; el ácido ayuda a integrar el sabor y a conservarla fresca."},{"title":"Sabor","description":"Ajo y orégano intensos, con la acidez de la naranja agria de fondo."}],"quote":"El agrio de naranja es a la longaniza dominicana lo que el pimentón al chorizo español: sin él, no es ella.","ingredientsNote":"El orégano y el ajo van en cantidad generosa. Deja macerar 24 h para que el agrio penetre la carne.","ingredients":[{"name":"Carne de cerdo (paleta)","amount":"750 g","pct":"75%"},{"name":"Grasa de cerdo","amount":"250 g","pct":"25%"},{"name":"Ajo fresco triturado","amount":"30 g","pct":"3%"},{"name":"Jugo de naranja agria (agrio)","amount":"50 ml","pct":"5%"},{"name":"Orégano seco","amount":"5 g","pct":"0.5%"},{"name":"Sal","amount":"20 g","pct":"2%"},{"name":"Pimentón dulce o achiote","amount":"5 g","pct":"0.5%"},{"name":"Pimienta negra","amount":"3 g","pct":"0.3%"},{"name":"Ají picante (opcional)","amount":"3 g","pct":"0.3%"}],"proportionNote":"75% carne y 25% grasa da jugosidad para freír. El agrio al 5% aporta la acidez característica; el orégano, en cantidad generosa, define el aroma.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. Al ser fresca, se cocina y se consume pronto, sin sal de cura.","steps":[{"n":"01","text":"Mezcla el ajo, el orégano, el agrio, la sal y las especias."},{"n":"02","text":"Corta la carne y la grasa en cubos, muy fríos (0–4 °C)."},{"n":"03","text":"Muele con disco de 8 mm."},{"n":"04","text":"Integra el adobo con la carne y amasa hasta ligar."},{"n":"05","text":"Deja macerar en frío 24 h."},{"n":"06","text":"Embute en tripa natural (30–34 mm) y forma la longaniza."},{"n":"07","text":"Refrigera; consúmela fresca en pocos días o congélala."}],"tips":[{"title":"Naranja agria","description":"Si no consigues agrio, mezcla jugo de naranja dulce con lima para imitar la acidez."},{"title":"Orégano generoso","description":"El orégano dominicano es protagonista; úsalo en cantidad, sin miedo."},{"title":"Maceración","description":"Las 24 h con el agrio integran el sabor y realzan el aroma."}],"cookMethods":[{"title":"Frita","description":"A fuego medio con un poco de agua; al evaporarse, se dora en su grasa."},{"title":"Con tostones","description":"Clásica con tostones, yuca o casabe; también al desayuno."}],"recommendations":["Usa naranja agria o imítala con naranja y lima.","Sé generoso con el orégano y el ajo.","Macera 24 h antes de embutir.","Consúmela fresca o congélala."],"resultNote":"El resultado: una longaniza jugosa, ácida y muy aromática, que dora en su grasa. El orégano y el agrio, inconfundibles en cada bocado.","finalQuote":"La longaniza dominicana enseña que el ácido también condimenta: el agrio de naranja transforma la misma carne en algo único.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 230),
  ('loukaniko', 'Loukániko Griego', 'embutidos-frescos', '{"Grecia","Fresco","Ahumado"}', '/recipes/loukaniko.jpg', 'Grecia · 1 kg', 'embutir-un-chorizo', $receta${"slug":"loukaniko","name":"Loukániko Griego","description":"Cerdo con naranja e hinojo — el embutido griego perfumado con cítrico y semillas, macerado en vino.","image":"/recipes/loukaniko.jpg","tags":["Grecia","Fresco","Ahumado"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Naranja, hinojo y vino: el aroma del Egeo.","intro":"El loukániko es el embutido griego más reconocible: cerdo perfumado con ralladura de naranja y semillas de hinojo, macerado en vino tinto. Ese perfume cítrico y anisado lo hace inconfundible. Puede consumirse fresco a la parrilla o secarse y ahumarse ligeramente. Un chorizo mediterráneo, herbal y aromático, muy presente en la mesa griega.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Fresco / semiseco"},{"label":"Nivel","value":"Intermedio"},{"label":"Tiempo de preparación","value":"45 min"},{"label":"Maceración","value":"12–24 h"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 32–36 mm"}],"details":[{"title":"Origen","description":"Cerdo con grasa, macerado en vino para integrar el cítrico y el hinojo."},{"title":"Textura","description":"Jugosa en fresco; firme y algo seca si se orea unos días."},{"title":"Sabor","description":"Naranja e hinojo al frente, con ajo, orégano y el fondo del vino tinto."}],"quote":"La ralladura de naranja y el hinojo son la firma del loukániko: un chorizo que huele a Mediterráneo antes de tocarlo.","ingredientsNote":"Ralla solo la parte naranja de la cáscara (sin lo blanco, que amarga). Macera en vino para que el perfume penetre.","ingredients":[{"name":"Carne de cerdo (paleta)","amount":"800 g","pct":"80%"},{"name":"Grasa de cerdo","amount":"200 g","pct":"20%"},{"name":"Ralladura de naranja","amount":"15 g","pct":"1.5%"},{"name":"Semillas de hinojo","amount":"8 g","pct":"0.8%"},{"name":"Ajo fresco triturado","amount":"10 g","pct":"1%"},{"name":"Sal","amount":"20 g","pct":"2%"},{"name":"Orégano seco","amount":"3 g","pct":"0.3%"},{"name":"Pimienta negra","amount":"3 g","pct":"0.3%"},{"name":"Vino tinto","amount":"50 ml","pct":"5%"}],"proportionNote":"80% carne y 20% grasa da una base jugosa que sostiene el perfume cítrico. Ajusta naranja e hinojo según cuánto aroma busques.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. Si lo consumes fresco, no necesita sal de cura; si lo secas varios días, añádela.","steps":[{"n":"01","text":"Machaca ligeramente las semillas de hinojo para liberar su aroma."},{"n":"02","text":"Corta la carne y la grasa en cubos, muy fríos (0–4 °C)."},{"n":"03","text":"Muele con disco de 8 mm."},{"n":"04","text":"Integra ralladura, hinojo, ajo, orégano, sal, pimienta y vino; amasa hasta ligar."},{"n":"05","text":"Macera en frío 12–24 h para que el cítrico penetre."},{"n":"06","text":"Embute en tripa natural (32–36 mm) y forma aros."},{"n":"07","text":"Consúmelo fresco a la parrilla, u orea 2–3 días para un perfil más seco."}],"tips":[{"title":"Solo la parte naranja","description":"Ralla la cáscara sin la parte blanca, que amarga. El aceite de la piel es el que perfuma."},{"title":"Hinojo machacado","description":"Machaca las semillas ligeramente antes de mezclar: libera mucho más aroma que enteras."},{"title":"Fresco o seco","description":"Si lo oreas para secarlo, añade sal de cura; si lo comes fresco a la brasa, no hace falta."}],"cookMethods":[{"title":"Parrilla","description":"A la brasa hasta dorar; el calor realza el cítrico y el hinojo."},{"title":"En meze","description":"En rodajas dentro de una tabla griega, con queso feta y pan de pita."}],"recommendations":["Ralla solo la parte naranja de la cáscara.","Machaca el hinojo antes de mezclar.","Macera 12–24 h en vino.","Añade sal de cura solo si vas a secarlo varios días."],"resultNote":"El resultado: un chorizo perfumado, jugoso y herbal, con la naranja y el hinojo al frente. El Mediterráneo en formato embutido.","finalQuote":"El loukániko enseña que un cítrico y una semilla bien elegidos transforman la carne: el aroma es tan ingrediente como la sal.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 240),
  ('merguez', 'Merguez', 'embutidos-frescos', '{"Magreb","Fresco","Picante"}', '/recipes/merguez.jpg', 'Magreb · 1 kg', 'embutir-un-chorizo', $receta${"slug":"merguez","name":"Merguez","description":"El fino y picante del Magreb — cordero, harissa y comino, rojo intenso y a la brasa.","image":"/recipes/merguez.jpg","tags":["Magreb","Fresco","Picante"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Cordero especiado, delgado y picante.","intro":"El merguez es el embutido fresco del norte de África: de cordero (a veces con res), delgado, rojo y picante. Su color y su fuego vienen de la harissa y el pimentón, sobre una base de comino, cilantro y ajo. Se asa a la brasa hasta chisporrotear y se sirve con pan, cuscús o en bocadillo. Un chorizo especiado, intenso y de calibre fino.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Embutido fresco"},{"label":"Nivel","value":"Intermedio"},{"label":"Tiempo de preparación","value":"45 min"},{"label":"Tiempo de reposo","value":"12–24 h"},{"label":"Tipo de tripa","value":"Natural de cordero, cal. 20–24 mm"}],"details":[{"title":"Origen","description":"Cordero, a veces con res, con grasa de cordero para su sabor característico."},{"title":"Textura","description":"Jugosa y fina; el calibre delgado la cocina rápido a la brasa."},{"title":"Sabor","description":"Picante de harissa y pimentón, con comino y cilantro muy presentes."}],"quote":"El merguez es el chorizo del cordero: cambia la carne, cambia el mundo de especias, pero la técnica es la misma.","ingredientsNote":"La harissa aporta color y picor; ajústala a tu gusto. El comino y el cilantro molido son la base aromática.","ingredients":[{"name":"Carne de cordero","amount":"700 g","pct":"70%"},{"name":"Grasa de cordero o res","amount":"300 g","pct":"30%"},{"name":"Harissa","amount":"40 g","pct":"4%"},{"name":"Pimentón picante","amount":"20 g","pct":"2%"},{"name":"Ajo fresco triturado","amount":"15 g","pct":"1.5%"},{"name":"Comino molido","amount":"10 g","pct":"1%"},{"name":"Cilantro molido","amount":"8 g","pct":"0.8%"},{"name":"Sal","amount":"20 g","pct":"2%"},{"name":"Pimienta negra","amount":"3 g","pct":"0.3%"},{"name":"Agua helada","amount":"20 ml","pct":"2%"}],"proportionNote":"70% carne y 30% grasa de cordero da jugosidad y el sabor característico. La harissa y el pimentón definen color y picor; ajústalos según tu tolerancia.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. Al ser fresco, se cocina y se consume pronto, sin sal de cura.","steps":[{"n":"01","text":"Mezcla los secos: pimentón, comino, cilantro, sal y pimienta."},{"n":"02","text":"Corta la carne y la grasa en cubos, muy fríos (0–4 °C)."},{"n":"03","text":"Muele con disco de 6–8 mm."},{"n":"04","text":"Integra la harissa, el ajo, los secos y el agua; amasa hasta una masa roja y homogénea."},{"n":"05","text":"Deja reposar en frío 12–24 h para que las especias se integren."},{"n":"06","text":"Embute en tripa fina de cordero (20–24 mm)."},{"n":"07","text":"Refrigera; consúmelo fresco a la brasa en pocos días."}],"tips":[{"title":"Grasa de cordero","description":"Es la que da el sabor auténtico. Si te resulta fuerte, mézclala con grasa de res."},{"title":"Harissa al gusto","description":"Regula el picor con la cantidad de harissa; también aporta color y profundidad."},{"title":"Calibre fino","description":"La tripa de cordero (20–24 mm) es esencial para su formato delgado y cocción rápida."}],"cookMethods":[{"title":"Brasa","description":"A fuego vivo, girando, hasta chisporrotear; su calibre fino se hace en minutos."},{"title":"Con cuscús","description":"Clásico junto a cuscús y verduras, o en bocadillo con harissa."}],"recommendations":["Usa grasa de cordero para el sabor auténtico.","Ajusta el picor con la harissa.","Emplea tripa fina de cordero.","Consúmelo fresco a la brasa."],"resultNote":"El resultado: un merguez delgado, rojo y picante, jugoso al morder y con el aroma del comino y el cilantro. El Magreb en la parrilla.","finalQuote":"El merguez recuerda que el chorizo no es solo de cerdo: con cordero y especias del Magreb, la técnica charcutera viaja lejos.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 250),
  ('sujuk', 'Sujuk (Sucuk)', 'chorizos', '{"Turquía","Curado","Picante"}', '/recipes/sujuk.jpg', 'Turquía · 1 kg', 'embutir-un-chorizo', $receta${"slug":"sujuk","name":"Sujuk (Sucuk)","description":"El curado seco de res — comino, ajo y pimentón, prensado plano y madurado. Especiado e intenso.","image":"/recipes/sujuk.jpg","tags":["Turquía","Curado","Picante"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Res especiada, prensada y curada.","intro":"El sujuk (o sucuk) es el embutido curado seco de Turquía y Oriente Medio: de res, muy especiado, con comino, ajo y pimentón, prensado en forma plana durante el curado. Su perfil es intenso y aromático, con un punto picante. Se cura al aire hasta secar, y se corta en rodajas finas para freír al desayuno o comer en tabla. Un chorizo de res, denso y contundente.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Curado en seco"},{"label":"Nivel","value":"Avanzado"},{"label":"Tiempo de preparación","value":"50 min"},{"label":"Curado","value":"3–5 semanas"},{"label":"Tipo de tripa","value":"Natural de res, cal. 38–42 mm"}],"details":[{"title":"Origen","description":"Res con algo de grasa; el prensado plano es parte de su identidad."},{"title":"Textura","description":"Densa y firme; se aplana con el curado y se corta en rodajas finas."},{"title":"Sabor","description":"Comino y ajo dominantes, con pimentón, sumac y un fondo picante."}],"quote":"El sujuk se cura prensado y plano: la forma no es capricho, es parte de cómo seca y concentra su sabor.","ingredientsNote":"La mezcla de especias es abundante y define el sujuk. La sal de cura es obligatoria para un curado seguro de res.","ingredients":[{"name":"Carne de res (magra)","amount":"750 g","pct":"75%"},{"name":"Grasa de res o cordero","amount":"250 g","pct":"25%"},{"name":"Ajo fresco triturado","amount":"20 g","pct":"2%"},{"name":"Comino molido","amount":"15 g","pct":"1.5%"},{"name":"Pimentón picante","amount":"15 g","pct":"1.5%"},{"name":"Sal","amount":"26 g","pct":"2.6%"},{"name":"Sumac","amount":"5 g","pct":"0.5%"},{"name":"Sal de cura (nitrificante, #2)","amount":"2.5 g","pct":"0.25%"},{"name":"Pimienta negra","amount":"5 g","pct":"0.5%"},{"name":"Fenogreco molido (opcional)","amount":"3 g","pct":"0.3%"}],"proportionNote":"75% carne y 25% grasa da un sujuk firme pero no seco. Las especias van en cantidad generosa: son la esencia de este embutido.","charcuteroNote":"El porcentaje junto a cada ingrediente es su peso sobre el total de carne y grasa. La sal de cura al 0.25% es imprescindible en el curado de res.","steps":[{"n":"01","text":"Mezcla todas las especias con la sal y la sal de cura."},{"n":"02","text":"Corta la carne y la grasa en cubos, muy fríos (0–2 °C)."},{"n":"03","text":"Muele con disco de 6 mm."},{"n":"04","text":"Integra las especias y el ajo; amasa bien hasta una masa densa."},{"n":"05","text":"Macera en frío 24 h para que las especias tomen."},{"n":"06","text":"Embute firme en tripa de res (38–42 mm) y ata en aros; prensa ligeramente."},{"n":"07","text":"Cura a 12–15 °C y 75–80% de humedad, 3–5 semanas, prensando para aplanar."}],"tips":[{"title":"Especias generosas","description":"El sujuk vive de sus especias. Comino, ajo y pimentón van en cantidad, sin timidez."},{"title":"Prensado plano","description":"Prensa ligeramente durante el curado para lograr su forma aplanada característica."},{"title":"Curado controlado","description":"12–15 °C y 75–80% de humedad; la sal de cura es obligatoria en el curado de res."}],"cookMethods":[{"title":"Frito","description":"En rodajas a la sartén, hasta dorar; clásico con huevos al desayuno (sucuklu yumurta)."},{"title":"En tabla","description":"Curado, en rodajas finas, como parte de un meze."}],"recommendations":["Sé generoso con las especias.","Prensa ligeramente durante el curado para aplanarlo.","No omitas la sal de cura en el curado de res.","Controla temperatura y humedad."],"resultNote":"El resultado: un sujuk plano, denso y muy especiado, que al freírse suelta su grasa aromática. Res curada con el recetario de Oriente Medio.","finalQuote":"El sujuk demuestra que el chorizo es una idea universal: cambia la carne por res, las especias por comino y sumac, y el oficio sigue siendo el mismo.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 260),
  ('kielbasa-polaca', 'Kielbasa Polaca de Cerdo y Res', 'chorizos', '{"Polonia","Ahumado","Curado"}', '/recipes/kielbasa-polaca.jpg', 'Polonia', 'embutir-un-chorizo', $receta${"slug":"kielbasa-polaca","name":"Kielbasa Polaca de Cerdo y Res","description":"La kielbasa auténtica — cerdo y res, ajo, pimienta y mejorana. Sin paprika, sin mostaza, sin mezclas de especias innecesarias: curada, ahumada y cocida como en Polonia.","image":"/recipes/kielbasa-polaca.jpg","tags":["Polonia","Ahumado","Curado"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Cerdo y res con ajo, pimienta y mejorana: el perfil clásico polaco.","intro":"La kielbasa polaca tradicional no lleva paprika, ni mostaza, ni coriandro, ni chile. Lleva cuatro cosas: sal, sal de cura, ajo y pimienta — y la mejorana, que es la firma aromática que distingue a la polaca de cualquier otra salchicha ahumada de Europa. Todo lo demás sobra. Esta fórmula vuelve a esa base: 70% cerdo y 30% res, un curado en frío de dos o tres días antes de moler, un amasado vigoroso hasta que la masa quede pegajosa, y un ahumado progresivo hasta el dorado característico. El resultado es una salchicha en herradura, firme y jugosa, que sabe a carne, ajo y humo — exactamente lo que debe saber.","stats":[{"label":"Rendimiento base","value":"1 kg de masa"},{"label":"Tipo","value":"Curada, ahumada y cocida"},{"label":"Nivel","value":"Intermedio"},{"label":"Curado","value":"2–3 días en frío (0–4 °C)"},{"label":"Molienda","value":"Media, disco de 8 mm"},{"label":"Ahumado","value":"Progresivo, hasta dorado"},{"label":"Temperatura interna","value":"68–70 °C (71 °C con margen)"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 30–32 mm"}],"details":[{"title":"Origen","description":"La base polaca de siempre: 70% cerdo por la grasa y la jugosidad, 30% res por el cuerpo y el color más profundo."},{"title":"Textura","description":"Firme y bien ligada, con grano visible de la molienda de 8 mm — no es una emulsión fina, se le ve la carne."},{"title":"Sabor","description":"Ajo y pimienta al frente, mejorana de fondo y humo encima. Un perfil limpio, sin especias que compitan entre sí."},{"title":"La mejorana es la firma","description":"Es lo que hace que una kielbasa sepa a polaca y no a alemana o a húngara. Va poca —0,5 a 1 g por kilo— pero no es opcional."}],"quote":"La verdadera kielbasa polaca: cerdo y res, ajo, pimienta y mejorana. Sin mezclas de especias innecesarias.","ingredientsNote":"La sal de cura Prague Powder #1 es obligatoria: esta salchicha pasa horas en el ahumador a temperaturas bajas antes de cocerse, y esa franja es justo donde el nitrito hace falta. A 2,5 g por kilo aporta el nivel estándar de nitrito de entrada de un embutido cocido, además del color rosado y el sabor curado. No la sustituyas ni la reduzcas.","ingredients":[{"name":"Carne de cerdo (paleta, con su grasa)","amount":"700 g","pct":"70%"},{"name":"Carne de res (magra)","amount":"300 g","pct":"30%"},{"name":"Agua o hielo triturado","amount":"80–100 ml","pct":"8–10%"},{"name":"Sal","amount":"18 g","pct":"1.8%"},{"name":"Sal de cura #1 (Prague Powder #1)","amount":"2.5 g","pct":"0.25%"},{"name":"Ajo fresco machacado","amount":"2.5–3 g","pct":"0.25–0.3%"},{"name":"Pimienta negra molida","amount":"2 g","pct":"0.2%"},{"name":"Mejorana seca","amount":"0.5–1 g","pct":"0.05–0.1%"}],"proportionNote":"70/30 cerdo y res: el cerdo aporta la grasa —sin ella la res deja la masa seca— y la res aporta cuerpo y un color más intenso. El agua o hielo al 8–10% no es relleno: es lo que permite que el amasado extraiga la proteína y la masa ligue de verdad.","charcuteroNote":"El porcentaje es el peso sobre el total de carne. Valores por kilo: cerdo 700 g, res 300 g, sal 18 g, sal de cura #1 2,5 g, ajo fresco 2,5–3 g, pimienta negra 2 g, mejorana 0,5–1 g, agua o hielo 80–100 ml. Los 2,5 g de Prague Powder #1 por kilo equivalen a 156 ppm de nitrito de entrada, el nivel estándar para un embutido cocido.","steps":[{"n":"01","text":"Mantén las carnes muy frías, casi congeladas, y córtalas en cubos."},{"n":"02","text":"Mezcla la carne con la sal y la sal de cura, y deja reposar 2 a 3 días en refrigeración a 0–4 °C."},{"n":"03","text":"Muele el cerdo y la res con molienda media, disco de 8 mm."},{"n":"04","text":"Agrega el ajo, la pimienta, la mejorana y el agua o hielo triturado."},{"n":"05","text":"Amasa vigorosamente hasta que la masa quede pegajosa y bien ligada — es el paso que decide la textura final."},{"n":"06","text":"Embute en tripa natural de cerdo de 30–32 mm, sin dejar bolsas de aire."},{"n":"07","text":"Forma las herraduras o los eslabones y deja que la superficie se seque al tacto antes del ahumado."},{"n":"08","text":"Ahúma progresivamente, subiendo la temperatura poco a poco, hasta obtener el color dorado característico."},{"n":"09","text":"Cocina hasta que el centro alcance 68–70 °C; para mayor margen doméstico, llévala a 71 °C."},{"n":"10","text":"Enfría rápidamente con agua fría, seca la superficie y refrigera."}],"tips":[{"title":"La superficie seca antes del humo","description":"Si la tripa está húmeda, el humo se deposita manchado y el color sale disparejo. Deja que la superficie se seque al tacto — es el paso que más se salta la gente."},{"title":"Ajo fresco, no en polvo","description":"En la kielbasa polaca el ajo se machaca fresco. El polvo da un sabor plano y no es lo que buscas aquí."},{"title":"Sube el humo por escalones","description":"Ahumar progresivamente —no de golpe a temperatura alta— evita que la grasa se funda antes de tiempo y que la salchicha quede arrugada y seca."},{"title":"Menos es más","description":"La tentación de añadir paprika o coriandro es real. No lo hagas: la kielbasa polaca se define tanto por lo que lleva como por lo que no lleva."}],"cookMethods":[{"title":"Ahumada y cocida","description":"El método propio de la receta: humo progresivo hasta el dorado y cocción hasta 68–70 °C internos. Queda lista para comer."},{"title":"A la parrilla","description":"Ya cocida, solo dorar unos minutos para reforzar el tostado antes de servir."},{"title":"En bigos o con chucrut","description":"El uso clásico polaco: en guiso con col fermentada, donde la mejorana y el ajo se lucen."}],"recommendations":["No omitas la sal de cura #1: el ahumado a baja temperatura la hace obligatoria.","Respeta el curado de 2 a 3 días antes de moler — ahí se asienta el color y el sabor.","Mantén la carne y la masa por debajo de 4 °C durante todo el proceso.","Amasa hasta que la masa se pegue a la mano: si no liga, la salchicha queda desmoronada.","Cocina hasta 68–70 °C internos, verificados con termómetro; 71 °C si quieres margen.","Enfría rápido con agua fría y refrigera de inmediato."],"resultNote":"El resultado: una herradura de color dorado ahumado, firme al tacto y rosada al corte, con el grano de la molienda de 8 mm bien visible. Sabe a cerdo, res, ajo y humo, con la mejorana asomando al final — la kielbasa que se reconoce sin necesidad de etiqueta.","finalQuote":"Cuatro condimentos y dos carnes. La kielbasa polaca se define tanto por lo que lleva como por lo que decidió no llevar.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 270),
  ('kielbasa-de-pollo', 'Kielbasa de Pollo Ahumada', 'chorizos', '{"Alemania","Ahumado","Pollo"}', '/recipes/kielbasa-de-pollo.jpg', 'Alemania · 2 kg', 'embutir-un-chorizo', $receta${"slug":"kielbasa-de-pollo","name":"Kielbasa de Pollo Ahumada","description":"Salchicha ahumada de pollo estilo alemán — pechuga y cerdo curados, ahumado lento en barril, jugosa y delicada.","image":"/recipes/kielbasa-de-pollo.jpg","tags":["Alemania","Ahumado","Pollo"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Pollo curado y ahumado, estilo salchicha blanca.","intro":"La kielbasa de pollo es una salchicha ahumada, ligera y jugosa, inspirada en la salchicha blanca alemana. La pechuga de pollo, con un apoyo de cerdo para la jugosidad, se cura tres días antes de especiarse y ahumarse lento en barril. El resultado es un embutido de sabor delicado, textura tersa y un ahumado suave que no tapa la carne. Una alternativa magra a los embutidos de cerdo, sin renunciar al oficio.","stats":[{"label":"Rendimiento base","value":"2 kg"},{"label":"Tipo","value":"Ahumado cocido"},{"label":"Nivel","value":"Avanzado"},{"label":"Curado","value":"3 días"},{"label":"Ahumado","value":"Lento, en barril"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 32–36 mm"}],"details":[{"title":"Origen","description":"Pechuga de pollo con un 15% de cerdo, que aporta la grasa y la jugosidad."},{"title":"Textura","description":"Tersa y jugosa; la leche en polvo y el curado dan una emulsión fina."},{"title":"Sabor","description":"Delicado — pimienta blanca, coriandro y nuez moscada — con ahumado suave."}],"quote":"El pollo pide respeto: poca grasa y mucho cuidado. El curado y el frío hacen que quede jugoso, no seco.","ingredientsNote":"Este embutido se cura 3 días antes de especiar. La sal de cura Prague Powder #1 es obligatoria para un ahumado cocido a baja temperatura.","ingredients":[{"name":"Pechuga de pollo","amount":"1700 g","pct":"85%"},{"name":"Carne de cerdo","amount":"300 g","pct":"15%"},{"name":"Sal","amount":"33 g","pct":"1.65%"},{"name":"Sal de cura #1 (Prague Powder #1)","amount":"5 g","pct":"0.25%"},{"name":"Leche en polvo","amount":"40 g","pct":"2%"},{"name":"Ajo en polvo","amount":"3.6 g","pct":"0.18%"},{"name":"Pimienta blanca","amount":"3.6 g","pct":"0.18%"},{"name":"Coriandro molido","amount":"2.4 g","pct":"0.12%"},{"name":"Azúcar","amount":"3.6 g","pct":"0.18%"},{"name":"Nuez moscada","amount":"0.6 g","pct":"0.03%"}],"proportionNote":"85% pechuga de pollo y 15% cerdo: el cerdo aporta la grasa que al pollo le falta, clave para que no quede seco. La leche en polvo ayuda a retener humedad y ligar la emulsión.","charcuteroNote":"El porcentaje es el peso sobre el total de carne. Valores por kilo: sal 16,5 g, sal de cura 2,5 g, ajo 1,8 g, pimienta blanca 1,8 g, coriandro 1,2 g, nuez moscada 0,3 g, leche en polvo 20 g, azúcar 1,8 g.","steps":[{"n":"01","text":"Cura la pechuga y el cerdo 3 días en frío (0–4 °C) con la sal y la sal de cura #1."},{"n":"02","text":"Procesa la carne curada: muele con disco de 4–6 mm, bien fría."},{"n":"03","text":"Agrega las especias, la leche en polvo y el azúcar; amasa hasta una emulsión fina y pegajosa."},{"n":"04","text":"Mantén la masa entre 0 y 4 °C durante todo el amasado."},{"n":"05","text":"Embute en tripa natural de cerdo (32–36 mm) y forma las clásicas herraduras."},{"n":"06","text":"Deja reposar toda la noche en frío para asentar el sabor."},{"n":"07","text":"Ahúma lento en barril a baja temperatura hasta cocer (73–75 °C internos)."}],"tips":[{"title":"Todo muy frío","description":"El pollo es magro; si la masa se calienta, pierde emulsión y queda seca. Trabaja casi congelada."},{"title":"Sal de cura #1","description":"Obligatoria en ahumados cocidos a baja temperatura: previene el riesgo de botulismo."},{"title":"Ahumado suave","description":"El pollo no necesita mucho humo; un ahumado lento y ligero realza sin tapar la carne."}],"cookMethods":[{"title":"Ahumado en barril","description":"A baja temperatura hasta alcanzar 73–75 °C en el centro; queda cocida y lista para comer."},{"title":"A la parrilla","description":"Ya ahumada, solo dorar unos minutos para reforzar el sabor antes de servir."}],"recommendations":["Cura 3 días antes de especiar.","No omitas la sal de cura #1 en un ahumado cocido.","Mantén la carne fría para conservar la emulsión.","Cocina hasta 73–75 °C internos para un consumo seguro."],"resultNote":"El resultado: una kielbasa tersa, jugosa y de ahumado delicado, más ligera que las de cerdo. Al corte, una emulsión fina y pareja — la señal de un buen curado y un trabajo en frío.","finalQuote":"La kielbasa de pollo demuestra que la charcutería no es solo de cerdo: con curado, frío y técnica, hasta la pechuga magra queda jugosa.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 280),
  ('kielbasa-de-mozzarella-y-jalapeno', 'Kielbasa de Mozzarella y Jalapeño', 'chorizos', '{"Polonia","Ahumado","Picante","Queso"}', '/recipes/kielbasa-de-mozzarella-y-jalapeno.jpg', 'Polonia', 'embutir-un-chorizo', $receta${"slug":"kielbasa-de-mozzarella-y-jalapeno","name":"Kielbasa de Mozzarella y Jalapeño","description":"Kielbasa ahumada de textura artesanal — 70% picada a cuchillo — con cubos de mozzarella y jalapeño encurtido, trabajada en dos días.","image":"/recipes/kielbasa-de-mozzarella-y-jalapeno.jpg","tags":["Polonia","Ahumado","Picante","Queso"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Picada a cuchillo, con queso y jalapeño, ahumada en dos días.","intro":"Una kielbasa de estructura, no de emulsión: el 70% de la carne va picada a cuchillo y solo el 30% molida fina, que es la que liga y sostiene. Se trabaja en dos días — el primero solo carne, condimentos y agua, amasando hasta la liga y ocho horas de reposo en frío; el segundo se incorporan la mozzarella en cubos y el jalapeño encurtido bien escurrido, con la mano suave, para que lleguen enteros al corte. Después, secado de la tripa y ahumado progresivo. El queso funde dentro y el jalapeño corta la grasa; al tajarla se ven los cubos blancos y el verde repartidos en una masa de grano grueso.","stats":[{"label":"Rendimiento base","value":"2 kg de carne"},{"label":"Tipo","value":"Ahumada y cocida"},{"label":"Nivel","value":"Intermedio"},{"label":"Proceso","value":"2 días (8 h de reposo en frío)"},{"label":"Molienda","value":"70% a cuchillo, 30% fina"},{"label":"Ahumado","value":"Progresivo, sin golpes de calor"},{"label":"Temperatura interna","value":"72 °C"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 32–38 mm"}],"details":[{"title":"Origen","description":"Carne de cerdo en dos texturas: 1400 g picada a cuchillo y 600 g molida fina."},{"title":"Textura","description":"De grano grueso y mordida marcada; el 30% molido fino es el que da la liga que la mantiene unida."},{"title":"Sabor","description":"Ajo, pimienta y coriandro de base, con el picante del jalapeño encurtido y la mozzarella fundida dentro."}],"quote":"El queso y el jalapeño no son adorno: son agua y grasa dentro de una tripa cerrada. Por eso aquí manda la presión, no la prisa.","ingredientsNote":"La mozzarella y el jalapeño entran el segundo día, nunca en el amasado del primero: si se amasan con la masa se deshacen y sueltan su agua dentro. El jalapeño hay que escurrirlo y secarlo de verdad — el líquido del encurtido es lo que después revienta la tripa.","ingredients":[{"name":"Carne de cerdo picada a cuchillo","amount":"1400 g","pct":"70%"},{"name":"Carne de cerdo molida fina","amount":"600 g","pct":"30%"},{"name":"Sal","amount":"30 g","pct":"1.5%"},{"name":"Sal de cura #1 (Cure #1)","amount":"5 g","pct":"0.25%"},{"name":"Azúcar","amount":"3.3 g","pct":"0.17%"},{"name":"Ajo en polvo","amount":"2.7 g","pct":"0.14%"},{"name":"Pimienta negra","amount":"1.75 g","pct":"0.09%"},{"name":"Coriandro molido","amount":"1 g","pct":"0.05%"},{"name":"Paprika dulce","amount":"1 g","pct":"0.05%"},{"name":"Nuez moscada","amount":"0.2 g","pct":"0.01%"},{"name":"Agua helada","amount":"100 ml","pct":"5%"},{"name":"Mozzarella en cubos de 5–7 mm, muy fría","amount":"120 g","pct":"6%"},{"name":"Jalapeño encurtido, escurrido, seco y picado","amount":"140 g","pct":"7%"}],"proportionNote":"70% picada a cuchillo y 30% molida fina: esa es la receta. El grano grueso da la mordida artesanal y el molido fino la liga que sostiene todo. Si subes el molido fino se va hacia la emulsión y pierde el carácter; si lo bajas, la salchicha se desarma al tajarla.","charcuteroNote":"El porcentaje es el peso sobre los 2 kg de carne. Valores por kilo: sal 15 g, sal de cura #1 2,5 g, azúcar 1,65 g, ajo en polvo 1,35 g, pimienta negra 0,88 g, coriandro 0,5 g, paprika 0,5 g, nuez moscada 0,1 g, agua helada 50 ml, mozzarella 60 g y jalapeño 70 g. Los 2,5 g de Prague Powder #1 por kilo equivalen a 156 ppm de nitrito de entrada, el nivel estándar para un embutido cocido — y también el techo. Si tu sal de cura tiene otra concentración de nitrito, la dosis no es la misma.","steps":[{"n":"01","text":"Día 1 — Pica 1400 g de cerdo a cuchillo y muele finos los 600 g restantes. Todo muy frío."},{"n":"02","text":"Día 1 — Junta las dos texturas de carne en un bol."},{"n":"03","text":"Día 1 — Agrega la sal, el Cure #1, el ajo en polvo, la pimienta negra, el coriandro, la nuez moscada, la paprika dulce, el azúcar y los 100 ml de agua helada."},{"n":"04","text":"Día 1 — Amasa hasta desarrollar la liga: la masa tiene que quedar pegajosa y cohesiva, agarrándose a la mano. Aquí no se escatima."},{"n":"05","text":"Día 1 — Cubre y refrigera 8 horas."},{"n":"06","text":"Día 2 — Saca la masa y trabájala muy fría; si se ha templado, al congelador un rato antes de seguir."},{"n":"07","text":"Día 2 — Añade los 120 g de mozzarella en cubos de 5–7 mm y los 140 g de jalapeño encurtido, muy bien escurrido y secado."},{"n":"08","text":"Día 2 — Mezcla suavemente, solo hasta repartir: los cubos de queso y el jalapeño tienen que llegar enteros, sin romperse."},{"n":"09","text":"Día 2 — Embute sin sobrellenar la tripa. Deja margen: el queso fundido y el vapor van a empujar desde dentro."},{"n":"10","text":"Día 2 — Deja secar la superficie de la tripa hasta que esté seca al tacto, antes de meter humo."},{"n":"11","text":"Ahúma y cocina de forma progresiva, subiendo la temperatura por escalones y sin golpes de calor."},{"n":"12","text":"Controla con sonda en el centro de la pieza más gruesa y cocina hasta 72 °C internos, parejos en toda la salchicha."},{"n":"13","text":"Enfría rápido, seca la superficie y refrigera antes de cortar."}],"tips":[{"title":"El jalapeño, seco de verdad","description":"Escúrrelo y sécalo con papel hasta que no suelte nada. El líquido del encurtido se convierte en vapor dentro de la tripa, y ese vapor es presión."},{"title":"No sobrellenes la tripa","description":"Es el error que revienta estas salchichas. La mozzarella funde y ocupa más, el agua se evapora y no hay a dónde ir. Embute con margen."},{"title":"Calor progresivo, nunca de golpe","description":"Una temperatura alta de entrada funde el queso antes de que la masa cuaje: la tripa cede por el punto más lleno. Sube por escalones."},{"title":"El queso y el jalapeño, el Día 2","description":"El amasado del Día 1 es solo carne, condimentos y agua. Si metes las inclusiones ahí, se deshacen y engrasan la masa."},{"title":"La superficie seca antes del humo","description":"Con la tripa húmeda el humo se deposita manchado y el color sale disparejo."}],"cookMethods":[{"title":"Ahumada y cocida","description":"El método de la receta: humo progresivo, sin temperaturas excesivas, hasta 72 °C en el centro. Queda lista para comer."},{"title":"A la parrilla","description":"Ya cocida, solo dorar unos minutos a fuego medio. Fuego fuerte revienta la tripa por el queso."},{"title":"A la sartén, ya fría","description":"Tajadas gruesas doradas un minuto por lado; el queso se tuesta en el corte."}],"recommendations":["Escurre y seca el jalapeño encurtido antes de incorporarlo.","Mantén la masa muy fría los dos días.","Embute sin sobrellenar y deja secar la tripa antes del humo.","Sube la temperatura por escalones y mide con sonda hasta 72 °C internos."],"resultNote":"El resultado: una kielbasa de grano grueso, jugosa y picante, con los cubos de mozzarella fundidos y el jalapeño repartido a la vista en cada tajada. Textura artesanal, no industrial — se nota que la carne se picó a cuchillo.","finalQuote":"Meter queso en una tripa es un problema de presión, no de sabor. Se resuelve embutiendo con margen, secando el jalapeño y subiendo el calor despacio.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 290),
  ('lomo-curado', 'Lomo Curado (Lomo Embuchado)', 'jamones-curados', '{"España","Curado"}', '/recipes/lomo-curado.jpg', 'España · 1,2 kg', 'bridar-un-jamon', $receta${"slug":"lomo-curado","name":"Lomo Curado (Lomo Embuchado)","description":"El curado de pimentón por excelencia — lomo de cerdo entero, adobado y embuchado, madurado semanas al aire.","image":"/recipes/lomo-curado.jpg","tags":["España","Curado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Lomo de cerdo entero, adobado y madurado al aire.","intro":"El lomo embuchado es uno de los curados enteros más queridos de España: una pieza de lomo de cerdo, la más magra y noble, cubierta en un adobo de pimentón, ajo y orégano y curada entera durante semanas. A diferencia de un embutido picado, aquí no hay dónde esconder un mal adobo — la pieza entera exige precisión en la sal y control durante todo el curado. El resultado es una carne firme, de un rojo intenso veteado de pimentón, que se corta en lonchas finas y perfumadas.","stats":[{"label":"Rendimiento base","value":"1.2 kg"},{"label":"Tipo","value":"Curado en seco, pieza entera"},{"label":"Nivel","value":"Intermedio"},{"label":"Curado","value":"3–4 semanas (versión larga: hasta 90 días)"},{"label":"Formato","value":"Embuchado en tripa o malla"},{"label":"Condiciones","value":"12–15 °C, 75–80% humedad"}],"details":[{"title":"Origen","description":"Lomo de cerdo entero, la pieza más magra y noble, adobada sin picar."},{"title":"Textura","description":"Firme y compacta, de un rosa intenso a rojo profundo tras el curado."},{"title":"Sabor","description":"Pimentón dulce y picante al frente, con ajo y orégano de fondo."}],"quote":"El lomo no perdona: una pieza entera no tiene dónde esconder un mal adobo.","ingredientsNote":"El adobo se aplica sobre la pieza entera, no sobre carne picada. La sal de cura es obligatoria para una curación segura de varias semanas.","ingredients":[{"name":"Lomo de cerdo (pieza entera)","amount":"1200 g","pct":"100%"},{"name":"Sal","amount":"31 g","pct":"2.6%"},{"name":"Sal de cura (nitrificante, #2)","amount":"3 g","pct":"0.25%"},{"name":"Pimentón dulce","amount":"36 g","pct":"3%"},{"name":"Pimentón picante","amount":"12 g","pct":"1%"},{"name":"Ajo fresco triturado","amount":"18 g","pct":"1.5%"},{"name":"Orégano seco","amount":"4 g","pct":"0.3%"},{"name":"Azúcar","amount":"6 g","pct":"0.5%"},{"name":"Aceite de oliva (para el adobo)","amount":"20 ml","pct":"1.7%"}],"proportionNote":"El pimentón al 4% total (dulce y picante) es lo que define el color y el sabor característico; el aceite liga el adobo para que se adhiera bien a la pieza.","charcuteroNote":"El porcentaje es el peso sobre el peso de la pieza de lomo. Valores por kilo: sal 26 g, sal de cura 2.5 g, pimentón dulce 30 g, pimentón picante 10 g, ajo 15 g, orégano 3 g, azúcar 5 g.","steps":[{"n":"01","text":"Limpia el lomo de grasa y nervios sobrantes, dejando la pieza entera."},{"n":"02","text":"Frota la pieza con sal y sal de cura; deja en frío (0–4 °C) 24–48 h para que penetre."},{"n":"03","text":"Lava el exceso de sal y seca bien la pieza."},{"n":"04","text":"Prepara el adobo mezclando pimentones, ajo, orégano, azúcar y aceite hasta formar una pasta espesa."},{"n":"05","text":"Cubre toda la pieza con el adobo, asegurando que penetre en cada rincón."},{"n":"06","text":"Embucha en tripa natural o envuelve en malla, atando bien para compactar."},{"n":"07","text":"Cura colgado a 12–15 °C y 75–80% de humedad durante 3–4 semanas (o hasta 90 días para un curado más intenso)."}],"tips":[{"title":"Pieza entera, cuidado extra","description":"Al no estar picada, cualquier zona mal curada queda expuesta; controla bien la sal y el frío inicial."},{"title":"Adobo generoso","description":"Cubre bien toda la superficie; el pimentón no solo da sabor, también protege durante el curado."},{"title":"Cuelga sin que se toque","description":"Deja espacio entre piezas para que el aire circule parejo y el curado sea uniforme."}],"cookMethods":[{"title":"En lonchas finas","description":"Curado, se corta en lonchas muy finas y se sirve a temperatura ambiente, solo o con pan."},{"title":"En tabla","description":"Combina bien con quesos curados y encurtidos en una tabla de embutidos."}],"recommendations":["Usa una pieza de lomo de buena calidad, sin exceso de grasa externa.","No omitas la sal de cura en un curado de varias semanas.","Controla temperatura y humedad durante todo el proceso.","Deja que repose sin prisas: el lomo mejora con el tiempo."],"resultNote":"El resultado: una pieza firme, de un rojo intenso veteado de pimentón, que se corta en lonchas finas y perfumadas. Sencillez y paciencia, la fórmula de siempre.","finalQuote":"El lomo embuchado demuestra que a veces la mejor charcutería es la más simple: una buena pieza, un buen adobo y tiempo.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 300),
  ('cecina-de-leon', 'Cecina de León', 'jamones-curados', '{"España","Curado","Ahumado"}', '/recipes/cecina-de-leon.jpg', 'España · 3 kg', 'bridar-un-jamon', $receta${"slug":"cecina-de-leon","name":"Cecina de León","description":"El curado de vacuno por excelencia — salada, ahumada con leña de roble y curada más de 7 meses. Intensa y oscura.","image":"/recipes/cecina-de-leon.jpg","tags":["España","Curado","Ahumado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Vacuno salado, ahumado con roble y curado largo.","intro":"La cecina de León es el gran curado de vacuno español: una pieza de la extremidad trasera de la res, perfilada, salada en seco, ahumada con leña de roble o encina durante casi dos semanas y curada un mínimo de siete meses — doce en su versión reserva. El resultado recuerda al jamón en su aspecto tostado y en la paciencia que exige, pero con el carácter fibroso y ahumado propio del vacuno. Un curado que no se apresura: siete meses son el mínimo, no el máximo.","stats":[{"label":"Rendimiento base","value":"3 kg"},{"label":"Tipo","value":"Curado, salado y ahumado"},{"label":"Nivel","value":"Avanzado"},{"label":"Salazón","value":"24–48 h según peso"},{"label":"Ahumado","value":"12–16 días, leña de roble o encina"},{"label":"Curado","value":"Mínimo 7 meses (Reserva: 12 meses)"}],"details":[{"title":"Origen","description":"Pieza de la extremidad trasera de la res (contra o babilla), perfilada y desgrasada."},{"title":"Textura","description":"Fibrosa y firme, con un aspecto exterior tostado similar al jamón."},{"title":"Sabor","description":"Intenso y ahumado, con un fondo salado profundo que se suaviza con el corte fino."}],"quote":"La cecina no se apresura: siete meses son el mínimo, no el máximo.","ingredientsNote":"El salado es en seco, a diferencia de muchos embutidos en salmuera. La sal de cura es clave para un curado seguro de varios meses.","ingredients":[{"name":"Contra o babilla de ternera (pieza entera)","amount":"3000 g","pct":"100%"},{"name":"Sal gruesa","amount":"78 g","pct":"2.6%"},{"name":"Sal de cura (nitrificante, #2)","amount":"7.5 g","pct":"0.25%"},{"name":"Pimienta negra molida (opcional, para frotar antes del ahumado)","amount":"9 g","pct":"0.3%"}],"proportionNote":"La cecina de León tradicional lleva solo sal — sin más condimento que el ahumado y el tiempo. La sal de cura es la única incorporación moderna para un curado seguro tan largo.","charcuteroNote":"El porcentaje es el peso sobre el peso de la pieza. Valores por kilo: sal 26 g, sal de cura 2.5 g, pimienta negra (opcional) 3 g. Nada más — la simplicidad es la clave del curado tradicional.","steps":[{"n":"01","text":"Perfila la pieza, retirando grasa y nervios hasta dejar una forma limpia."},{"n":"02","text":"Cubre por completo en sal gruesa y sal de cura; deja en salazón 24–48 h en frío según el peso."},{"n":"03","text":"Lava el exceso de sal bajo agua fría y seca bien la pieza."},{"n":"04","text":"Deja asentar colgada en frío varios días para que la sal se reparta de forma uniforme."},{"n":"05","text":"Ahúma en frío con leña de roble o encina durante 12–16 días."},{"n":"06","text":"Cuelga a curar en un lugar fresco y ventilado (10–15 °C) un mínimo de 7 meses."},{"n":"07","text":"Para la versión reserva, extiende el curado hasta 12 meses."}],"tips":[{"title":"Sal justa, no de más","description":"Un exceso de sal en el salazón inicial arruina el equilibrio; calcula bien el tiempo según el peso de la pieza."},{"title":"Ahumado con roble o encina","description":"La madera define el aroma característico; evita maderas resinosas que amarguen la carne."},{"title":"Paciencia de meses","description":"Los siete meses mínimos no son un capricho — es el tiempo que necesita la pieza para curar en profundidad."}],"cookMethods":[{"title":"En lonchas finísimas","description":"Se corta lo más fino posible, a temperatura ambiente, para apreciar su textura y aroma ahumado."},{"title":"Con aceite de oliva","description":"Un hilo de aceite de oliva virgen realza su sabor sin taparlo."}],"recommendations":["Elige una pieza de vacuno de buena calidad y bien perfilada.","Respeta el tiempo de salazón según el peso — ni más ni menos.","No aceleres el ahumado ni el curado: son procesos de meses.","Guarda la pieza curada en un lugar fresco y ventilado."],"resultNote":"El resultado: una pieza de un rojo oscuro tostado, fibrosa y de aroma ahumado profundo — un curado de vacuno que rivaliza en carácter con el mejor jamón.","finalQuote":"La cecina de León recuerda que el buen curado no se mide en días, sino en meses — y a veces en años.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 310),
  ('panceta-ahumada', 'Panceta Curada y Ahumada (Bacon)', 'jamones-curados', '{"EE. UU.","Ahumado","Curado"}', '/recipes/panceta-ahumada.jpg', 'EE. UU. · 1,5 kg', 'sal-de-cura', $receta${"slug":"panceta-ahumada","name":"Panceta Curada y Ahumada (Bacon)","description":"El curado que se cocina — panceta de cerdo curada en seco y ahumada en frío con manzano, lista para la sartén.","image":"/recipes/panceta-ahumada.jpg","tags":["EE. UU.","Ahumado","Curado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Panceta curada en seco, ahumada y lista para cocinar.","intro":"El bacon casero no es solo panceta con humo: es una pieza curada varios días antes de ver el ahumadero. La panceta de cerdo se frota con una cura seca de sal, azúcar y sal de cura, reposa en frío hasta absorber el sabor, se seca sin tapar hasta formar una película pegajosa y se ahúma a baja temperatura con manzano o nogal. A diferencia del resto de curados de esta colección, esta pieza no se come cruda: siempre se cocina antes de servir.","stats":[{"label":"Rendimiento base","value":"1.5 kg"},{"label":"Tipo","value":"Curado en seco y ahumado en frío"},{"label":"Nivel","value":"Intermedio"},{"label":"Curado","value":"5–7 días en frío"},{"label":"Ahumado","value":"71–93 °C hasta 65–68 °C internos"},{"label":"Consumo","value":"Se cocina antes de comer"}],"details":[{"title":"Origen","description":"Panceta de cerdo (vientre), la pieza más grasa, curada entera."},{"title":"Textura","description":"Vetas marcadas de carne y grasa, firme tras el ahumado."},{"title":"Sabor","description":"Salado y ahumado, dulzón por el azúcar del curado."}],"quote":"El bacon no es solo panceta con humo: es una pieza curada días antes de ver el ahumadero.","ingredientsNote":"A diferencia de otros curados de esta colección, esta panceta se cocina siempre antes de comer — la sal de cura #1 es la indicada para curados que luego se cocinan o ahúman en caliente.","ingredients":[{"name":"Panceta de cerdo (con o sin piel)","amount":"1500 g","pct":"100%"},{"name":"Sal","amount":"39 g","pct":"2.6%"},{"name":"Sal de cura #1 (Prague Powder #1)","amount":"3.75 g","pct":"0.25%"},{"name":"Azúcar moreno","amount":"45 g","pct":"3%"},{"name":"Pimienta negra molida","amount":"4.5 g","pct":"0.3%"}],"proportionNote":"El azúcar moreno al 3% suaviza el salado y ayuda a dorar en la sartén. La sal de cura #1 (no #2) es la correcta aquí porque esta pieza se ahúma en caliente y se cocina — no cura meses al aire.","charcuteroNote":"El porcentaje es el peso sobre el peso de la panceta. Valores por kilo: sal 26 g, sal de cura #1 2.5 g, azúcar moreno 30 g, pimienta negra 3 g.","steps":[{"n":"01","text":"Mezcla sal, sal de cura #1, azúcar y pimienta; frota bien toda la pieza."},{"n":"02","text":"Cura en una bolsa cerrada en frío (0–4 °C) 5–7 días, volteando cada día."},{"n":"03","text":"Enjuaga el exceso de curado bajo agua fría y seca con papel."},{"n":"04","text":"Deja secar sin tapar en la nevera 12–24 h hasta que la superficie quede pegajosa (la película que fija el humo)."},{"n":"05","text":"Ahúma en frío o a baja temperatura (71–93 °C) con manzano, nogal o cerezo, hasta 65–68 °C internos."},{"n":"06","text":"Deja enfriar y reposar en frío antes de cortar en lonchas."},{"n":"07","text":"Cocina siempre antes de comer — a la sartén o al horno hasta dorar."}],"tips":[{"title":"Voltea cada día","description":"Durante el curado, voltea la pieza a diario para que la sal y el curado penetren parejo."},{"title":"Forma la película antes de ahumar","description":"El secado en frío sin tapar crea una superficie pegajosa que retiene mejor el humo."},{"title":"No te pases de temperatura","description":"Un ahumado demasiado caliente cuece la grasa antes de tiempo; mantente en 71–93 °C."}],"cookMethods":[{"title":"A la sartén","description":"En lonchas finas, a fuego medio hasta dorar y quedar crujiente en los bordes."},{"title":"Al horno","description":"Sobre rejilla a 190 °C, 15–20 min, para un dorado parejo sin tanta grasa salpicada."}],"recommendations":["Cura siempre en frío, nunca a temperatura ambiente.","No omitas la sal de cura #1 en un ahumado en caliente.","Deja formar la película pegajosa antes de ahumar.","Cocina siempre esta pieza antes de comerla — a diferencia de un curado tradicional, no se come cruda."],"resultNote":"El resultado: lonchas vetadas de carne y grasa, con un ahumado suave y un salado justo — el bacon casero no se parece al de bolsa.","finalQuote":"El bacon es la prueba de que curar no siempre significa comer crudo: a veces el curado es solo el primer paso.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 320),
  ('jamon-selva-negra', 'Jamón Curado y Ahumado (Estilo Selva Negra)', 'jamones-curados', '{"Alemania","Curado","Ahumado"}', '/recipes/jamon-selva-negra.jpg', 'Alemania · 4 kg', 'bridar-un-jamon', $receta${"slug":"jamon-selva-negra","name":"Jamón Curado y Ahumado (Estilo Selva Negra)","description":"El jamón que se ahúma — pierna de cerdo curada en seco con enebro, ahumada en frío sobre abeto y madurada semanas.","image":"/recipes/jamon-selva-negra.jpg","tags":["Alemania","Curado","Ahumado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Pierna de cerdo curada, ahumada en frío y madurada.","intro":"No todo jamón se cura solo con sal: el estilo Selva Negra (Schwarzwälder Schinken) necesita también el humo. Una pierna de cerdo deshuesada se cura en seco con pimienta, cilantro, ajo y bayas de enebro, se ahúma en frío sobre madera de abeto o pícea durante varios días y madura semanas más hasta redondear su sabor. El proceso completo ronda los tres meses, y el resultado es un jamón de color rojo intenso que se corta fino, como un curado tradicional, pero con un carácter ahumado que lo distingue del serrano o el ibérico.","stats":[{"label":"Rendimiento base","value":"4 kg"},{"label":"Tipo","value":"Curado en seco y ahumado en frío"},{"label":"Nivel","value":"Avanzado"},{"label":"Curado","value":"Aprox. 4 semanas"},{"label":"Ahumado","value":"En frío, sobre abeto o pícea, varios días"},{"label":"Maduración","value":"Varias semanas más (proceso total: hasta 3 meses)"}],"details":[{"title":"Origen","description":"Pierna de cerdo deshuesada, curada entera con especias de bosque."},{"title":"Textura","description":"Firme, de color rojo intenso con un borde de grasa blanca."},{"title":"Sabor","description":"Salado y aromático — enebro, cilantro y ajo de fondo, con un ahumado marcado."}],"quote":"No todo jamón se cura solo con sal: el de la Selva Negra necesita también el humo.","ingredientsNote":"A diferencia del jamón serrano o ibérico (solo sal), este lleva especias de bosque y un ahumado en frío que lo define. La sal de cura es clave para un curado seguro de varias semanas.","ingredients":[{"name":"Pierna de cerdo deshuesada","amount":"4000 g","pct":"100%"},{"name":"Sal","amount":"104 g","pct":"2.6%"},{"name":"Sal de cura (nitrificante, #2)","amount":"10 g","pct":"0.25%"},{"name":"Pimienta negra molida","amount":"12 g","pct":"0.3%"},{"name":"Bayas de enebro machacadas","amount":"16 g","pct":"0.4%"},{"name":"Cilantro molido","amount":"8 g","pct":"0.2%"},{"name":"Ajo en polvo","amount":"8 g","pct":"0.2%"},{"name":"Laurel molido","amount":"4 g","pct":"0.1%"}],"proportionNote":"El enebro es la especia que define este jamón frente a otros curados europeos — su aroma resinoso combina con el humo de abeto o pícea.","charcuteroNote":"El porcentaje es el peso sobre el peso de la pierna. Valores por kilo: sal 26 g, sal de cura 2.5 g, pimienta negra 3 g, enebro 4 g, cilantro 2 g, ajo 2 g, laurel 1 g.","steps":[{"n":"01","text":"Deshuesa la pierna y perfílala, dejando una pieza compacta."},{"n":"02","text":"Mezcla sal, sal de cura y especias; frota toda la pieza a conciencia."},{"n":"03","text":"Cura en frío (0–4 °C) unas 2 semanas, volteando y redistribuyendo la sal."},{"n":"04","text":"Retira el exceso de sal, lava y deja curar 2 semanas más para asentar."},{"n":"05","text":"Ahúma en frío (alrededor de 20–25 °C) sobre madera de abeto o pícea durante varios días, volteando la pieza."},{"n":"06","text":"Deja madurar colgada en un espacio fresco y ventilado varias semanas más."},{"n":"07","text":"El proceso completo, de inicio a fin, ronda los 3 meses."}],"tips":[{"title":"Enebro con moderación","description":"Es una especia potente; un exceso tapa el resto de aromas en lugar de realzarlos."},{"title":"Humo frío, no caliente","description":"El ahumado debe mantenerse frío para curar, no cocinar, la pieza — vigila la temperatura de la cámara."},{"title":"Voltea durante el ahumado","description":"Girar la pieza de arriba a abajo asegura un ahumado parejo en toda la superficie."}],"cookMethods":[{"title":"En lonchas finas","description":"Se come crudo, cortado muy fino, como un jamón serrano pero con un carácter ahumado marcado."},{"title":"En tabla fría","description":"Acompaña bien con pan de centeno, pepinillos y mostaza, al estilo centroeuropeo."}],"recommendations":["Deshuesa con cuidado para mantener la pieza compacta.","Respeta las dos fases de curado antes de pasar al ahumado.","Ahúma siempre en frío, nunca en caliente.","Deja madurar sin prisas — el sabor se redondea con las semanas."],"resultNote":"El resultado: un jamón de color rojo intenso, aromático a enebro y humo de bosque, que se corta fino y se come crudo como el mejor curado europeo.","finalQuote":"El jamón de la Selva Negra prueba que el humo también tiene lugar en la tradición del jamón curado.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 330),
  ('bresaola', 'Bresaola della Valtellina', 'jamones-curados', '{"Italia","Curado"}', '/recipes/bresaola.jpg', 'Italia · 1,5 kg', 'sal-de-cura', $receta${"slug":"bresaola","name":"Bresaola della Valtellina","description":"El curado magro de los Alpes — babilla de ternera en sal seca, especiada y madurada hasta el púrpura oscuro.","image":"/recipes/bresaola.jpg","tags":["Italia","Curado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Ternera curada en seco, sin ahumar, madurada en los Alpes.","intro":"La bresaola no necesita humo ni grasa: solo sal, especias y el aire frío de la montaña. Una pieza magra de ternera —babilla o contra— se cura en seco diez días con pimienta, ajo, canela, laurel y clavo, y madura colgada entre dos y cuatro meses a 12–18 °C, en el clima alpino que le da nombre. Al no tener grasa que la proteja, es una de las piezas más exigentes de curar: cualquier descuido en la humedad o la temperatura se nota. El resultado es una carne de un púrpura oscuro intenso, magra y de sabor especiado.","stats":[{"label":"Rendimiento base","value":"1.5 kg"},{"label":"Tipo","value":"Curado en seco, sin ahumar"},{"label":"Nivel","value":"Avanzado"},{"label":"Salazón","value":"10 días"},{"label":"Curado","value":"2–4 meses a 12–18 °C"},{"label":"Formato","value":"Pieza entera, embuchada en tripa o malla"}],"details":[{"title":"Origen","description":"Babilla o contra de ternera, una de las piezas más magras del animal."},{"title":"Textura","description":"Firme y compacta, de un color púrpura oscuro característico."},{"title":"Sabor","description":"Suave y especiado — canela, clavo y laurel de fondo, sin rastro de humo."}],"quote":"La bresaola no necesita humo ni grasa: solo sal, especias y el aire frío de la montaña.","ingredientsNote":"Es de los curados más magros de esta colección — por eso el control de temperatura y humedad durante la maduración es aún más importante.","ingredients":[{"name":"Babilla o contra de ternera (pieza entera)","amount":"1500 g","pct":"100%"},{"name":"Sal gruesa","amount":"39 g","pct":"2.6%"},{"name":"Sal de cura (nitrificante, #2)","amount":"3.75 g","pct":"0.25%"},{"name":"Pimienta negra en grano machacada","amount":"6 g","pct":"0.4%"},{"name":"Ajo en polvo","amount":"4.5 g","pct":"0.3%"},{"name":"Canela molida","amount":"1.5 g","pct":"0.1%"},{"name":"Laurel molido","amount":"1.5 g","pct":"0.1%"},{"name":"Clavo molido","amount":"0.75 g","pct":"0.05%"},{"name":"Vino tinto (opcional, para el frotado)","amount":"30 ml","pct":"2%"}],"proportionNote":"Las especias dulces —canela, clavo, laurel— son la firma de la bresaola frente a otros curados de vacuno; se usan en pequeñas cantidades para no tapar la carne.","charcuteroNote":"El porcentaje es el peso sobre el peso de la pieza. Valores por kilo: sal 26 g, sal de cura 2.5 g, pimienta 4 g, ajo 3 g, canela 1 g, laurel 1 g, clavo 0.5 g.","steps":[{"n":"01","text":"Perfila la pieza retirando grasa y nervios hasta dejarla limpia y compacta."},{"n":"02","text":"Mezcla sal, sal de cura y especias; frota bien toda la superficie."},{"n":"03","text":"Cura en frío (0–4 °C) 10 días, volteando y redistribuyendo la mezcla a diario."},{"n":"04","text":"Lava el exceso de sal y seca bien la pieza."},{"n":"05","text":"Embucha en tripa o envuelve en malla, atando para compactar."},{"n":"06","text":"Cuelga a curar a 12–18 °C con humedad alta (70–80%) durante 2 a 4 meses."},{"n":"07","text":"La pieza está lista cuando pierde un 35–40% de su peso inicial y el color es púrpura oscuro."}],"tips":[{"title":"Pieza magra, cuidado extra","description":"Al no tener grasa que la proteja, la bresaola es más sensible a un curado descontrolado; vigila humedad y temperatura de cerca."},{"title":"Voltea a diario en la salazón","description":"Asegura que la sal penetre parejo en toda la pieza durante los primeros 10 días."},{"title":"Pésala para saber cuándo está lista","description":"La pérdida de peso, no solo el tiempo, es el mejor indicador de que terminó el curado."}],"cookMethods":[{"title":"En carpaccio","description":"En lonchas finísimas, con aceite de oliva, limón y virutas de parmesano."},{"title":"En ensalada","description":"Con rúcula y parmesano, aprovechando su perfil magro y especiado."}],"recommendations":["Elige una pieza magra y bien perfilada, sin grasa externa.","Controla la humedad durante toda la maduración — es clave en una pieza tan magra.","No aceleres los 10 días de salazón inicial.","Pesa la pieza antes y después para verificar la pérdida de peso correcta."],"resultNote":"El resultado: una pieza de un púrpura oscuro intenso, magra y especiada, que se corta en lonchas casi transparentes — un curado alpino de una pureza única.","finalQuote":"La bresaola demuestra que un buen curado no necesita grasa ni humo: solo sal, especias precisas y el tiempo de la montaña.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 340),
  ('speck-alto-adige', 'Speck Alto Adige', 'jamones-curados', '{"Italia","Curado","Ahumado"}', '/recipes/speck-alto-adige.jpg', 'Italia · 2,5 kg', 'bridar-un-jamon', $receta${"slug":"speck-alto-adige","name":"Speck Alto Adige","description":"El punto medio entre jamón y ahumado — pierna de cerdo con especias alpinas, ahumada suave con haya y madurada meses.","image":"/recipes/speck-alto-adige.jpg","tags":["Italia","Curado","Ahumado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Cerdo curado, ahumado suave y madurado en la montaña.","intro":"El speck vive del equilibrio: poca sal, poco humo, mucho tiempo al aire libre. Una pierna de cerdo deshuesada se cura con especias alpinas —enebro, laurel, romero— sin superar el 5% de sal, se ahúma suave con madera de haya en sesiones breves y madura al menos 22 semanas en el aire fresco de la montaña, hasta perder cerca de un tercio de su peso. A medio camino entre el jamón crudo italiano y un jamón ahumado centroeuropeo, el speck no busca imponerse: busca equilibrarse.","stats":[{"label":"Rendimiento base","value":"2.5 kg"},{"label":"Tipo","value":"Curado, ahumado suave y madurado al aire"},{"label":"Nivel","value":"Avanzado"},{"label":"Curado","value":"Aprox. 3 semanas"},{"label":"Ahumado","value":"Suave, con madera de haya, baja temperatura"},{"label":"Maduración","value":"Mínimo 22 semanas al aire de montaña"}],"details":[{"title":"Origen","description":"Pierna de cerdo deshuesada, curada entera con especias alpinas."},{"title":"Textura","description":"Firme, con un borde de grasa blanca y color rojo oscuro al corte."},{"title":"Sabor","description":"Equilibrado — poca sal, poco humo, mucho aire de montaña, según su tradición."}],"quote":"El speck vive del equilibrio: poca sal, poco humo, mucho tiempo al aire libre.","ingredientsNote":"El principio del speck es usar poca sal y poco humo — la maduración al aire de montaña hace el resto del trabajo. La sal no debe superar el 5%.","ingredients":[{"name":"Pierna de cerdo deshuesada","amount":"2500 g","pct":"100%"},{"name":"Sal","amount":"65 g","pct":"2.6%"},{"name":"Sal de cura (nitrificante, #2)","amount":"6.25 g","pct":"0.25%"},{"name":"Pimienta negra molida","amount":"7.5 g","pct":"0.3%"},{"name":"Bayas de enebro machacadas","amount":"10 g","pct":"0.4%"},{"name":"Laurel molido","amount":"2.5 g","pct":"0.1%"},{"name":"Ajo en polvo","amount":"5 g","pct":"0.2%"},{"name":"Romero seco","amount":"2.5 g","pct":"0.1%"}],"proportionNote":"El enebro y el laurel son la firma alpina del speck; a diferencia del jamón de la Selva Negra, aquí el ahumado es mucho más suave y breve.","charcuteroNote":"El porcentaje es el peso sobre el peso de la pieza. Valores por kilo: sal 26 g, sal de cura 2.5 g, pimienta 3 g, enebro 4 g, laurel 1 g, ajo 2 g, romero 1 g.","steps":[{"n":"01","text":"Deshuesa la pierna y perfílala en una forma compacta y regular."},{"n":"02","text":"Mezcla sal, sal de cura y especias; frota bien toda la pieza."},{"n":"03","text":"Cura en frío (0–4 °C) unas 3 semanas, volteando periódicamente."},{"n":"04","text":"Lava el exceso de curado y seca bien la superficie."},{"n":"05","text":"Ahúma suave con madera de haya a baja temperatura, en sesiones breves y espaciadas."},{"n":"06","text":"Cuelga a madurar en un lugar fresco, seco y ventilado un mínimo de 22 semanas."},{"n":"07","text":"La pieza está lista cuando ha perdido cerca de un tercio de su peso inicial."}],"tips":[{"title":"Menos humo es más","description":"El speck no busca un ahumado intenso; unas pocas sesiones suaves con haya bastan para su carácter."},{"title":"El aire de montaña hace el trabajo","description":"Una maduración lenta en un espacio fresco y bien ventilado es más importante que la cantidad de sal o humo."},{"title":"No superes el 5% de sal","description":"Un exceso de sal tapa el equilibrio que define a este curado frente a otros jamones ahumados."}],"cookMethods":[{"title":"En lonchas finas","description":"Se come crudo, en lonchas muy finas, con pan y un vino blanco de montaña."},{"title":"En dados para guisar","description":"Aporta un fondo ahumado suave a sopas, guisos y platos de pasta."}],"recommendations":["Deshuesa con cuidado para mantener una pieza compacta y regular.","No excedas el 5% de sal en el curado.","Ahúma en sesiones suaves y espaciadas, nunca de forma intensa.","Respeta las 22 semanas mínimas de maduración al aire."],"resultNote":"El resultado: una pieza de rojo oscuro con un borde blanco de grasa, de sabor equilibrado entre el jamón crudo y el ahumado — ni uno ni otro, sino ambos a la vez.","finalQuote":"El speck demuestra que el ahumado, cuando es sutil, no compite con el curado — lo completa.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 350),
  ('magret-de-pato-curado', 'Magret de Pato Curado (Magret Séché)', 'jamones-curados', '{"Francia","Curado"}', '/recipes/magret-de-pato-curado.jpg', 'Francia · 800 g', 'sal-de-cura', $receta${"slug":"magret-de-pato-curado","name":"Magret de Pato Curado (Magret Séché)","description":"El jamón de pato francés — pechuga entera cubierta en sal, secada en frío hasta quedar firme y perfumada.","image":"/recipes/magret-de-pato-curado.jpg","tags":["Francia","Curado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Pechuga de pato en sal, secada al frío sin ahumar.","intro":"El magret curado es la puerta de entrada a los curados enteros: rápido, sin ahumar, y con resultado en pocas semanas. Una pechuga de pato entera se cubre por completo en sal durante doce horas, se envuelve en un paño limpio y se seca en la nevera dos o tres semanas hasta quedar firme al tacto, como un jamón curado en miniatura. Es el proceso más corto y accesible de esta colección — ideal para quien quiere probar el curado de piezas enteras antes de animarse con procesos de meses.","stats":[{"label":"Rendimiento base","value":"800 g"},{"label":"Tipo","value":"Curado en seco, sin ahumar"},{"label":"Nivel","value":"Principiante"},{"label":"Salazón","value":"12 h en sal"},{"label":"Secado","value":"2–3 semanas en frío, envuelto en tela"},{"label":"Formato","value":"Pieza entera, sin tripa ni malla"}],"details":[{"title":"Origen","description":"Pechuga de pato entera, con su capa de grasa característica."},{"title":"Textura","description":"Firme al tacto, similar a un jamón curado en miniatura."},{"title":"Sabor","description":"Intenso y ligeramente dulzón, con la grasa aportando jugosidad al corte."}],"quote":"El magret curado es la puerta de entrada a los curados enteros: rápido, sin ahumar, y con resultado en pocas semanas.","ingredientsNote":"Es el curado más rápido y accesible de esta colección — ideal para empezar en las piezas enteras antes de animarse con procesos de meses.","ingredients":[{"name":"Pechuga de pato (magret), con grasa","amount":"800 g","pct":"100%"},{"name":"Sal gruesa","amount":"21 g","pct":"2.6%"},{"name":"Sal de cura (nitrificante, #2), opcional","amount":"2 g","pct":"0.25%"},{"name":"Pimienta negra molida","amount":"4 g","pct":"0.5%"},{"name":"Tomillo seco (opcional)","amount":"2 g","pct":"0.25%"}],"proportionNote":"A diferencia de los curados largos de esta colección, el magret no necesita una mezcla compleja: sal, tiempo y frío bastan. La sal de cura es opcional dado lo corto del proceso, pero ayuda a fijar el color.","charcuteroNote":"El porcentaje es el peso sobre el peso de la pechuga. Valores por kilo: sal 26 g, sal de cura 2.5 g, pimienta 5 g, tomillo 2.5 g.","steps":[{"n":"01","text":"Seca bien las pechugas y retira el exceso de nervio, dejando la grasa intacta."},{"n":"02","text":"Cubre por completo en sal (y sal de cura si se usa) en un recipiente; deja en frío 12 h."},{"n":"03","text":"Retira de la sal, enjuaga el exceso y seca a conciencia con papel."},{"n":"04","text":"Frota con pimienta (y tomillo si se usa) y envuelve en un paño limpio y seco."},{"n":"05","text":"Deja secar en la parte alta de la nevera 2–3 semanas, revisando que el paño se mantenga seco."},{"n":"06","text":"La pieza está lista cuando se siente firme al tacto en toda su superficie."},{"n":"07","text":"Guarda envuelta en la nevera y consume en las semanas siguientes."}],"tips":[{"title":"No cures de más","description":"12 h de sal son suficientes para una pieza tan pequeña; pasarte de tiempo la deja demasiado salada."},{"title":"Paño limpio y seco","description":"Cambia el paño si se humedece durante el secado — la humedad atrapada favorece el moho no deseado."},{"title":"Empieza por aquí","description":"Si es tu primer curado de pieza entera, el magret es el más rápido y perdona más que un jamón o una bresaola."}],"cookMethods":[{"title":"En lonchas finas","description":"Se come crudo, en lonchas finas, solo o con higos y un buen pan."},{"title":"En tabla","description":"Combina con quesos suaves y mermeladas dulces, al estilo francés."}],"recommendations":["No excedas las 12 h de salazón en una pieza tan pequeña.","Usa un paño limpio y transpirable durante el secado.","Revisa la pieza cada pocos días para detectar cualquier signo de humedad excesiva.","Consume en las semanas siguientes al curado — no es un curado de larga conservación."],"resultNote":"El resultado: una pechuga firme y perfumada, con la grasa aportando jugosidad — el curado entero más rápido y accesible para empezar.","finalQuote":"El magret curado prueba que no hace falta esperar meses para disfrutar de una pieza entera bien curada.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 360),
  ('bundnerfleisch', 'Bündnerfleisch (Viande des Grisons)', 'jamones-curados', '{"Suiza","Curado"}', '/recipes/bundnerfleisch.jpg', 'Suiza · 1,5 kg', 'sal-de-cura', $receta${"slug":"bundnerfleisch","name":"Bündnerfleisch (Viande des Grisons)","description":"El curado alpino suizo — res en sal, vino blanco y hierbas, secada y prensada hasta su forma rectangular.","image":"/recipes/bundnerfleisch.jpg","tags":["Suiza","Curado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Vacuno curado y prensado, secado al aire alpino.","intro":"El prensado es lo que distingue al Bündnerfleisch: no solo se cura, se le da forma con el tiempo. Una pieza magra de res —cadera o paleta— se cura cerca del punto de congelación durante tres a cinco semanas con sal, vino blanco y hierbas alpinas, reacomodándose con frecuencia para que el curado penetre parejo. Después se seca al aire entre 9 y 14 °C, prensándose periódicamente hasta adquirir su característica silueta rectangular. Es la charcutería suiza que también acompaña al raclette.","stats":[{"label":"Rendimiento base","value":"1.5 kg"},{"label":"Tipo","value":"Curado en seco, prensado y secado al aire"},{"label":"Nivel","value":"Avanzado"},{"label":"Curado","value":"3–5 semanas, cerca de 0 °C"},{"label":"Secado","value":"Al aire, 9–14 °C, con prensados periódicos"},{"label":"Formato","value":"Pieza prensada, de forma rectangular"}],"details":[{"title":"Origen","description":"Cadera o paleta de res, sin grasa ni nervios."},{"title":"Textura","description":"Compacta y de forma rectangular por el prensado periódico."},{"title":"Sabor","description":"Salado y herbal, con un toque del vino blanco del curado."}],"quote":"El prensado es lo que distingue al Bündnerfleisch: no solo se cura, se le da forma con el tiempo.","ingredientsNote":"El vino blanco no es un detalle menor: forma parte del curado, no solo del sabor. La sal de cura es necesaria para las 3–5 semanas de curado en frío.","ingredients":[{"name":"Cadera o paleta de res (pieza entera)","amount":"1500 g","pct":"100%"},{"name":"Sal gruesa","amount":"39 g","pct":"2.6%"},{"name":"Sal de cura (nitrificante, #2)","amount":"3.75 g","pct":"0.25%"},{"name":"Vino blanco seco","amount":"60 ml","pct":"4%"},{"name":"Cebolla en polvo","amount":"4.5 g","pct":"0.3%"},{"name":"Hierbas alpinas secas (tomillo, romero, laurel)","amount":"4.5 g","pct":"0.3%"}],"proportionNote":"El vino blanco al 4% aporta acidez y aroma al curado inicial; las hierbas alpinas son intercambiables según la tradición familiar de cada valle.","charcuteroNote":"El porcentaje es el peso sobre el peso de la pieza. Valores por kilo: sal 26 g, sal de cura 2.5 g, vino blanco 40 ml, cebolla 3 g, hierbas 3 g.","steps":[{"n":"01","text":"Perfila la pieza retirando toda la grasa y los nervios visibles."},{"n":"02","text":"Mezcla sal, sal de cura, cebolla y hierbas; frota la pieza y rocía con el vino blanco."},{"n":"03","text":"Cura en un recipiente cerrado, cerca de 0 °C, durante 3–5 semanas, reacomodando la pieza cada varios días."},{"n":"04","text":"Retira del curado, escurre y seca bien la superficie."},{"n":"05","text":"Cuelga a secar al aire a 9–14 °C."},{"n":"06","text":"Prensa la pieza periódicamente durante el secado para darle su forma rectangular característica."},{"n":"07","text":"Continúa el secado hasta que la pieza esté firme y compacta en toda su superficie."}],"tips":[{"title":"Cerca del punto de congelación","description":"El curado inicial debe hacerse casi a 0 °C; unos grados de más aceleran el proceso de forma descontrolada."},{"title":"Reacomoda con frecuencia","description":"Mover la pieza durante el curado asegura que la sal y el vino se repartan parejo."},{"title":"El prensado da la forma","description":"Sin los prensados periódicos, la pieza no adquiere su característica silueta rectangular."}],"cookMethods":[{"title":"En lonchas finísimas","description":"Se come crudo, cortado muy fino, tradicionalmente junto al raclette."},{"title":"En tabla con raclette","description":"Acompaña el queso raclette fundido, junto a jamón y verduras encurtidas."}],"recommendations":["Cura siempre cerca de 0 °C, nunca a temperatura de nevera estándar.","Reacomoda la pieza cada varios días durante el curado.","Prensa con regularidad durante el secado para lograr la forma correcta.","Sécalo en un espacio bien ventilado a 9–14 °C."],"resultNote":"El resultado: una pieza rectangular, compacta y de sabor herbal, lista para corte finísimo — el curado alpino que también acompaña al raclette.","finalQuote":"El Bündnerfleisch demuestra que el curado también puede ser escultura: el tiempo y la presión le dan su forma final.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 370),
  ('biltong', 'Biltong', 'jamones-curados', '{"Sudáfrica","Curado"}', '/recipes/biltong.jpg', 'Sudáfrica · 1 kg', 'sal-de-cura', $receta${"slug":"biltong","name":"Biltong","description":"El curado exprés sudafricano — res en vinagre, sal y cilantro tostado, secada al aire en pocos días.","image":"/recipes/biltong.jpg","tags":["Sudáfrica","Curado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Tiras de res curadas con vinagre y secadas al aire.","intro":"El biltong es el curado más rápido de la colección — y el único que no necesita ni sal de cura ni ahumado. Tiras de res cortadas a favor de la fibra se cubren en vinagre, sal y cilantro tostado, curan una noche en frío y se cuelgan en un espacio bien ventilado apenas cuatro días, hasta que no ceden al apretarlas con los dedos. La acidez del vinagre, el frío inicial y un secado corto —de días, no de meses— bastan para su conservación segura, muy distinto de los curados largos del resto de esta colección.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Curado con vinagre, secado al aire"},{"label":"Nivel","value":"Principiante"},{"label":"Curado","value":"Una noche en frío"},{"label":"Secado","value":"Aprox. 4 días, con ventilación constante"},{"label":"Formato","value":"Tiras cortadas a favor de la fibra"}],"details":[{"title":"Origen","description":"Falda o cadera de res, cortada en tiras a favor de la fibra."},{"title":"Textura","description":"Firme por fuera, más tierna hacia el centro según el punto de secado."},{"title":"Sabor","description":"Ácido por el vinagre, con el cilantro tostado como sello distintivo."}],"quote":"El biltong es el curado más rápido de la colección — y el único que no necesita ni sal de cura ni ahumado.","ingredientsNote":"A diferencia de los curados largos de esta colección, el biltong tradicional no lleva sal de cura: el vinagre, el frío y un secado corto de días —no meses— bastan para su conservación segura.","ingredients":[{"name":"Falda o cadera de res (en tiras)","amount":"1000 g","pct":"100%"},{"name":"Vinagre de vino tinto o balsámico","amount":"100 ml","pct":"10%"},{"name":"Sal gruesa","amount":"26 g","pct":"2.6%"},{"name":"Cilantro en grano tostado y machacado","amount":"15 g","pct":"1.5%"},{"name":"Pimienta negra molida","amount":"5 g","pct":"0.5%"},{"name":"Azúcar morena (opcional)","amount":"10 g","pct":"1%"}],"proportionNote":"El cilantro tostado al 1.5% es la firma aromática del biltong — tuéstalo justo antes de machacarlo para un aroma más intenso.","charcuteroNote":"El porcentaje es el peso sobre el peso de la carne. Valores por kilo: vinagre 100 ml, sal 26 g, cilantro 15 g, pimienta 5 g, azúcar 10 g.","steps":[{"n":"01","text":"Tuesta los granos de cilantro en una sartén seca y machácalos grueso."},{"n":"02","text":"Corta la carne en tiras de 2–3 cm de grosor, a favor de la fibra."},{"n":"03","text":"Cubre las tiras con el vinagre, dejando que penetre unos minutos."},{"n":"04","text":"Frota con sal, cilantro tostado, pimienta y azúcar."},{"n":"05","text":"Cura tapado en frío durante una noche."},{"n":"06","text":"Cuelga las tiras en un espacio bien ventilado, con un ventilador si es posible."},{"n":"07","text":"Seca unos 4 días, hasta que no ceda al presionar con los dedos."}],"tips":[{"title":"Corta a favor de la fibra","description":"Facilita colgar las tiras y da la textura característica al morder, deshebrada en el sentido correcto."},{"title":"Ventilación, no calor","description":"El biltong seca con aire en movimiento, no con calor; un ventilador es más útil que una fuente de calor."},{"title":"Ajusta el punto a tu gusto","description":"Menos días de secado dan un biltong más tierno y húmedo; más días, uno más firme y concentrado."}],"cookMethods":[{"title":"Como snack","description":"Se come tal cual, cortado en lonchas finas o desmenuzado con los dedos."},{"title":"En ensaladas","description":"Rallado o en tiras finas, aporta un salado ácido intenso a ensaladas frescas."}],"recommendations":["Usa un vinagre de calidad — su acidez es parte de la conservación, no solo del sabor.","Cuelga las tiras sin que se toquen entre sí para un secado parejo.","Revisa a diario apretando la carne para encontrar tu punto ideal.","Consume en un plazo razonable y consérvalo en frío una vez seco."],"resultNote":"El resultado: tiras oscuras y aromáticas, ácidas por el vinagre y perfumadas de cilantro tostado — listas en días, no en meses.","finalQuote":"El biltong recuerda que no todo curado necesita esperar meses: a veces, el vinagre y el viento hacen el trabajo en días.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 380),
  ('pastrami', 'Pastrami Ahumado', 'jamones-cocidos', '{"EE. UU.","Ahumado","Especiado"}', '/recipes/pastrami.jpg', 'EE. UU. · 2,5 kg', 'bridar-un-jamon', $receta${"slug":"pastrami","name":"Pastrami Ahumado","description":"El curado que se ahúma y se cuece al vapor — pecho de res en salmuera, especiado en pimienta y cilantro, ahumado hasta tierno.","image":"/recipes/pastrami.jpg","tags":["EE. UU.","Ahumado","Especiado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Pecho de res en salmuera, ahumado y cocido al vapor.","intro":"El pastrami es el único curado de esta colección que termina en la olla de vapor, no en el cuchillo directo. Un pecho de res se cura varios días sumergido en una salmuera con sal de cura, se cubre en una costra generosa de pimienta y cilantro en grano, se ahúma hasta los 74 °C internos y finalmente se cuece al vapor hasta quedar tierno. De tradición judía-rumana y símbolo del deli neoyorquino, se sirve siempre caliente, en lonchas gruesas sobre pan de centeno — el broche especiado de esta colección de curados.","stats":[{"label":"Rendimiento base","value":"2.5 kg"},{"label":"Tipo","value":"Curado en salmuera, ahumado y al vapor"},{"label":"Nivel","value":"Avanzado"},{"label":"Curado","value":"5–10 días en salmuera"},{"label":"Ahumado","value":"Aprox. 135 °C, hasta 74 °C internos"},{"label":"Cocción final","value":"Al vapor, hasta tierno"}],"details":[{"title":"Origen","description":"Pecho de res (brisket), la pieza fibrosa clásica del ahumado americano."},{"title":"Textura","description":"Fibrosa y tierna tras el vapor, con una costra de pimienta y cilantro."},{"title":"Sabor","description":"Salado, especiado y ahumado, con un anillo rosado característico al corte."}],"quote":"El pastrami es el único curado de esta colección que termina en la olla de vapor, no en el cuchillo directo.","ingredientsNote":"Este es un curado en salmuera, no en seco — la sal de cura #1 es indispensable, disuelta en agua junto con sal y azúcar antes de sumergir la pieza.","ingredients":[{"name":"Pecho de res (brisket)","amount":"2500 g","pct":"100%"},{"name":"Agua fría (para la salmuera)","amount":"2500 ml","pct":"100%"},{"name":"Sal","amount":"175 g","pct":"7%"},{"name":"Sal de cura #1 (Prague Powder #1)","amount":"6.25 g","pct":"0.25%"},{"name":"Azúcar morena","amount":"65 g","pct":"2.6%"},{"name":"Pimienta negra en grano (para la costra)","amount":"30 g","pct":"1.2%"},{"name":"Cilantro en grano (para la costra)","amount":"30 g","pct":"1.2%"},{"name":"Ajo en polvo","amount":"10 g","pct":"0.4%"}],"proportionNote":"La salmuera lleva un 7% de sal sobre el peso de la carne, disuelta en igual peso de agua fría; la costra de pimienta y cilantro se aplica después, ya escurrida la pieza.","charcuteroNote":"El porcentaje es el peso sobre el peso del pecho de res. Valores por kilo: agua 1000 ml, sal 70 g, sal de cura #1 2.5 g, azúcar 26 g, pimienta 12 g, cilantro 12 g, ajo 4 g.","steps":[{"n":"01","text":"Disuelve la sal, la sal de cura #1 y el azúcar en el agua fría hasta obtener la salmuera."},{"n":"02","text":"Sumerge el pecho de res por completo, con un peso encima para que no flote."},{"n":"03","text":"Cura en frío 5–10 días, según el grosor de la pieza."},{"n":"04","text":"Retira de la salmuera, enjuaga bien y seca con papel."},{"n":"05","text":"Machaca pimienta y cilantro en grano y cubre toda la pieza formando la costra."},{"n":"06","text":"Ahúma a unos 135 °C hasta que la pieza alcance 74 °C internos."},{"n":"07","text":"Cuece al vapor hasta que esté tierna al pinchar, y sirve caliente en lonchas."}],"tips":[{"title":"Un peso sobre la pieza","description":"Mantén el pecho siempre sumergido en la salmuera; una zona fuera del líquido no cura bien."},{"title":"Costra generosa","description":"No escatimes en pimienta y cilantro — es la firma visual y de sabor del pastrami."},{"title":"El vapor final no es opcional","description":"Sin la cocción al vapor, la pieza queda fibrosa y dura; es lo que la hace tierna."}],"cookMethods":[{"title":"En sándwich","description":"Caliente, en lonchas gruesas, sobre pan de centeno con mostaza — el clásico neoyorquino."},{"title":"En tabla caliente","description":"Servido recién cortado, con encurtidos ácidos que equilibran lo especiado y ahumado."}],"recommendations":["Cura siempre en frío y con la pieza totalmente sumergida.","No omitas la sal de cura #1 en una salmuera de varios días.","Aplica la costra de especias generosa y justo antes de ahumar.","Termina siempre al vapor — es el paso que da la textura final."],"resultNote":"El resultado: lonchas fibrosas y tiernas, con un anillo rosado y una costra especiada — el único curado de la colección que se sirve caliente.","finalQuote":"El pastrami cierra la colección recordando que curar es solo el primer paso — a veces, el fuego y el vapor terminan el trabajo.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 390),
  ('jamon-ahumado-picante', 'Jamón Ahumado Picante (Bondiola)', 'jamones-curados', '{"Argentina","Ahumado","Picante"}', '/recipes/jamon-ahumado-picante.jpg', 'Argentina · 2 kg', 'bridar-un-jamon', $receta${"slug":"jamon-ahumado-picante","name":"Jamón Ahumado Picante (Bondiola)","description":"El curado picante que arrasa en redes — bondiola de cerdo curada 4 días, ahumada con leña de manzano y reposada hasta quedar jugosa.","image":"/recipes/jamon-ahumado-picante.jpg","tags":["Argentina","Ahumado","Picante"],"eyebrow":"Receta · Curados del mundo","subtitle":"Bondiola curada, ahumada con manzano y bien especiada.","intro":"Hay recetas que se vuelven virales por una razón: funcionan. Esta bondiola ahumada y picante es una de esas — un curado corto de apenas cuatro días, un ahumado lento con leña de manzano y un reposo de un día que termina de asentar todo el sabor. El resultado es una pieza jugosa, con el picante justo del chile quebrado y la paprika, y ese toque ahumado que la hace desaparecer de la tabla en minutos.","stats":[{"label":"Rendimiento base","value":"2 kg"},{"label":"Tipo","value":"Curado en seco y ahumado"},{"label":"Nivel","value":"Intermedio"},{"label":"Curado","value":"4 días en frío"},{"label":"Ahumado","value":"4 h, leña de manzano"},{"label":"Reposo","value":"24 horas"}],"details":[{"title":"Origen","description":"Bondiola de cerdo (cabecero de lomo), la pieza jugosa por excelencia para curar entera."},{"title":"Textura","description":"Jugosa y firme, con un interior tierno que se corta en lonchas gruesas."},{"title":"Sabor","description":"Picante moderado —chile quebrado y paprika— sobre un fondo ahumado a manzano."}],"quote":"No es casualidad que se venda como pan caliente: cuatro días de curado y cuatro horas de humo son toda la ciencia que necesita.","ingredientsNote":"El curado es corto —apenas cuatro días— porque la pieza se ahúma y se cocina después; la sal de cura #1 es la indicada para este tipo de proceso.","ingredients":[{"name":"Bondiola de cerdo (pieza entera)","amount":"2000 g","pct":"100%"},{"name":"Sal","amount":"36 g","pct":"1.8%"},{"name":"Sal de cura #1 (Prague Powder #1)","amount":"5 g","pct":"0.25%"},{"name":"Pimienta negra","amount":"2.4 g","pct":"0.12%"},{"name":"Ajo en polvo","amount":"3 g","pct":"0.15%"},{"name":"Coriandro molido","amount":"2 g","pct":"0.1%"},{"name":"Nuez moscada","amount":"0.5 g","pct":"0.025%"},{"name":"Azúcar","amount":"5 g","pct":"0.25%"},{"name":"Paprika dulce","amount":"2.4 g","pct":"0.12%"},{"name":"Chile quebrado (pepper flakes)","amount":"2 g","pct":"0.1%"},{"name":"Mostaza en polvo (opcional)","amount":"1.8 g","pct":"0.09%"}],"proportionNote":"El chile quebrado y la paprika dulce son los que definen el picante y el color; la nuez moscada y el coriandro quedan de fondo, apenas perceptibles pero necesarios.","charcuteroNote":"El porcentaje es el peso sobre el peso de la bondiola. Valores por kilo: sal 18 g, sal de cura #1 2.5 g, pimienta negra 1.2 g, ajo 1.5 g, coriandro 1 g, nuez moscada 0.25 g, azúcar 2.5 g, paprika 1.2 g, chile quebrado 1 g, mostaza en polvo 0.9 g (opcional).","steps":[{"n":"01","text":"Mezcla todas las especias con la sal y la sal de cura #1 hasta integrar bien."},{"n":"02","text":"Frota la bondiola entera con la mezcla, cubriendo toda la superficie."},{"n":"03","text":"Cura en frío (0–4 °C), en una bolsa o recipiente cerrado, durante 4 días, volteando la pieza cada día."},{"n":"04","text":"Retira del curado, enjuaga el exceso y seca bien con papel."},{"n":"05","text":"Deja secar sin tapar en la nevera unas horas, hasta que la superficie quede seca al tacto."},{"n":"06","text":"Ahúma en frío o a baja temperatura con leña de manzano durante 4 horas, hasta alcanzar 68–70 °C internos."},{"n":"07","text":"Retira del ahumador y deja reposar 24 horas en frío antes de cortar — este reposo termina de asentar el sabor y la textura."}],"tips":[{"title":"Voltea la pieza a diario","description":"Durante los 4 días de curado, girar la bondiola asegura que la sal y las especias penetren parejo."},{"title":"Manzano, no cualquier leña","description":"El manzano da un humo suave y dulce que no tapa el picante — evita maderas resinosas."},{"title":"No te saltes el reposo","description":"Las 24 horas de reposo son las que hacen que el corte quede jugoso y no se sienta seco."}],"cookMethods":[{"title":"En sándwich","description":"Caliente o frío, en lonchas gruesas sobre pan — el uso más pedido en redes."},{"title":"En tabla","description":"Frío, en lonchas finas, junto a encurtidos que corten lo picante."}],"recommendations":["No omitas la sal de cura #1 — es la que hace seguro un ahumado de solo 4 horas.","Cura siempre en frío y voltea la pieza a diario.","Deja secar la superficie antes de ahumar, para que el humo se adhiera mejor.","Respeta las 24 horas de reposo antes de cortar."],"resultNote":"El resultado: una bondiola jugosa, picante y ahumada, de esas que se acaban antes de que termines de armar la tabla.","finalQuote":"No es magia: es sal, humo y tiempo bien medidos — la fórmula de siempre, con un poco más de picante.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 400),
  ('jamon-de-bondiola-ahumado', 'Jamón de Bondiola Ahumado', 'jamones-cocidos', '{"Colombia","Ahumado","Curado"}', '/recipes/jamon-de-bondiola-ahumado.jpg', 'Colombia · 1 kg', 'bridar-un-jamon', $receta${"slug":"jamon-de-bondiola-ahumado","name":"Jamón de Bondiola Ahumado","description":"Bondiola curada, bridada como jamón y ahumada lento con leña de guayabo hasta los 75 °C internos — para cortar en lonchas finas.","image":"/recipes/jamon-de-bondiola-ahumado.jpg","tags":["Colombia","Ahumado","Curado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Bondiola convertida en jamón, con humo de guayabo.","intro":"¿Bondiola convertida en jamón? La duda es razonable: la bondiola es una pieza con vetas de grasa, nada que ver con el músculo magro y compacto del que se hacen los jamones clásicos. Y justo ahí está la gracia — esa grasa entreverada se funde durante el ahumado y deja una loncha jugosa donde un jamón de pierna quedaría seco. El proceso es de tres tiempos: se cura empacada al vacío, se brida para que tome la forma cilíndrica, y se ahúma lento con leña de guayabo hasta los 75 °C internos. El guayabo es lo que le da el carácter: un humo dulce y redondo, mucho menos agresivo que el de maderas duras como el roble.","stats":[{"label":"Rendimiento base","value":"1 kg"},{"label":"Tipo","value":"Curado en seco, ahumado y cocido"},{"label":"Nivel","value":"Intermedio"},{"label":"Curado","value":"1 día por cada kilo, al vacío"},{"label":"Ahumado","value":"Horno o barril a 200 °C, guayabo"},{"label":"Temperatura interna","value":"75 °C"},{"label":"Reposo","value":"Toda la noche, en frío"}],"details":[{"title":"Origen","description":"Bondiola de cerdo, el cabecero de lomo. Es la pieza con más grasa entreverada del cerdo, y por eso aguanta un ahumado largo sin secarse."},{"title":"Textura","description":"Firme pero jugosa. Al enfriarse la grasa se asienta y la pieza se deja cortar en lonchas finas sin desarmarse."},{"title":"Sabor","description":"Profundo y especiado, con el humo dulce del guayabo por encima. La paprika y el chile quebrado aportan color y un picante de fondo, no de golpe."}],"quote":"Yo también tenía mis dudas, hasta que lo probé: la grasa de la bondiola es justo lo que impide que un jamón ahumado quede seco.","ingredientsNote":"Estas cantidades son para 1 kg de bondiola. La mezcla completa son 27,35 g por kilo — pesa la pieza antes de nada, porque todo se calcula sobre su peso real y no sobre el que dice la receta.","ingredients":[{"name":"Bondiola de cerdo (pieza entera)","amount":"1000 g","pct":"100%"},{"name":"Sal fina","amount":"16,20 g","pct":"1,62%"},{"name":"Sal de cura #1 (Prague Powder #1)","amount":"2,5 g","pct":"0,25%"},{"name":"Azúcar","amount":"2,50 g","pct":"0,25%"},{"name":"Ajo en polvo","amount":"1,50 g","pct":"0,15%"},{"name":"Pimienta negra molida","amount":"1,20 g","pct":"0,12%"},{"name":"Paprika dulce","amount":"1,20 g","pct":"0,12%"},{"name":"Coriandro molido","amount":"1,00 g","pct":"0,10%"},{"name":"Chile quebrado","amount":"1,00 g","pct":"0,10%"},{"name":"Nuez moscada","amount":"0,25 g","pct":"0,025%"},{"name":"Pellets o astillas de guayabo","amount":"al gusto","pct":"—"},{"name":"Pita o cabuya para bridar","amount":"1 madeja","pct":"—"}],"proportionNote":"La sal fina al 1,62% es lo que hace que quede sabroso sin salarse, y la sal de cura al 0,25% es el estándar seguro y también el techo: nunca más. El azúcar no está para endulzar — redondea la sal y ayuda al color durante el ahumado.","charcuteroNote":"Valores por kilo de bondiola: sal fina 16,20 g · sal de cura #1 2,5 g · azúcar 2,50 g · ajo en polvo 1,50 g · pimienta negra 1,20 g · paprika dulce 1,20 g · coriandro 1,00 g · chile quebrado 1,00 g · nuez moscada 0,25 g. Total de la mezcla: 27,35 g por kilo. Aquí la sal de cura NO es opcional: la pieza pasa horas entre 30 y 60 °C mientras sube al centro, que es justo el rango donde el Clostridium botulinum trabaja mejor.","steps":[{"n":"01","text":"Pesa la bondiola y calcula la mezcla sobre ese peso. Si la pieza es grande, porciónala: una bondiola de 2 kg partida en dos cura en la mitad de tiempo y con mucha menos incertidumbre."},{"n":"02","text":"Mezcla todos los secos en un bol aparte antes de tocar la carne. Hacerlo así es lo único que garantiza que la sal de cura quede repartida pareja; echándolos uno a uno sobre la pieza siempre queda una zona con más."},{"n":"03","text":"Cubre la bondiola con la mezcla masajeando bien toda la superficie, incluidos los pliegues y las puntas. No sobra nada: todo lo que pesaste va sobre la carne."},{"n":"04","text":"Empaca al vacío y refrigera 1 día por cada kilo de carne. Voltea la bolsa una vez al día para que la salmuera que se forma bañe la pieza por los dos lados."},{"n":"05","text":"Saca la pieza, escúrrela y brídala con pita o cabuya dándole forma cilíndrica. Esa forma no es estética: una pieza pareja se cocina pareja y se corta en lonchas redondas."},{"n":"06","text":"Precalienta el barril u horno a 200 °C y mete la pieza. Añade pellets de guayabo cada 30 minutos para mantener el humo constante durante toda la cocción."},{"n":"07","text":"Cocina hasta que el CENTRO de la pieza marque 75 °C. Mide con termómetro en la parte más gruesa, nunca por tiempo: dos bondiolas del mismo peso pueden tardar distinto según su forma."},{"n":"08","text":"Enfría de golpe en agua con hielo hasta que la pieza esté fría al tacto. Este paso corta la cocción residual y es también seguridad: acorta el tiempo que la carne pasa en el rango de temperatura donde crecen las bacterias."},{"n":"09","text":"Envuelve en papel aluminio y deja reposar en la nevera toda la noche. Al día siguiente corta en lonchas finas — en caliente se desarma, en frío se corta limpio."}],"tips":[{"title":"El guayabo, en pellets o astillas","description":"El guayabo da un humo dulce y suave. Si no consigues, el manzano o el cerezo son los sustitutos más cercanos; evita maderas duras como el roble, que tapan las especias."},{"title":"Un día por kilo, no un día y ya","description":"El curado es proporcional al peso. Una pieza de 2 kg necesita 2 días; cortarlo a la mitad del tiempo deja el centro sin curar, que es donde importa."},{"title":"El termómetro manda sobre el reloj","description":"75 °C internos es el objetivo, no una duración. Si el horno es más chico o la pieza más gruesa, tardará más — y está bien."}],"cookMethods":[{"title":"En lonchas finas","description":"Frío y recién cortado, sobre tabla. Es como mejor se aprecia el humo del guayabo."},{"title":"En sándwich","description":"En lonchas algo más gruesas, apenas templado, con pan crujiente y poco más."}],"recommendations":["No omitas la sal de cura #1 — la pieza pasa horas en el rango de riesgo mientras sube al centro.","Pesa la bondiola antes de calcular nada: los porcentajes se aplican sobre el peso real.","Mide siempre la temperatura en el centro de la parte más gruesa, no cerca de la superficie.","El enfriado rápido en agua con hielo no es opcional: es parte de la seguridad, no del acabado.","Guarda la pieza entera y corta a medida que consumas — en loncha se seca mucho más rápido."],"resultNote":"El resultado: una pieza firme por fuera y jugosa por dentro, con el humo dulce del guayabo integrado en toda la carne y un picante de fondo que aparece al final del bocado.","finalQuote":"Bondiola, especias, humo de guayabo y paciencia. No hay atajo para ninguno de los cuatro.","finalQuoteCaption":"Consejo de El Charcu","doubts":{"onIntro":{"label":"¿Cuánto curo si mi pieza pesa más?","prompt":"La receta del Jamón de Bondiola Ahumado está para 1 kg y cura 1 día por kilo. Mi bondiola pesa otra cosa: ¿cómo reescalo los 27,35 g de mezcla y cuántos días la dejo al vacío? ¿Conviene partirla en dos?"},"onIngredients":{"label":"¿Por qué sal de cura #1 y no #2?","prompt":"El Jamón de Bondiola Ahumado lleva 2,5 g de sal de cura #1 por kilo. ¿Por qué la #1 y no la #2 si la pieza se cura antes de ahumar? ¿Qué pasa exactamente si me paso de esa cantidad, y se puede hacer sin ella?"},"onProcess":{"label":"¿Cómo sé que llegó a 75 °C de verdad?","prompt":"Estoy ahumando mi Jamón de Bondiola Ahumado en horno a 200 °C con pellets de guayabo. ¿Dónde clavo el termómetro exactamente, qué hago si la temperatura se estanca a mitad de camino, y cómo evito que la superficie se seque antes de que el centro llegue a 75 °C?"},"onServing":{"label":"Mándale una foto de cómo quedó","prompt":"Te voy a mandar una foto del corte de mi Jamón de Bondiola Ahumado para que me digas si el ahumado y la cocción quedaron bien, si el color por dentro es el que debería, y cuánto me aguanta en la nevera."}}}$receta$::jsonb, 410),
  ('hamburguesa-cerdo-europea', 'Hamburguesa de Cerdo Estilo Europeo', 'embutidos-frescos', '{"Europa","Fresco","Parrillero"}', '/recipes/hamburguesa-cerdo-europea.jpg', 'Europa · 5,6 kg', null, $receta${"slug":"hamburguesa-cerdo-europea","name":"Hamburguesa de Cerdo Estilo Europeo","description":"Carne de cerdo sazonada al estilo centroeuropeo —coriandro, nuez moscada y paprika— ligada con agua helada y formada en hamburguesas jugosas.","image":"/recipes/hamburguesa-cerdo-europea.jpg","tags":["Europa","Fresco","Parrillero"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Carne ligada con agua helada, formada a mano y a la parrilla.","intro":"La hamburguesa europea no busca impactar con picante: busca equilibrio. Esta carne de cerdo se sazona con un perfil clásico centroeuropeo —coriandro, nuez moscada y paprika de fondo— y se liga con agua muy fría hasta lograr una mezcla pegajosa y jugosa, la misma técnica detrás de las bratwurst y salchichas frescas de Alemania y Europa central, aplicada aquí a la hamburguesa. Se forma a mano y termina siempre en la parrilla o la sartén, jugosa por dentro y bien dorada por fuera.","stats":[{"label":"Rendimiento base","value":"5.6 kg"},{"label":"Tipo","value":"Fresco, formado a mano"},{"label":"Nivel","value":"Intermedio"},{"label":"Tiempo de preparación","value":"40 min"},{"label":"Reposo","value":"1–2 h en frío"},{"label":"Formato","value":"Hamburguesas de 150–200 g"}],"details":[{"title":"Origen","description":"Carne de cerdo molida entera, sin mezcla de grasa por separado — la base de las salchichas frescas centroeuropeas, aquí formada en hamburguesa."},{"title":"Textura","description":"Firme y ligada tras el amasado con agua helada; jugosa por dentro, bien dorada por fuera."},{"title":"Sabor","description":"Especiado suave —coriandro, nuez moscada y paprika de fondo— sin picante protagonista."}],"quote":"La hamburguesa europea no busca impactar con picante: busca equilibrio — un fondo especiado que acompaña, no que domina.","ingredientsNote":"El agua muy fría no es opcional: es la que liga la carne y le da la jugosidad característica de las salchichas y hamburguesas centroeuropeas.","ingredients":[{"name":"Carne de cerdo (molida)","amount":"5600 g","pct":"100%"},{"name":"Sal","amount":"93 g","pct":"1.66%"},{"name":"Sal de cura (Prague Powder #1)","amount":"14 g","pct":"0.25%"},{"name":"Ajo en polvo","amount":"10 g","pct":"0.18%"},{"name":"Pimienta negra molida","amount":"10 g","pct":"0.18%"},{"name":"Coriandro molido","amount":"7 g","pct":"0.13%"},{"name":"Nuez moscada","amount":"1.7 g","pct":"0.03%"},{"name":"Paprika dulce","amount":"7 g","pct":"0.13%"},{"name":"Azúcar","amount":"10 g","pct":"0.18%"},{"name":"Agua muy fría","amount":"390–420 ml","pct":"7–7.5%"}],"proportionNote":"El agua helada representa un 7–7.5% del peso de la carne — la proporción justa para ligar la mezcla sin aguarla. Agrégala poco a poco, nunca de un solo golpe.","charcuteroNote":"El porcentaje es el peso sobre el peso de la carne. Valores por kilo: sal 16.6 g, sal de cura #1 2.5 g, ajo 1.8 g, pimienta negra 1.8 g, coriandro 1.25 g, nuez moscada 0.3 g, paprika 1.25 g, azúcar 1.8 g, agua 70–75 ml.","steps":[{"n":"01","text":"Muele la carne de cerdo bien fría (0–2 °C) con disco de 6–8 mm."},{"n":"02","text":"Mezcla los secos: sal, sal de cura, ajo, pimienta, coriandro, nuez moscada, paprika y azúcar."},{"n":"03","text":"Incorpora los secos a la carne molida y amasa brevemente para distribuirlos parejo."},{"n":"04","text":"Añade el agua muy fría poco a poco, amasando hasta lograr una mezcla pegajosa y ligada — señal de que la proteína está bien extraída."},{"n":"05","text":"Mantén la mezcla entre 0–4 °C durante todo el proceso; si se calienta, pierde ligazón."},{"n":"06","text":"Forma hamburguesas de 150–200 g, compactando bien para que no se abran en la parrilla."},{"n":"07","text":"Deja reposar en frío 1–2 horas para que los sabores asienten y la forma se fije."},{"n":"08","text":"Cocina hasta 68–70 °C internos: a la parrilla o en sartén bien caliente, dorando parejo por ambos lados."}],"tips":[{"title":"Todo muy frío","description":"Carne, tazón y agua helados — si la mezcla se calienta durante el amasado, pierde ligazón y queda seca."},{"title":"Agua de a poco","description":"Incorpora el agua helada en tandas pequeñas; de golpe, la carne no la absorbe bien."},{"title":"Compacta bien al formar","description":"Una hamburguesa bien compactada no se desarma en la parrilla; presiona los bordes al final para sellarlos."}],"cookMethods":[{"title":"A la parrilla","description":"Directa sobre la brasa hasta dorar por fuera y llegar a 68–70 °C internos, sin aplastarla mientras cocina."},{"title":"En sartén","description":"A fuego medio-alto con una gota de aceite, tapada los últimos minutos para que el centro termine de cocinarse."}],"recommendations":["Mantén la carne y el agua bien frías durante todo el proceso.","No omitas la sal de cura #1 — da el color y la seguridad del producto cocido.","Agrega el agua helada gradualmente, sin apurar el amasado.","Cocina siempre hasta 68–70 °C internos antes de servir."],"resultNote":"El resultado: una hamburguesa jugosa y bien ligada, de sabor especiado suave — distinta a la clásica de res, con el carácter de la charcutería centroeuropea.","finalQuote":"A veces la mejor charcutería no es la más curada, sino la más bien ligada — sal, frío y agua helada, en las proporciones correctas.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 420),
  ('mortadela-de-pollo-casera', 'Mortadela de Pollo Casera', 'chorizos', '{"Rusia","Fresco"}', '/recipes/mortadela-de-pollo-casera.jpg', 'Rusia', 'embutir-un-chorizo', $receta${"slug":"mortadela-de-pollo-casera","name":"Mortadela de Pollo Casera","description":"El fiambre casero que se hace sin ahumador ni tripa — pollo cocido, gelatina y un toque de remolacha, moldeado en una botella y listo para rebanar.","image":"/recipes/mortadela-de-pollo-casera.jpg","tags":["Rusia","Fresco"],"eyebrow":"Receta · Chorizos del mundo","subtitle":"Pollo cocido, ligado con gelatina y moldeado en frío.","intro":"Esta no es la mortadela italiana de emulsión fina con pistachos — es su prima casera, conocida en Europa del Este como jamón de pollo: pechuga cocida en un caldo reducido y aromático, ligada con gelatina sin sabor y teñida con un toque de jugo de remolacha, moldeada en una botella cortada y cuajada en frío. Sin ahumador, sin tripa y sin sal de cura — solo caldo concentrado, gelatina y paciencia en la nevera. El resultado es un fiambre casero, suave y saludable, listo para rebanar en minutos.","stats":[{"label":"Rendimiento base","value":"800 g de pollo"},{"label":"Tipo","value":"Cocido y moldeado en frío"},{"label":"Nivel","value":"Fácil"},{"label":"Cocción","value":"1 h 30 min en caldo"},{"label":"Refrigeración","value":"Mínimo 4 horas"},{"label":"Formato","value":"Moldeado en botella cortada"}],"details":[{"title":"Origen","description":"Pechuga de pollo sin huesos, cocida en un caldo aromático con verduras y especias."},{"title":"Textura","description":"Firme al cortar y jugosa por dentro, gracias a la gelatina que liga el caldo concentrado."},{"title":"Sabor","description":"Suave y aromático —laurel, pimienta, coriandro y nuez moscada de fondo— con un toque de remolacha que da color, no sabor dominante."}],"quote":"No hace falta ahumador ni tripa para tener un fiambre casero — solo caldo, gelatina y un molde improvisado.","ingredientsNote":"El caldo reducido es la clave: concentra el sabor de las verduras y las especias antes de ligarse con la gelatina. Las verduras de la cocción se descartan — son solo para aromatizar.","ingredients":[{"name":"Carne de pollo (sin huesos)","amount":"800 g","pct":"100%"},{"name":"Caldo de pollo (reducido)","amount":"400 ml","pct":"50%"},{"name":"Gelatina sin sabor","amount":"30 g","pct":"3.75%"},{"name":"Sal","amount":"1 cucharada (≈18 g)","pct":"2.25%"},{"name":"Pimienta molida","amount":"½ cdta (≈1.2 g)","pct":"0.15%"},{"name":"Cilantro (semillas molidas)","amount":"½ cdta (≈1 g)","pct":"0.13%"},{"name":"Nuez moscada","amount":"½ cdta (≈1.1 g)","pct":"0.14%"},{"name":"Pimentón (paprika)","amount":"1 cdta (≈2.3 g)","pct":"0.29%"},{"name":"Jugo de remolacha (rallada)","amount":"3 cucharadas (≈45 ml)","pct":"5.6%"}],"proportionNote":"Para la cocción del caldo se usan además 1 zanahoria, 1 cebolla dorada, 2–3 hojas de laurel y 10 granos de pimienta negra — se descartan antes de licuar, solo aromatizan. Los 30 g de gelatina sobre 400 ml de caldo dan un cuajado firme pero fácil de rebanar.","charcuteroNote":"A diferencia del resto de la colección, esta receta no lleva sal de cura: al ser un fiambre cocido y refrigerado para consumo en pocos días, no necesita nitrificantes. Consérvala en frío y cómela en la semana.","steps":[{"n":"01","text":"Cubre el pollo (800 g, sin huesos) con agua fría en una olla."},{"n":"02","text":"Cuando rompa el hervor, agrega la zanahoria, la cebolla previamente dorada a fuego muy alto, el laurel, los granos de pimienta y la sal."},{"n":"03","text":"Cocina 1 hora 30 minutos a fuego bajo. Al mismo tiempo, hierve la remolacha aparte hasta que esté tierna."},{"n":"04","text":"Retira todos los sólidos del caldo; déjalo al fuego y redúcelo hasta unos 400 ml, para concentrar el sabor."},{"n":"05","text":"Descarta las verduras de la cocción y retira cualquier hueso o cartílago del pollo."},{"n":"06","text":"Disuelve la gelatina sin sabor en el caldo caliente, revolviendo hasta integrarla por completo."},{"n":"07","text":"Agrega el pollo cocido, la pimienta molida, el cilantro, la nuez moscada, la paprika y 3 cucharadas del jugo de la remolacha rallada."},{"n":"08","text":"Tritura todo con licuadora o batidora de mano hasta obtener una mezcla homogénea."},{"n":"09","text":"Vierte la mezcla en una botella plástica recta con el cuello cortado, que hará de molde."},{"n":"10","text":"Cubre la parte superior con film plástico y refrigera un mínimo de 4 horas, hasta que cuaje por completo."},{"n":"11","text":"Desmolda sacándola de la botella — tendrás un fiambre casero listo para cortar en rebanadas."}],"tips":[{"title":"Dora bien la cebolla","description":"Un buen dorado a fuego muy alto le da color y profundidad al caldo antes de cocinar el pollo."},{"title":"Reduce el caldo con paciencia","description":"Mientras más concentrado quede, más sabor y mejor cuajado tendrá el molde final."},{"title":"El jugo de remolacha es solo color","description":"Agrégalo de a poco: 3 cucharadas dan un tono rosado natural sin alterar el sabor."}],"cookMethods":[{"title":"En sándwich","description":"Frío, en lonchas finas, sobre pan — el uso más clásico de este fiambre casero."},{"title":"En tabla fría","description":"En rebanadas, junto a mostaza o encurtidos que le den un contrapunto ácido."}],"recommendations":["No te saltes la reducción del caldo — es lo que concentra el sabor de todo el fiambre.","Retira bien todos los huesos y cartílagos antes de triturar.","Refrigera un mínimo de 4 horas — cortarlo antes de que cuaje del todo lo deshace.","Consúmelo en los días siguientes: al no llevar sal de cura, su conservación es la de un fiambre fresco, no la de un curado."],"resultNote":"El resultado: un fiambre casero de pollo, suave y ligeramente rosado, firme al corte pero jugoso — sin ahumador, sin tripa y sin aditivos, listo en una tarde.","finalQuote":"A veces la mejor charcutería no necesita ni tripa ni ahumador — solo un buen caldo, gelatina y una botella cortada de molde.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 430),
  ('jamon-pierna-horneado', 'Jamón de Pierna Horneado', 'jamones-cocidos', '{"Argentina","Curado"}', '/recipes/jamon-pierna-horneado.jpg', 'Argentina', 'bridar-un-jamon', $receta${"slug":"jamon-pierna-horneado","name":"Jamón de Pierna Horneado","description":"El jamón cocido casero hecho al horno en vez de en agua — pierna de cerdo en salmuera, envuelta y horneada, prensada y reposada hasta quedar jugosa y lista para fetear.","image":"/recipes/jamon-pierna-horneado.jpg","tags":["Argentina","Curado"],"eyebrow":"Receta · Curados del mundo","subtitle":"Pierna en salmuera, horneada envuelta y prensada en frío.","intro":"De una pierna de cerdo de 4 kilos y medio, deshuesada y sin cuero, salen más de 2 kilos de jamón cocido casero — y realmente solo lleva tiempo, no es difícil. La pieza se sumerge en una salmuera de agua, azúcar, sal y sal de cura durante 5 a 6 días, se ata bien compacta y se cocina envuelta al horno en lugar del tradicional baño de agua a 80 °C. Un prensado y un reposo en frío toda la noche terminan el trabajo: al día siguiente aparece ese color rosado clásico y una textura jugosa, lista para cortar.","stats":[{"label":"Rendimiento base","value":"4 kg (pierna deshuesada)"},{"label":"Tipo","value":"Curado en salmuera, horneado y prensado"},{"label":"Nivel","value":"Intermedio"},{"label":"Salmuera","value":"5–6 días en frío"},{"label":"Horneado","value":"Envuelto, aprox. 3 h"},{"label":"Prensado","value":"Toda la noche en frío, con peso"}],"details":[{"title":"Origen","description":"Pierna o paleta de cerdo deshuesada y sin cuero — la pieza económica que rinde más de 2 kilos de jamón."},{"title":"Textura","description":"Jugosa, con vetas de grasa visibles al corte — cuanto más veteado, mejor calidad."},{"title":"Sabor","description":"Suave y clásico de jamón cocido, con el color rosado propio de la sal de cura, sin ahumar."}],"quote":"Cuantas más vetas y textura tenga el jamón, de mejor calidad es — si lo ves muy liso, desconfía.","ingredientsNote":"La clave está en que la pieza quede realmente bien sumergida en la salmuera, cubriendo todas sus partes — usa un peso encima si hace falta para que no flote.","ingredients":[{"name":"Pierna de cerdo (deshuesada, sin cuero)","amount":"4000 g","pct":"100%"},{"name":"Agua fría (para la salmuera)","amount":"4000 ml","pct":"100%"},{"name":"Sal","amount":"280 g","pct":"7%"},{"name":"Sal de cura #1 (Prague Powder #1)","amount":"10 g","pct":"0.25%"},{"name":"Azúcar","amount":"104 g","pct":"2.6%"}],"proportionNote":"La salmuera lleva un 7% de sal sobre el peso de la carne, disuelta en igual peso de agua fría — la misma lógica que un curado en salmuera de cualquier pieza grande. El azúcar suaviza el salado sin competir con el sabor del jamón.","charcuteroNote":"El porcentaje es el peso sobre el peso de la pierna. Valores por kilo: agua 1000 ml, sal 70 g, sal de cura #1 2.5 g, azúcar 26 g.","steps":[{"n":"01","text":"Deshuesa la pierna de cerdo y retira el cuero — es la parte más laboriosa, pero deja la carne lista para la salmuera."},{"n":"02","text":"Prepara la salmuera disolviendo el agua, la sal, la sal de cura y el azúcar."},{"n":"03","text":"Sumerge la pieza por completo en la salmuera, cubriendo todas sus partes; usa un peso encima si hace falta para que no flote."},{"n":"04","text":"Cura en la nevera entre 5 y 6 días."},{"n":"05","text":"Pasado el tiempo, retira la pieza, lávala bien bajo agua fría y sécala por completo."},{"n":"06","text":"Átala con rejilla para jamón o con hilo de matambre, dándole una forma compacta y cilíndrica."},{"n":"07","text":"Envuelve la pieza en una capa de papel manteca y otra de papel aluminio."},{"n":"08","text":"Hornea a temperatura controlada (similar a un baño de agua a 80 °C) durante unas 3 horas, hasta que la pieza alcance 68–70 °C internos."},{"n":"09","text":"Deja atemperar, ponle un peso encima y refrigera toda la noche."},{"n":"10","text":"Al día siguiente, desenvuelve: tendrás un jamón cocido de color rosado y textura jugosa, listo para fetear con máquina o cuchillo."}],"tips":[{"title":"La pieza debe quedar bien sumergida","description":"Cubre por completo con la salmuera y usa un peso si es necesario — cualquier zona expuesta al aire no cura parejo."},{"title":"El prensado marca la textura","description":"El peso y el reposo toda la noche en frío son los que le dan al jamón esa textura firme y fácil de fetear."},{"title":"Más vetas, mejor calidad","description":"Un jamón con vetas y textura visibles al corte es buena señal; si lo ves demasiado liso, algo no está bien."}],"cookMethods":[{"title":"Al horno (esta receta)","description":"Envuelto en papel manteca y aluminio, a temperatura controlada, unas 3 horas hasta el punto interno."},{"title":"A baño de agua (tradicional)","description":"Sumergido en agua a 80 °C hasta alcanzar el punto interno — el método clásico del jamón cocido."}],"recommendations":["No omitas la sal de cura — es la que da el color rosado clásico y la seguridad del curado.","Verifica que la pieza quede totalmente cubierta por la salmuera durante los 5–6 días.","No te saltes el prensado ni el reposo en frío — son los que dan la textura final.","Congela lo que no vayas a consumir pronto; rinde para varias semanas."],"resultNote":"El resultado: más de 2 kilos de jamón cocido casero, de color rosado clásico y textura jugosa — todo por una fracción de lo que cuesta comprarlo ya hecho.","finalQuote":"Es un 10.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 440),
  ('charqui-de-res', 'Charqui de Res (Beef Jerky)', 'jamones-curados', '{"Andes","Picante"}', '/recipes/charqui-de-res.jpg', 'Andes', 'sal-de-cura', $receta${"slug":"charqui-de-res","name":"Charqui de Res (Beef Jerky)","description":"El beef jerky andino, dulce y picante — carne de res marinada en miel y sriracha, deshidratada al horno hasta quedar firme y lista para picar.","image":"/recipes/charqui-de-res.jpg","tags":["Andes","Picante"],"eyebrow":"Receta · Curados del mundo","subtitle":"Res marinada en miel y sriracha, deshidratada al horno.","intro":"Más de 500 años de historia, resueltos con apenas cuatro ingredientes. El charqui es una de las formas más antiguas de conservar carne en los Andes, y esta versión le suma un giro moderno: miel, sriracha, sal y sal de ajo. La carne se marina bien impregnada, se acomoda en rejilla y se deshidrata al horno a baja temperatura durante varias horas, hasta quedar firme y correosa — el beef jerky casero, dulce, picante e intenso.","stats":[{"label":"Rendimiento base","value":"1 kg (carne fresca)"},{"label":"Tipo","value":"Marinado y deshidratado al horno"},{"label":"Nivel","value":"Fácil"},{"label":"Marinado","value":"6–12 h en frío"},{"label":"Deshidratado","value":"80 °C, 3–4 horas"},{"label":"Formato","value":"Láminas finas, a favor de la fibra"}],"details":[{"title":"Origen","description":"Carne de res muy magra, marinada con una mezcla dulce-picante inspirada en la tradición andina del charqui."},{"title":"Textura","description":"Firme y correosa — el charqui pierde gran parte de su humedad al deshidratarse en el horno."},{"title":"Sabor","description":"Dulce y picante, con un fondo salado de ajo — miel y sriracha en equilibrio."}],"quote":"Más de 500 años de historia, resueltos con apenas cuatro ingredientes.","ingredientsNote":"Al ser un marinado corto seguido de una deshidratación completa al horno —no un curado largo al aire— esta receta no necesita sal de cura.","ingredients":[{"name":"Carne de res (muy magra, sin grasa)","amount":"1000 g","pct":"100%"},{"name":"Sriracha","amount":"60 g","pct":"6%"},{"name":"Miel","amount":"40 g","pct":"4%"},{"name":"Sal","amount":"12 g","pct":"1.2%"},{"name":"Sal de ajo","amount":"8 g","pct":"0.8%"}],"proportionNote":"La miel y la sriracha, al 10% combinado, son las que definen el carácter dulce-picante del charqui; la sal y la sal de ajo sazonan sin dominar.","charcuteroNote":"El porcentaje es el peso sobre el peso de la carne. Valores por kilo: sriracha 60 g, miel 40 g, sal 12 g, sal de ajo 8 g. Sin sal de cura — el marinado corto y la deshidratación completa hacen el trabajo de conservación.","steps":[{"n":"01","text":"Corta la carne en láminas delgadas (aprox. 0.5 cm), a favor de la fibra, y retira toda la grasa visible."},{"n":"02","text":"Mezcla la miel, la sriracha, la sal y la sal de ajo hasta integrar bien."},{"n":"03","text":"Cubre cada lámina de carne con la marinada, asegurándote de que quede bien impregnada por ambos lados."},{"n":"04","text":"Marina en refrigeración entre 6 y 12 horas."},{"n":"05","text":"Escurre el exceso de marinada y acomoda las láminas sobre una rejilla, sin que se toquen entre sí."},{"n":"06","text":"Hornea a 80 °C durante 3 a 4 horas, volteando a la mitad del tiempo, hasta que la carne se vea completamente deshidratada."},{"n":"07","text":"Deja enfriar por completo antes de guardar — el charqui termina de firmar su textura mientras se enfría."}],"tips":[{"title":"Corta bien fino y parejo","description":"Láminas de grosor uniforme se deshidratan al mismo tiempo, sin puntos crudos ni sobrecocidos."},{"title":"Sin grasa","description":"La grasa no se deshidrata igual que la carne y puede enranciarse — retírala toda antes de marinar."},{"title":"Rejilla, no bandeja","description":"Apoyar las láminas sobre una rejilla deja que el aire circule por ambos lados y se sequen parejo."}],"cookMethods":[{"title":"Como snack","description":"Se come directo, en tiras, sin más preparación — el uso más clásico del charqui."},{"title":"En ensaladas o arroces","description":"En tiras finas o desmenuzado, aporta un salado dulce-picante intenso."}],"recommendations":["No satures el horno — deja espacio entre las láminas para que el aire circule.","Voltea las láminas a mitad de la cocción para un secado parejo.","Deja enfriar por completo antes de guardar, para que no genere humedad en el envase.","Guarda en un recipiente hermético; se conserva varias semanas en un lugar fresco."],"resultNote":"El resultado: charqui dulce, picante e intenso, de textura firme y correosa — de 1 kg de carne fresca salen unos 350–400 g de charqui seco, listo para comer directo o guardar para más tarde.","finalQuote":"Cuatro ingredientes y un poco de paciencia — la misma fórmula que los Andes usan desde hace 500 años, con un giro dulce-picante.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 450),
  ('queso-burrata', 'Queso Burrata Artesanal', 'quesos', '{"Italia","Fresco","Queso"}', '/recipes/queso-burrata.jpg', 'Italia', null, $receta${"slug":"queso-burrata","name":"Queso Burrata Artesanal","description":"La burrata casera de verdad — leche cruda pasteurizada en el fogón, hilada en mozzarella y rellena de stracciatella con nata, que se abre con el cuchillo y se derrama sobre el plato.","image":"/recipes/queso-burrata.jpg","tags":["Italia","Fresco","Queso"],"eyebrow":"Receta · Quesos artesanales","subtitle":"Mozzarella hilada rellena de stracciatella: el queso que se derrama.","intro":"La burrata nació en Puglia como una forma de aprovechar los recortes de la mozzarella: se hilaba una lámina fina, se rellenaba con las hebras sobrantes bañadas en nata y se cerraba en una bolsita atada por arriba, la testa. Ese es todo el secreto — por fuera es pasta hilada, firme y elástica; por dentro es stracciatella, hebras de queso empapadas en crema. Partimos de leche cruda, que es la que da el sabor de verdad, y la pasteurizamos nosotros mismos en el fogón: 63 °C sostenidos media hora, ni más ni menos. Hacerla en casa no requiere equipo de quesería, pero sí dos cosas que no se pueden improvisar: un termómetro y paciencia con los tiempos. El punto exacto de acidez y temperatura es lo que decide si la cuajada se estira como chicle caliente o se rompe en grumos.","stats":[{"label":"Rendimiento base","value":"4 L de leche → 4–5 burratas de ~120 g"},{"label":"Tipo","value":"Queso fresco de pasta hilada, relleno"},{"label":"Nivel","value":"Avanzado — el hilado tiene su técnica"},{"label":"Pasteurización","value":"63 °C sostenidos 30 min, en el fogón"},{"label":"Coagulación","value":"32 °C, 10–15 min de reposo"},{"label":"Cocción de cuajada","value":"41–42 °C"},{"label":"Maduración de acidez","value":"1–3 h a temperatura ambiente"},{"label":"Agua de hilado","value":"80–82 °C, salada a 20 g/L"},{"label":"Conservación","value":"0–4 °C, en su líquido, 2–3 días"}],"details":[{"title":"Origen","description":"Puglia, sur de Italia. Nació como aprovechamiento de los recortes de mozzarella, no como producto de lujo — aunque hoy lo sea."},{"title":"Textura","description":"Doble: una funda de pasta hilada elástica y brillante, y un centro de hebras blandas empapadas en nata que se derrama al cortar."},{"title":"Sabor","description":"Lácteo, dulce y limpio, con un punto ácido muy leve. Es un queso que sabe a leche fresca — por eso partir de leche cruda buena se nota tanto."},{"title":"Stracciatella","description":"El relleno: tiras de pasta hilada desgarradas a mano y mezcladas con nata. Literalmente significa \"desgarradita\". Se vende sola, y es media receta."}],"quote":"La burrata no se inventó para presumir: se inventó para no tirar los recortes de la mozzarella. Lo mejor de la cocina italiana casi siempre empieza así.","ingredientsNote":"Partimos de leche cruda y la pasteurizamos nosotros en el fogón — es el primer paso de la receta, no un trámite opcional. La burrata es un queso fresco, húmedo y sin maduración: no hay ninguna etapa posterior que elimine patógenos, así que la pasteurización es la única barrera del proceso. La pasteurización lenta a 63 °C es suave y respeta la aptitud quesera de la leche, a diferencia de la industrial. Por eso mismo NO hace falta cloruro de calcio: eso solo se añade cuando se trabaja con leche de tienda homogeneizada. Y ojo con el agua del cuajo: debe ser sin cloro (filtrada o embotellada), porque el cloro del grifo lo inactiva.","ingredients":[{"name":"Leche cruda de vaca entera (la pasteurizamos en el fogón)","amount":"4 L","pct":"100%"},{"name":"Zumo de limón colado","amount":"130 ml","pct":"3.25%"},{"name":"Cuajo líquido","amount":"1.5 ml","pct":"0.04%"},{"name":"Agua sin cloro (para diluir el cuajo)","amount":"50 ml","pct":"1.25%"},{"name":"Nata / crema de leche (mín. 35% MG)","amount":"180 ml","pct":"4.5%"},{"name":"Sal para el agua de hilado","amount":"40 g","pct":"20 g por litro"},{"name":"Sal fina para la stracciatella","amount":"3 g","pct":"0.075%"}],"proportionNote":"Los 130 ml de zumo de limón — unos 4 o 5 limones medianos, siempre colado — son la medida para 4 L de leche: llevan la cuajada al punto de acidez que permite el hilado. Cuélalo sin excepción, porque la pulpa deja grumos en la cuajada. La nata al 4,5% es lo que convierte unas hebras de queso en stracciatella de verdad: por debajo de eso el relleno queda seco y deja de derramarse.","charcuteroNote":"Valores por litro de leche: zumo de limón 33 ml, cuajo líquido 0,4 ml, nata 45 ml. Rendimiento aproximado: de 4 L de leche entera salen 450–550 g de pasta hilada, de los que unos 350 g van a las fundas y 100–150 g se desgarran para la stracciatella. El agua de hilado se sala a 20 g/L. Equivalencia útil si algún día quieres repetibilidad exacta lote a lote: esos 130 ml de limón aportan aproximadamente la misma acidez que 5 g de ácido cítrico.","steps":[{"n":"01","text":"Higieniza a fondo todo el equipo: olla, cuchillo largo, colador, cucharón y termómetro. Escáldalos con agua hirviendo y sécalos. En un queso fresco que no madura, la limpieza del primer minuto es la que se come al final."},{"n":"02","text":"Pasteuriza la leche cruda en el fogón: llévala a 63 °C y sostén esa temperatura 30 minutos, removiendo de vez en cuando. Usa olla de fondo grueso o baño maría, y fuego bajo — si se pega al fondo, arruina el sabor de todo el lote."},{"n":"03","text":"Enfría la leche rápido, con la olla dentro del fregadero lleno de agua y hielo, hasta bajar de 15 °C. Cuanto antes cruce la franja templada, mejor."},{"n":"04","text":"Con la leche ya fría, incorpora el zumo de limón colado removiendo suavemente. Añadir el ácido en frío es lo que evita que la leche se corte en grumos: nunca al revés."},{"n":"05","text":"Calienta lentamente hasta 32 °C, removiendo de vez en cuando. Sube despacio — un calentamiento brusco arruina la textura de la cuajada."},{"n":"06","text":"Disuelve el cuajo en los 50 ml de agua sin cloro, incorpóralo a la leche y remueve con dos o tres movimientos suaves de arriba abajo. No más: a partir de aquí la leche debe quedar completamente quieta."},{"n":"07","text":"Retira del fuego, tapa y deja reposar 10 a 15 minutos sin tocar ni mover la olla."},{"n":"08","text":"Comprueba el punto: introduce el cuchillo en ángulo y levanta un poco. Si la cuajada se abre en un corte limpio y suelta suero transparente, está lista. Si aún se ve lechosa, dale 5 minutos más."},{"n":"09","text":"Corta la cuajada en cubos de unos 2 cm con el cuchillo largo, en rejilla vertical y luego en diagonal. Deja reposar 5 minutos para que suelte suero."},{"n":"10","text":"Calienta muy despacio hasta 41–42 °C removiendo con suavidad. Los cubos se contraen, se vuelven más firmes y el suero se aclara."},{"n":"11","text":"Escurre la cuajada en un colador, reservando el suero caliente — te servirá para el hilado y para la ricotta."},{"n":"12","text":"Deja reposar la cuajada escurrida entre 1 y 3 horas a temperatura ambiente para que termine de acidificar. Este es el paso que más se salta la gente, y el que más fallos causa."},{"n":"13","text":"Haz la prueba de hilado: corta un trozo pequeño y sumérgelo en agua a 80 °C un minuto. Si se estira en una lámina brillante sin romperse, está listo. Si se rompe, deja reposar otros 30 minutos y vuelve a probar — nunca hiles el lote entero sin esta prueba."},{"n":"14","text":"Calienta agua (o el suero reservado) a 80–82 °C y sálala a razón de 20 g por litro. Ponte guantes: a esa temperatura la cuajada quema de verdad."},{"n":"15","text":"Sumerge porciones de cuajada 2 o 3 minutos, hasta que alcancen unos 57 °C internos, y estíralas y pliégalas sobre sí mismas hasta obtener una masa lisa y brillante. No amases de más: cada pliegue extra expulsa humedad y acerca el queso a la textura de goma."},{"n":"16","text":"Aparta un tercio de la pasta hilada para el relleno. Estíralo en un cordón fino de un centímetro, enfríalo en agua fría y desgárralo a mano en hebras muy delgadas."},{"n":"17","text":"Mezcla las hebras con la nata y la sal fina hasta que queden bien empapadas: eso es la stracciatella. Resérvala en frío mientras formas las fundas."},{"n":"18","text":"Con el resto de la pasta, aún caliente y maleable, forma discos de unos 15 cm, más gruesos en el centro y finos en el borde. Trabaja rápido: si se enfría, deja de estirarse."},{"n":"19","text":"Apoya el disco sobre la palma o dentro de un cuenco pequeño para formar una bolsa, rellena con la stracciatella sin excederte y cierra los bordes hacia arriba, sellando bien con los dedos. Si no sella, moja la unión un segundo en el agua caliente."},{"n":"20","text":"Retuerce el sobrante de arriba para formar la testa, el nudito característico de la burrata. Además de ser su firma visual, es lo que garantiza que la bolsa quede cerrada."},{"n":"21","text":"Sumerge las burratas en agua fría con hielo entre 10 y 15 minutos, hasta que la funda quede firme y brillante."},{"n":"22","text":"Guárdalas en refrigeración a 0–4 °C sumergidas en su propio líquido (suero ligeramente salado o agua con sal), en recipiente tapado. Sácalas 20–30 minutos antes de servir."}],"tips":[{"title":"El termómetro no es opcional","description":"Los cuatro números que deciden la receta son 63 °C para pasteurizar, 32 °C para cuajar, 41–42 °C para cocer la cuajada y 80–82 °C para hilar. A ojo no se acierta, y un error de cinco grados se nota en el resultado."},{"title":"Pasteurizar sin quemar la leche","description":"Fuego bajo, olla de fondo grueso y removido frecuente. Si tienes dudas, hazlo a baño maría: tarda más, pero es imposible que se pegue al fondo."},{"title":"Si no estira, no es culpa tuya: es la acidez","description":"Cuando la cuajada se rompe en vez de estirarse, casi siempre le falta reposo. Dale otros 30 minutos y vuelve a probar el trocito antes de hilar todo."},{"title":"Amasar de más la vuelve goma","description":"La pasta hilada se trabaja solo hasta que está lisa. Cada pliegue de más expulsa grasa y humedad, y el queso pasa de tierno a chicloso sin punto de retorno."},{"title":"El centro grueso, el borde fino","description":"Las bolsas se rompen por dos motivos: se estiran demasiado o se rellenan demasiado. Deja el centro con cuerpo y no la llenes hasta arriba."},{"title":"No tires el suero: hazte una ricotta","description":"El suero que reservaste, calentado a 85–90 °C con un chorro de limón, suelta la ricotta que le queda dentro. Dos quesos de una misma olla de leche."}],"cookMethods":[{"title":"Al natural, a temperatura ambiente","description":"La forma correcta. Sácala del frío 20–30 minutos antes: en frío la grasa está cuajada y no se aprecia nada. Aceite de oliva, sal en escamas y pimienta."},{"title":"Con tomate y albahaca","description":"El clásico de Puglia. Tomate maduro de verdad, aceite bueno y poco más — la burrata es la protagonista."},{"title":"Sobre pizza o pasta, fuera del horno","description":"Siempre al final, con el plato ya servido. Si la horneas se derrite y pierde justo lo que la hace burrata."},{"title":"Con embutido curado","description":"Su dulzor láctico corta la grasa y la sal de un buen curado — la razón por la que aparece en tantas tablas."}],"recommendations":["Pasteuriza siempre la leche cruda en el fogón antes de empezar: 63 °C sostenidos 30 minutos. Es la única barrera sanitaria que tiene este queso.","Enfría la leche por debajo de 15 °C antes de añadir el limón, y calienta después — nunca al revés.","Cuela el zumo de limón: la pulpa deja grumos en la cuajada.","Diluye el cuajo en agua sin cloro; el cloro del grifo lo inactiva.","Haz siempre la prueba de hilado con un trocito antes de comprometer todo el lote.","Trabaja el hilado con guantes: el agua va a 80 °C y la cuajada retiene el calor.","Extrema la higiene al rellenar y formar: la stracciatella se manipula a mano después del calentamiento, así que cualquier contaminación en ese punto ya no se elimina.","Consúmela en 2–3 días como máximo, siempre refrigerada y sumergida en su líquido."],"resultNote":"El resultado: una bolsita blanca y brillante, rematada por su testa, que al cortarla se abre y derrama hebras de queso bañadas en nata sobre el plato. Por fuera, la elasticidad de la mozzarella; por dentro, algo que está más cerca de la crema que del queso — y que ninguna burrata de supermercado con una semana de transporte a cuestas puede igualar.","finalQuote":"De 4 litros de leche y una tarde de trabajo salen cinco burratas. La diferencia con la del súper no es el precio: es que esta se come el mismo día que se hizo.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 460),
  ('kielbasa-bajo-sodio', 'Kielbasa Cocida de Bajo Sodio', 'chorizos', '{"Polonia","Fresco","Bajo sodio"}', '/recipes/kielbasa-bajo-sodio.jpg', 'Polonia', 'embutir-un-chorizo', $receta${"slug":"kielbasa-bajo-sodio","name":"Kielbasa Cocida de Bajo Sodio","description":"La kielbasa reformulada para dietas de sodio restringido — sin sal añadida, sin sal de cura y sin apio: una salchicha fresca cocida que se conserva por frío, no por curado.","image":"/recipes/kielbasa-bajo-sodio.jpg","tags":["Polonia","Fresco","Bajo sodio"],"eyebrow":"Receta · Formulaciones especiales","subtitle":"Kielbasa sin sal añadida ni sal de cura: producto cocido, no curado.","intro":"Esta no es una kielbasa curada con menos sal: es otra cosa, y conviene decirlo desde el principio. Al retirar la sal y la sal de cura #1 desaparecen las dos barreras que hacen segura una salchicha ahumada en frío o semicurada, así que la formulación se convierte en un embutido fresco que se cuece por completo y se conserva únicamente por refrigeración o congelación. A cambio, el sodio baja de unos 850 mg por 100 g a los ~60 mg que la propia carne de cerdo ya trae. Todo el trabajo de sabor lo hacen las especias, subidas casi al doble, más ajo fresco, mejorana y un toque ácido que engaña al paladar y devuelve parte de la sensación salada perdida.","stats":[{"label":"Rendimiento base","value":"1 kg de masa"},{"label":"Tipo","value":"Embutido fresco cocido (NO curado)"},{"label":"Nivel","value":"Intermedio"},{"label":"Sodio estimado","value":"≈ 60 mg / 100 g cocido"},{"label":"Reposo","value":"12 h en frío (0–4 °C)"},{"label":"Cocción","value":"Hasta 72 °C internos"},{"label":"Conservación","value":"0–4 °C, 3 días · −18 °C, 2 meses"},{"label":"Tipo de tripa","value":"Natural de cerdo, cal. 32–36 mm"}],"details":[{"title":"Objetivo","description":"Reducir el sodio al mínimo técnicamente posible — solo el que aporta la carne — sin inventar un método de curado que no existe sin sal."},{"title":"Textura","description":"Más quebradiza y granulosa que una kielbasa clásica: sin sal no hay extracción de miosina, así que no hay ligazón real. La fécula de papa y el picado fino compensan en parte."},{"title":"Sabor","description":"Aromático e intenso — ajo, mejorana, coriandro y paprika al doble de dosis — con un fondo ácido que sustituye la percepción salada."},{"title":"Diferencia con la kielbasa tradicional","description":"La tradicional lleva 18 g de sal y 2,5 g de Prague Powder #1 por kilo: color rosado, sabor curado, ahumado en frío seguro y vida útil larga. Esta no tiene nada de eso — es gris al corte, sabe a carne especiada y caduca como una hamburguesa fresca."}],"quote":"Sin sal no hay curado. Se puede hacer una kielbasa deliciosa con casi nada de sodio, pero hay que llamarla por su nombre: es un embutido fresco cocido.","ingredientsNote":"Sin sal y sin Prague Powder #1 esta masa NO está curada: no debe ahumarse en frío, ni fermentarse, ni secarse al aire, ni mantenerse entre 10 y 50 °C más de lo imprescindible. Se cuece hasta 72 °C internos y se refrigera o congela de inmediato. El apio en polvo queda excluido a propósito: aportaría nitrato y sodio, y no cumple el objetivo.","ingredients":[{"name":"Carne de cerdo magra (paleta)","amount":"800 g","pct":"80%"},{"name":"Tocino / grasa dorsal de cerdo","amount":"200 g","pct":"20%"},{"name":"Sal","amount":"0 g","pct":"0%"},{"name":"Sal de cura #1 (Prague Powder #1)","amount":"0 g","pct":"0%"},{"name":"Agua helada","amount":"60 g","pct":"6%"},{"name":"Fécula de papa (ligante sin sodio)","amount":"20 g","pct":"2%"},{"name":"Ajo fresco machacado","amount":"8 g","pct":"0.8%"},{"name":"Ajo en polvo (puro, sin sal)","amount":"3 g","pct":"0.3%"},{"name":"Vinagre de manzana","amount":"10 g","pct":"1%"},{"name":"Azúcar","amount":"2.5 g","pct":"0.25%"},{"name":"Pimienta negra molida","amount":"2.5 g","pct":"0.25%"},{"name":"Paprika dulce","amount":"2.5 g","pct":"0.25%"},{"name":"Coriandro molido","amount":"2 g","pct":"0.2%"},{"name":"Mostaza en polvo","amount":"1.5 g","pct":"0.15%"},{"name":"Chile quebrado","amount":"1.5 g","pct":"0.15%"},{"name":"Mejorana seca","amount":"1 g","pct":"0.1%"},{"name":"Nuez moscada","amount":"0.4 g","pct":"0.04%"}],"proportionNote":"80% magro y 20% grasa, como una kielbasa clásica: la grasa es aún más importante aquí, porque sin sal la masa no liga y es la grasa la que sostiene la jugosidad. Las especias van al doble de la fórmula tradicional (pimienta 1,2 → 2,5 g; ajo 1,5 → 3 g; paprika 1,2 → 2,5 g; coriandro 1 → 2 g), y el azúcar se mantiene en 2,5 g porque no aporta sodio y redondea el conjunto.","charcuteroNote":"Sodio estimado por kilo de masa: carne magra 800 g ≈ 456 mg (≈57 mg/100 g), tocino 200 g ≈ 60 mg, fécula y especias ≈ 5 mg, agua ≈ 10 mg. TOTAL ≈ 530 mg de sodio por kg de masa cruda. Con una merma de cocción del ~12% (≈880 g de producto terminado): ≈ 60 mg de sodio por 100 g. La misma kielbasa tradicional aporta ≈ 8.500 mg/kg (sal 18 g = 7.074 mg Na; Prague #1 2,5 g = 2,34 g de NaCl ≈ 920 mg Na; carne ≈ 516 mg), es decir ≈ 850 mg/100 g. La reducción es de aproximadamente el 94%. Nota: los valores de sodio de la carne son de tabla de composición y varían por corte y proveedor; para una etiqueta nutricional real hace falta un análisis de laboratorio del producto terminado (dato necesario para validar).","steps":[{"n":"01","text":"Enfría todo — carne, grasa, molino y bol — hasta rozar la congelación. Sin sal, la emulsión es frágil y el frío es la única ayuda que tienes."},{"n":"02","text":"Muele el magro con disco de 4–6 mm y la grasa con disco de 8 mm, por separado."},{"n":"03","text":"Mezcla las especias secas con la fécula de papa, y aparte disuelve el azúcar y el vinagre en el agua helada."},{"n":"04","text":"Amasa la carne con las especias y el ajo fresco, añadiendo el agua en dos veces, hasta que la masa se vea homogénea y ligeramente pegajosa. No esperes el hilo pegajoso de una masa salada: no va a aparecer."},{"n":"05","text":"Mantén la masa por debajo de 4 °C durante todo el amasado; si se calienta, para y devuélvela al frío."},{"n":"06","text":"Fríe una cucharada de prueba y ajusta especias — sin sal, el punto de sazón se juzga solo con la muestra cocida."},{"n":"07","text":"Embute en tripa natural de cerdo de 32–36 mm y forma las herraduras clásicas, sin apretar en exceso."},{"n":"08","text":"Reposa un máximo de 12 horas en refrigeración a 0–4 °C. Sin sal de cura, no alargues este reposo ni lo dejes a temperatura ambiente."},{"n":"09","text":"Cuece en agua a 78–80 °C (o al horno con vapor) hasta alcanzar 72 °C en el centro de la pieza, medidos con termómetro."},{"n":"10","text":"Si quieres humo, hazlo SOLO después de la cocción y en caliente: guayaba con una madera suave, a más de 90 °C de cámara y no más de 20–30 minutos, para dar aroma sin bajar la temperatura a la zona de riesgo."},{"n":"11","text":"Enfría en baño de agua con hielo hasta bajar por debajo de 10 °C en menos de una hora, seca y refrigera de inmediato a 0–4 °C."}],"tips":[{"title":"Sin Prague Powder #1, sin ahumado en frío","description":"El nitrito es la barrera que hace seguro mantener una masa cárnica horas entre 20 y 50 °C. Sin él, cualquier ahumado en frío o a baja temperatura es un riesgo de Clostridium botulinum. Cuece primero, ahúma después y en caliente."},{"title":"La acidez suple parte de la sal","description":"El vinagre, el ajo fresco y la mostaza aumentan la percepción de sazón. No bajan el pH lo suficiente como para ser una barrera de conservación — solo son sabor."},{"title":"Nada de cloruro de potasio","description":"Los sustitutos de sal a base de KCl aportan potasio, que muchas dietas renales restringen tanto o más que el sodio. No se usan aquí sin indicación médica."},{"title":"Espera una textura distinta","description":"La sal extrae miosina y liga la masa. Sin ella el corte es granuloso, más cerca de una salchicha de desayuno que de una kielbasa. Es el precio real del bajo sodio, no un defecto de la receta."}],"cookMethods":[{"title":"Pochada a 78–80 °C","description":"El método principal y el más seguro: cocción suave hasta 72 °C internos, controlada con termómetro."},{"title":"A la sartén o parrilla","description":"Ya cocida y fría, solo dorar unos minutos para reforzar el sabor tostado antes de servir."},{"title":"Ahumado en caliente, al final","description":"Guayaba y madera suave, sobre 90 °C de cámara, 20–30 minutos después de la cocción — aroma sin ventana de riesgo."}],"recommendations":["Este producto NO está curado: no lo seques, no lo fermentes y no lo ahúmes en frío.","Cocina siempre hasta 72 °C internos, verificados con termómetro.","Enfría rápido: por debajo de 10 °C en menos de una hora tras la cocción.","Refrigerado a 0–4 °C consúmelo en un máximo de 3 días; envasado al vacío y congelado a −18 °C, hasta 2 meses.","Si la masa cruda se queda a temperatura ambiente más de 2 horas, descártala.","Datos necesarios para validar cualquier afirmación de vida útil más larga: aw y pH medidos del producto terminado y análisis microbiológico. No los estimes.","Si el destinatario sigue una dieta médica de sodio restringido, revisa la formulación con su nutricionista o médico antes de producirla."],"resultNote":"El resultado: una salchicha gris-rosada al corte, aromática y jugosa, con un sodio de ~60 mg por 100 g frente a los ~850 mg de una kielbasa tradicional — una reducción cercana al 94%. No tiene el color rosado ni el sabor curado de la kielbasa polaca clásica, y no los tendrá: eso lo daba exactamente lo que aquí se ha quitado.","finalQuote":"Se puede quitar toda la sal de una kielbasa. Lo que no se puede es quitarla y seguir llamándola curada.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 470),
  ('bondiola-cocida-bajo-sodio', 'Bondiola Cocida Ahumada de Bajo Sodio', 'jamones-cocidos', '{"Argentina","Ahumado","Bajo sodio"}', '/recipes/bondiola-cocida-bajo-sodio.jpg', 'Argentina', 'bridar-un-jamon', $receta${"slug":"bondiola-cocida-bajo-sodio","name":"Bondiola Cocida Ahumada de Bajo Sodio","description":"Bondiola de cerdo con rub de especias, ahumada en caliente con naranjo y guayaba y cocida hasta el punto — sin sal, sin sal de cura y sin apio, con solo el sodio que trae la carne.","image":"/recipes/bondiola-cocida-bajo-sodio.jpg","tags":["Argentina","Ahumado","Bajo sodio"],"eyebrow":"Receta · Formulaciones especiales","subtitle":"Pieza entera ahumada y cocida: asado de cerdo, no jamón curado.","intro":"Un jamón cocido nace de una salmuera con sal y nitrito: eso es lo que le da el color rosado, el sabor característico y buena parte de su conservación. Si retiramos la sal, la salmuera pierde su motor —sin gradiente salino no hay difusión ni retención de agua— y el producto deja de ser jamón para convertirse en lo que realmente es: una bondiola entera especiada, ahumada en caliente y cocida al punto. Es una pieza magnífica, jugosa y fácil de fetear en frío, con un perfil ahumado cítrico y dulce de naranjo y guayaba. Y aporta unos 80 mg de sodio por 100 g frente a los 900–1.200 mg de un jamón cocido comercial.","stats":[{"label":"Rendimiento base","value":"1 kg de bondiola"},{"label":"Tipo","value":"Pieza entera ahumada y cocida (NO curada)"},{"label":"Nivel","value":"Intermedio"},{"label":"Sodio estimado","value":"≈ 80 mg / 100 g cocido"},{"label":"Reposo con especias","value":"12–24 h en frío (0–4 °C)"},{"label":"Ahumado","value":"Naranjo + guayaba, en caliente"},{"label":"Temperatura interna","value":"72 °C"},{"label":"Conservación","value":"0–4 °C, 4 días · −18 °C, 3 meses"}],"details":[{"title":"Objetivo","description":"Conservar el perfil artesanal de El Charcu —ajo, pimienta, paprika, mejorana, coriandro, nuez moscada— con el mínimo sodio posible: solo el intrínseco de la carne."},{"title":"Textura","description":"Jugosa y tierna por el veteado propio de la bondiola, pero menos ligada y con más merma que un jamón en salmuera: sin sal, la carne retiene menos agua."},{"title":"Sabor","description":"Cerdo asado especiado con un ahumado cítrico y frutal. Sabroso, pero claramente menos sazonado que un jamón; la sal se añade en el plato, no en la pieza."},{"title":"Diferencia con el jamón cocido tradicional","description":"El tradicional es una pieza salmuerizada con sal y Prague Powder #1: rosada, ligada, feteable y con vida útil larga. Esta es gris-marrón al corte, sabe a asado de cerdo y se comporta como una carne cocida cualquiera en la nevera."}],"quote":"Sin salmuera salada no hay jamón. Hay una bondiola cocida extraordinaria — que es exactamente lo que buscamos aquí.","ingredientsNote":"Formulación en seco, no en salmuera: sin sal no existe el gradiente que empuja la salmuera hacia el interior, así que sumergir la pieza en agua especiada solo la lavaría. El rub va a la superficie, sobre una fina capa de aceite que fija las especias. Sin sal de cura #1 no hay nitrito, no hay color rosado y no hay barrera antibotulínica: por eso el ahumado es siempre en caliente y nunca en frío. El apio en polvo queda excluido a propósito.","ingredients":[{"name":"Bondiola de cerdo (cabeza de lomo, entera)","amount":"1000 g","pct":"100%"},{"name":"Sal","amount":"0 g","pct":"0%"},{"name":"Sal de cura #1 (Prague Powder #1)","amount":"0 g","pct":"0%"},{"name":"Azúcar","amount":"10 g","pct":"1%"},{"name":"Aceite de oliva (fijador del rub)","amount":"10 g","pct":"1%"},{"name":"Paprika dulce","amount":"4 g","pct":"0.4%"},{"name":"Ajo en polvo (puro, sin sal)","amount":"4 g","pct":"0.4%"},{"name":"Pimienta negra molida","amount":"3 g","pct":"0.3%"},{"name":"Coriandro molido","amount":"2 g","pct":"0.2%"},{"name":"Ralladura de naranja","amount":"2 g","pct":"0.2%"},{"name":"Mejorana seca","amount":"1.5 g","pct":"0.15%"},{"name":"Nuez moscada","amount":"0.5 g","pct":"0.05%"}],"proportionNote":"El azúcar sube a 10 g por kilo (1%) — no aporta sodio, favorece el dorado en el ahumado y compensa parte del vacío que deja la sal. Las especias van a dosis de rub superficial, más altas que en una masa embutida, porque toda la sazón vive en la corteza.","charcuteroNote":"Sodio estimado por kilo: bondiola de cerdo 1000 g ≈ 600 mg (≈60 mg/100 g), especias, azúcar y aceite ≈ 5 mg. TOTAL ≈ 605 mg por kg de carne cruda. Con una merma de cocción del ~25% (≈750 g de producto terminado): ≈ 81 mg de sodio por 100 g. Referencia: un jamón cocido comercial se mueve en 900–1.200 mg/100 g, así que la reducción está en el entorno del 92%. Los valores de la carne provienen de tablas de composición y varían por corte y proveedor; para una etiqueta nutricional hace falta análisis de laboratorio del producto terminado (dato necesario para validar).","steps":[{"n":"01","text":"Limpia la bondiola de tejido conectivo grueso, dejando la grasa intramuscular — es la que va a sostener la jugosidad sin sal."},{"n":"02","text":"Mezcla todas las especias secas con el azúcar y la ralladura de naranja."},{"n":"03","text":"Unta la pieza con el aceite de oliva y cúbrela por completo con el rub, presionando para que se adhiera."},{"n":"04","text":"Ata la bondiola con hilo dándole forma cilíndrica compacta, para que cueza pareja y se fetee bien."},{"n":"05","text":"Reposa 12 a 24 horas en refrigeración a 0–4 °C, tapada. No alargues más este reposo: sin sal ni nitrito no hay nada que frene la flora."},{"n":"06","text":"Saca la pieza y déjala atemperar solo lo justo mientras el ahumador sube a temperatura — nunca más de una hora fuera del frío."},{"n":"07","text":"Ahúma en CALIENTE con naranjo y guayaba, cámara a 110–120 °C. Nada de ahumado en frío ni cámaras por debajo de 90 °C: sin nitrito esa franja es zona de riesgo."},{"n":"08","text":"Mantén la pieza en el ahumador hasta llegar a 72 °C en el centro, medidos con termómetro — unas 2 a 3 horas según el grosor. Si no tienes ahumador, hornea a 120 °C hasta la misma temperatura interna."},{"n":"09","text":"Reposa la pieza 20 minutos envuelta antes de tocarla, para que los jugos se redistribuyan."},{"n":"10","text":"Enfría rápido en baño de agua con hielo o en cámara: por debajo de 10 °C en menos de dos horas. Si la vas a fetear en frío, refrigera la pieza entera toda la noche antes de cortar."},{"n":"11","text":"Envasa al vacío o en recipiente hermético y guarda a 0–4 °C."}],"tips":[{"title":"El rub no cura: sazona","description":"Sin sal, las especias no penetran ni conservan. Todo el sabor vive en el primer centímetro, así que fetea fino para que cada rebanada lleve corteza."},{"title":"Pieza entera, riesgo menor que en un embutido","description":"En un músculo entero la contaminación es superficial y el ahumado en caliente la alcanza. En una masa molida está repartida por todo el interior — por eso la kielbasa exige más cuidado que esta bondiola."},{"title":"Naranjo y guayaba","description":"El perfil cítrico, frutal y dulce de la casa para piezas de cerdo. Aquí trabaja doble: aroma y percepción de sazón donde no hay sal."},{"title":"Termómetro, no reloj","description":"Sin sal ni nitrito, la cocción completa es la única barrera real que tiene este producto. 72 °C internos verificados, siempre."}],"cookMethods":[{"title":"Ahumado en caliente","description":"Naranjo y guayaba, cámara a 110–120 °C hasta 72 °C internos — método principal."},{"title":"Al horno","description":"Alternativa sin ahumador: 120 °C hasta la misma temperatura interna, con la pieza tapada las dos primeras horas."},{"title":"Feteada en frío","description":"Refrigerada toda la noche y cortada fina, funciona como fiambre de sándwich bajo en sodio."},{"title":"En caliente, al plato","description":"En rodajas gruesas, con la sal servida aparte para quien no tenga restricción."}],"recommendations":["Este producto NO está curado ni es jamón: es una bondiola cocida. No lo seques al aire ni lo ahúmes en frío.","Alcanza siempre 72 °C internos, verificados con termómetro.","Enfría por debajo de 10 °C en menos de dos horas tras la cocción.","Refrigerado a 0–4 °C consúmelo en un máximo de 4 días; envasado al vacío y congelado a −18 °C, hasta 3 meses.","El envasado al vacío en refrigeración crea un ambiente anaerobio: sin nitrito NO alarga la vida útil de forma segura, solo protege del secado. Trátalo igual que sin vacío.","Datos necesarios para validar cualquier vida útil mayor: aw y pH medidos del producto terminado y análisis microbiológico. No los estimes.","Si el destinatario sigue una dieta médica de sodio restringido, revisa la formulación con su nutricionista o médico antes de producirla."],"resultNote":"El resultado: una bondiola jugosa de corteza especiada y ahumado cítrico, feteable en frío, con ~80 mg de sodio por 100 g frente a los 900–1.200 mg de un jamón cocido comercial. Al corte es marrón-grisácea, no rosada: ese rosa lo daba el nitrito que aquí no está.","finalQuote":"Entre las dos formulaciones, la bondiola es la que menos pierde al quitarle la sal — una pieza entera bien ahumada se sostiene sola.","finalQuoteCaption":"Consejo de El Charcu"}$receta$::jsonb, 480)
